              <div>
                <label className="block text-sm font-semibold text-slate-700 mb-2">Data Sopralluogo</label>
                <div className="relative">
                  <Calendar className="absolute left-3 top-3 w-5 h-5 text-slate-400" />
                  <input 
                    type="date" 
                    className="w-full pl-10 pr-4 py-3 bg-slate-50 border border-slate-200 rounded-xl focus:ring-2 focus:ring-indigo-500 outline-none transition-all"
                    value={data.inspectionDate}
                    onChange={(e) => setData({...data, inspectionDate: e.target.value})}
                  />
                </div>
              </div>
            </div>
            <button 
              disabled={!isSetupValid}
              onClick={() => setStep(AppStep.PHOTOS)}
              className="mt-8 w-full bg-indigo-600 hover:bg-indigo-700 disabled:bg-slate-300 text-white font-bold py-4 rounded-xl shadow-lg shadow-indigo-200 flex items-center justify-center gap-2 transition-all active:scale-95"
            >
              Inizia Caricamento Foto <ChevronRight className="w-5 h-5" />
            </button>
          </div>
        )}

        {step === AppStep.PHOTOS && (
          <div className="space-y-6 animate-in fade-in slide-in-from-bottom-4 duration-500">
            <div className="flex items-center justify-between">
              <button 
                onClick={() => setStep(AppStep.SETUP)}
                className="flex items-center gap-2 text-slate-500 hover:text-slate-800 transition-colors"
              >
                <ChevronLeft className="w-5 h-5" /> Indietro
              </button>
              <span className="text-sm font-medium bg-indigo-50 text-indigo-700 px-3 py-1 rounded-full">
                {data.photos.length} Foto caricate
              </span>
            </div>

            <div className="grid grid-cols-1 gap-6">
              {data.photos.map((photo) => (
                <div key={photo.id} className="bg-white rounded-2xl shadow-sm border border-slate-200 overflow-hidden flex flex-col md:flex-row h-full">
                  <div className="md:w-1/3 relative bg-slate-100 min-h-[200px]">
                    <img src={photo.url} alt="Inspection" className="w-full h-full object-cover" />
                    <button 
                      onClick={() => removePhoto(photo.id)}
                      className="absolute top-2 right-2 p-2 bg-red-500 text-white rounded-full hover:bg-red-600 transition-all shadow-lg"
                    >
                      <Trash2 className="w-4 h-4" />
                    </button>
                  </div>
                  <div className="flex-1 p-6 space-y-4">
                    <div className="space-y-2">
                      <label className="text-xs font-bold uppercase tracking-wider text-slate-500">Dettagli Problema</label>
                      <div className="relative">
                        <textarea 
                          placeholder="Descrivi il problema riscontrato..."
                          className="w-full p-3 bg-slate-50 border border-slate-200 rounded-xl focus:ring-2 focus:ring-indigo-500 outline-none h-24 resize-none transition-all"
                          value={photo.issue}
                          onChange={(e) => updatePhoto(photo.id, { issue: e.target.value })}
                        />
                        <button 
                          onClick={() => handleAIEnhance(photo.id, photo.issue)}
                          disabled={!photo.issue || photo.isLoading}
                          className="absolute bottom-2 right-2 p-2 bg-white border border-slate-200 rounded-lg text-indigo-600 hover:bg-indigo-50 transition-all shadow-sm flex items-center gap-2 disabled:opacity-50"
                        >
                          {photo.isLoading ? <div className="animate-spin rounded-full h-4 w-4 border-2 border-indigo-600 border-t-transparent"></div> : <Wand2 className="w-4 h-4" />}
                          <span className="text-xs font-semibold">Migliora con IA</span>
                        </button>
                      </div>
                      {photo.aiPolishedIssue && (
                        <div className="mt-2 p-3 bg-indigo-50 border border-indigo-100 rounded-xl text-sm text-indigo-900 italic">
                          <span className="font-bold block mb-1">Versione Professionale:</span>
                          {photo.aiPolishedIssue}
                        </div>
                      )}
                    </div>
                    <div className="space-y-2">
                      <label className="text-xs font-bold uppercase tracking-wider text-slate-500">Fornitore di Riferimento</label>
                      <input 
                        type="text"
                        placeholder="Es: Idraulica Rossi, Ditta Edile Bianchi..."
                        className="w-full p-3 bg-slate-50 border border-slate-200 rounded-xl focus:ring-2 focus:ring-indigo-500 outline-none transition-all"
                        value={photo.supplier}
                        onChange={(e) => updatePhoto(photo.id, { supplier: e.target.value })}
                      />
                    </div>
                  </div>
                </div>
              ))}

              <label className="border-2 border-dashed border-slate-300 rounded-2xl p-12 flex flex-col items-center justify-center gap-4 bg-white hover:bg-slate-50 hover:border-indigo-400 cursor-pointer transition-all group">
                <div className="p-4 bg-slate-100 rounded-full text-slate-400 group-hover:text-indigo-500 group-hover:bg-indigo-50 transition-all">
                  <Camera className="w-8 h-8" />
                </div>
                <div className="text-center">
                  <p className="text-lg font-bold text-slate-700">Aggiungi altre foto</p>
                  <p className="text-sm text-slate-400">Trascina qui i file o clicca per sfogliare</p>
                </div>
                <input type="file" multiple accept="image/*" className="hidden" onChange={handleFileChange} />
              </label>
            </div>

            <div className="pt-8">
              <button 
                disabled={!isPhotosValid}
                onClick={handleGenerateReport}
                className="w-full bg-emerald-600 hover:bg-emerald-700 disabled:bg-slate-300 text-white font-bold py-4 rounded-xl shadow-lg shadow-emerald-200 flex items-center justify-center gap-2 transition-all active:scale-95"
              >
                Genera Report Finale <FileText className="w-5 h-5" />
              </button>
            </div>
          </div>
        )}

        {step === AppStep.REPORT && (
          <div className="space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-500">
            <div className="flex items-center justify-between print:hidden">
              <button 
                onClick={() => setStep(AppStep.PHOTOS)}
                className="flex items-center gap-2 text-slate-500 hover:text-slate-800 transition-colors"
              >
                <ChevronLeft className="w-5 h-5" /> Modifica Foto
              </button>
              <button 
                onClick={printReport}
                className="bg-slate-900 text-white px-6 py-3 rounded-xl hover:bg-slate-800 transition-all shadow-lg flex items-center gap-2"
              >
                <Download className="w-5 h-5" /> Scarica PDF / Stampa
              </button>
            </div>

            {/* The Actual Report Content */}
            <div id="final-report" className="bg-white shadow-2xl rounded-sm p-10 print:shadow-none print:p-0">
              <div className="border-b-2 border-indigo-600 pb-8 mb-8 flex flex-col md:flex-row md:justify-between md:items-end gap-4">
                <div>
                  <h1 className="text-3xl font-black text-slate-900 uppercase">Verbale di Sopralluogo</h1>
                  <p className="text-indigo-600 font-bold tracking-widest uppercase text-sm mt-1">Ispezione Tecnica Condominiale</p>
                </div>
                <div className="text-right">
                  <p className="text-slate-500 font-medium">Data Sopralluogo</p>
                  <p className="text-xl font-bold">{new Date(data.inspectionDate).toLocaleDateString('it-IT', { day: 'numeric', month: 'long', year: 'numeric' })}</p>
                </div>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-8 mb-12">
                <div className="bg-slate-50 p-6 rounded-xl border border-slate-100">
                  <h3 className="text-xs font-bold text-slate-400 uppercase tracking-widest mb-2">Immobile</h3>
                  <p className="text-2xl font-bold text-slate-800 underline decoration-indigo-200 underline-offset-4">{data.condoName}</p>
                </div>
                <div className="bg-indigo-50 p-6 rounded-xl border border-indigo-100">
                  <h3 className="text-xs font-bold text-indigo-400 uppercase tracking-widest mb-2">Stato Generale</h3>
                  <p className="text-slate-700 italic">
                    {isGeneratingSummary ? (
                      <span className="flex items-center gap-2 text-indigo-400 animate-pulse">
                        Generazione sintesi IA...
                      </span>
                    ) : summary}
                  </p>
                </div>
              </div>

              <div className="space-y-12">
                {data.photos.map((photo, index) => (
                  <div key={photo.id} className="break-inside-avoid">
                    <div className="flex items-center gap-3 mb-4">
                      <span className="bg-slate-900 text-white w-8 h-8 rounded-full flex items-center justify-center font-bold">{index + 1}</span>
                      <h4 className="text-lg font-bold text-slate-800">Rilievo Fotografico #{index + 1}</h4>
                    </div>
                    <div className="grid grid-cols-1 md:grid-cols-5 gap-6">
                      <div className="md:col-span-2">
                        <img src={photo.url} alt={`Rilievo ${index + 1}`} className="w-full rounded-lg shadow-md border border-slate-200" />
                      </div>
                      <div className="md:col-span-3 space-y-6">
                        <div>
                          <h5 className="text-xs font-bold text-slate-400 uppercase tracking-widest mb-1">Descrizione Tecnica</h5>
                          <p className="text-slate-800 leading-relaxed font-medium bg-slate-50 p-4 rounded-lg border-l-4 border-indigo-600">
                            {photo.aiPolishedIssue || photo.issue}
                          </p>
                        </div>
                        <div>
                          <h5 className="text-xs font-bold text-slate-400 uppercase tracking-widest mb-1">Fornitore Incaricato / Riferimento</h5>
                          <div className="flex items-center gap-2 text-slate-700">
                            <CheckCircle2 className="w-5 h-5 text-emerald-500" />
                            <span className="font-bold text-lg">{photo.supplier}</span>
                          </div>
                        </div>
                      </div>
                    </div>
                  </div>
                ))}
              </div>

              <div className="mt-20 pt-10 border-t border-slate-200 grid grid-cols-2 gap-20">
                <div className="text-center space-y-12">
                  <div className="h-1 bg-slate-200 w-full mb-4"></div>
                  <p className="text-sm font-bold text-slate-400 uppercase">Firma Amministratore</p>
                </div>
                <div className="text-center space-y-12">
                  <div className="h-1 bg-slate-200 w-full mb-4"></div>
                  <p className="text-sm font-bold text-slate-400 uppercase">Firma Tecnico / Fornitore</p>
                </div>
              </div>

              <footer className="mt-16 text-center text-xs text-slate-400">
                Documento generato via CondoInspect Pro il {new Date().toLocaleDateString('it-IT')} alle ore {new Date().toLocaleTimeString('it-IT')}
              </footer>
            </div>
          </div>
        )}
      </main>

      {/* Floating Action Bar for Upload */}
      {step === AppStep.PHOTOS && data.photos.length > 0 && (
        <div className="fixed bottom-6 left-1/2 -translate-x-1/2 bg-white/80 backdrop-blur-md border border-slate-200 px-6 py-4 rounded-full shadow-2xl flex items-center gap-6 z-50 animate-in fade-in slide-in-from-bottom-8">
           <div className="flex items-center gap-2">
              <AlertCircle className="w-5 h-5 text-indigo-600" />
              <span className="text-sm font-bold text-slate-600">{data.photos.length} Rilevazioni</span>
           </div>
           <div className="w-px h-6 bg-slate-200"></div>
           <button 
            onClick={() => document.getElementById('footer-upload')?.click()}
            className="flex items-center gap-2 text-indigo-600 hover:text-indigo-700 font-bold transition-colors"
           >
             <Camera className="w-5 h-5" /> Aggiungi
             <input id="footer-upload" type="file" multiple accept="image/*" className="hidden" onChange={handleFileChange} />
           </button>
        </div>
      )}
    </div>
  );
};

export default App;

{
  "name": "CondoInspect Pro",
  "description": "Un'applicazione professionale per la creazione di report di sopralluogo condominiale con analisi assistita dall'IA.",
  "requestFramePermissions": [
    "camera",
    "geolocation"
  ]
}

export interface Coordinates {
  latitude: number;
  longitude: number;
}

export interface InspectionPhoto {
  id: string;
  url: string;
  issue: string;
  supplier: string;
  category: string;
  coordinates?: Coordinates;
  aiPolishedIssue?: string;
  isLoading?: boolean;
}

export interface InspectionData {
  condoName: string;
  inspectionDate: string;
  logoUrl?: string;
  technicalNotes: string;
  photos: InspectionPhoto[];
  availableCategories: string[];
}

export enum AppStep {
  SETUP = 'setup',
  PHOTOS = 'photos',
  REPORT = 'report'
}

import React, { useState, useMemo } from 'react';
import { 
  Building2, 
  Calendar, 
  Camera, 
  Trash2, 
  ChevronRight, 
  ChevronLeft, 
  FileText, 
  Download,
  Wand2,
  CheckCircle2,
  AlertCircle,
  MapPin,
  Tag,
  Plus,
  Image as ImageIcon,
  StickyNote,
  Filter
} from 'lucide-react';
import { AppStep, InspectionData, InspectionPhoto, Coordinates } from './types';
import { professionalizeDescription, generateExecutiveSummary } from './services/geminiService';

const DEFAULT_CATEGORIES = ['Strutturale', 'Impianto Idraulico', 'Impianto Elettrico', 'Estetica/Facciata', 'Aree Comuni', 'Sicurezza'];

const App: React.FC = () => {
  const [step, setStep] = useState<AppStep>(AppStep.SETUP);
  const [data, setData] = useState<InspectionData>({
    condoName: '',
    inspectionDate: new Date().toISOString().split('T')[0],
    logoUrl: undefined,
    technicalNotes: '',
    photos: [],
    availableCategories: DEFAULT_CATEGORIES
  });
  const [summary, setSummary] = useState('');
  const [isGeneratingSummary, setIsGeneratingSummary] = useState(false);
  const [selectedCategoryFilter, setSelectedCategoryFilter] = useState<string>('Tutte');

  const getCoordinates = (): Promise<Coordinates | undefined> => {
    return new Promise((resolve) => {
      if (!navigator.geolocation) {
        resolve(undefined);
        return;
      }
      navigator.geolocation.getCurrentPosition(
        (position) => {
          resolve({
            latitude: position.coords.latitude,
            longitude: position.coords.longitude
          });
        },
        () => resolve(undefined),
        { timeout: 10000 }
      );
    });
  };

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files) {
      const coords = await getCoordinates();
      const newFiles = Array.from(e.target.files) as File[];
      const newPhotos: InspectionPhoto[] = newFiles.map(file => ({
        id: Math.random().toString(36).substr(2, 9),
        url: URL.createObjectURL(file),
        issue: '',
        supplier: '',
        category: DEFAULT_CATEGORIES[0],
        coordinates: coords
      }));
      setData(prev => ({ ...prev, photos: [...prev.photos, ...newPhotos] }));
    }
  };

  const handleLogoChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files?.[0]) {
      const url = URL.createObjectURL(e.target.files[0]);
      setData(prev => ({ ...prev, logoUrl: url }));
    }
  };

  const updatePhoto = (id: string, updates: Partial<InspectionPhoto>) => {
    setData(prev => ({
      ...prev,
      photos: prev.photos.map(p => p.id === id ? { ...p, ...updates } : p)
    }));
  };

  const removePhoto = (id: string) => {
    setData(prev => ({
      ...prev,
      photos: prev.photos.filter(p => p.id !== id)
    }));
  };

  const addCategory = () => {
    const newCat = prompt("Inserisci il nome della nuova categoria:");
    if (newCat && !data.availableCategories.includes(newCat)) {
      setData(prev => ({
        ...prev,
        availableCategories: [...prev.availableCategories, newCat]
      }));
    }
  };

  const handleAIEnhance = async (id: string, currentIssue: string) => {
    if (!currentIssue) return;
    updatePhoto(id, { isLoading: true });
    const polished = await professionalizeDescription(currentIssue);
    updatePhoto(id, { aiPolishedIssue: polished, isLoading: false });
  };

  const handleGenerateReport = async () => {
    setStep(AppStep.REPORT);
    setIsGeneratingSummary(true);
    const issues = data.photos.map(p => p.aiPolishedIssue || p.issue).filter(Boolean);
    const execSummary = await generateExecutiveSummary(data.condoName, issues);
    setSummary(execSummary);
    setIsGeneratingSummary(false);
  };

  const filteredPhotos = useMemo(() => {
    if (selectedCategoryFilter === 'Tutte') return data.photos;
    return data.photos.filter(p => p.category === selectedCategoryFilter);
  }, [data.photos, selectedCategoryFilter]);

  const reportCategories = useMemo(() => {
    const cats = new Set(data.photos.map(p => p.category));
    return ['Tutte', ...Array.from(cats)];
  }, [data.photos]);

  const printReport = () => {
    window.print();
  };

  const isSetupValid = data.condoName && data.inspectionDate;
  const isPhotosValid = data.photos.length > 0 && data.photos.every(p => p.issue && p.supplier);

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col">
      {/* Header */}
      <header className="bg-white border-b border-slate-200 sticky top-0 z-50 px-4 py-4 print:hidden">
        <div className="max-w-4xl mx-auto flex items-center justify-between">
          <div className="flex items-center gap-2">
            <div className="bg-indigo-600 p-2 rounded-lg">
              <Building2 className="text-white w-6 h-6" />
            </div>
            <h1 className="text-xl font-bold text-slate-800">CondoInspect <span className="text-indigo-600">Pro</span></h1>
          </div>
          <div className="flex items-center gap-4">
            <div className="hidden sm:flex items-center gap-1 text-xs font-medium text-slate-400">
               <span className={step === AppStep.SETUP ? 'text-indigo-600' : ''}>Setup</span>
               <ChevronRight className="w-3 h-3" />
               <span className={step === AppStep.PHOTOS ? 'text-indigo-600' : ''}>Foto</span>
               <ChevronRight className="w-3 h-3" />
               <span className={step === AppStep.REPORT ? 'text-indigo-600' : ''}>Report</span>
            </div>
          </div>
        </div>
      </header>

      <main className="flex-1 max-w-4xl mx-auto w-full p-4 sm:p-6 pb-32">
        {step === AppStep.SETUP && (
          <div className="bg-white rounded-2xl shadow-sm border border-slate-200 p-8 animate-in fade-in slide-in-from-bottom-4 duration-500">
            <h2 className="text-2xl font-bold text-slate-900 mb-6">Configurazione Report</h2>
            <div className="space-y-6">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div>
                  <label className="block text-sm font-semibold text-slate-700 mb-2">Nome Condominio</label>
                  <div className="relative">
                    <Building2 className="absolute left-3 top-3 w-5 h-5 text-slate-400" />
                    <input 
                      type="text" 
                      placeholder="Esempio: Condominio Belvedere"
                      className="w-full pl-10 pr-4 py-3 bg-slate-50 border border-slate-200 rounded-xl focus:ring-2 focus:ring-indigo-500 outline-none transition-all"
                      value={data.condoName}
                      onChange={(e) => setData({...data, condoName: e.target.value})}
                    />
                  </div>
                </div>
                <div>
                  <label className="block text-sm font-semibold text-slate-700 mb-2">Data Sopralluogo</label>
                  <div className="relative">
                    <Calendar className="absolute left-3 top-3 w-5 h-5 text-slate-400" />
                    <input 
                      type="date" 
                      className="w-full pl-10 pr-4 py-3 bg-slate-50 border border-slate-200 rounded-xl focus:ring-2 focus:ring-indigo-500 outline-none transition-all"
                      value={data.inspectionDate}
                      onChange={(e) => setData({...data, inspectionDate: e.target.value})}
                    />
                  </div>
                </div>
              </div>

              <div>
                <label className="block text-sm font-semibold text-slate-700 mb-2">Logo Condominio (opzionale)</label>
                <div className="flex items-center gap-4">
                  <label className="flex-1 border-2 border-dashed border-slate-200 rounded-xl p-4 flex items-center justify-center gap-3 cursor-pointer hover:bg-slate-50 hover:border-indigo-300 transition-all">
                    {data.logoUrl ? (
                      <img src={data.logoUrl} alt="Logo" className="h-12 w-auto object-contain" />
                    ) : (
                      <div className="flex items-center gap-2 text-slate-400">
                        <ImageIcon className="w-5 h-5" />
                        <span className="text-sm">Carica Logo</span>
                      </div>
                    )}
                    <input type="file" accept="image/*" className="hidden" onChange={handleLogoChange} />
                  </label>
                  {data.logoUrl && (
                    <button onClick={() => setData({...data, logoUrl: undefined})} className="p-3 text-red-500 hover:bg-red-50 rounded-xl transition-all">
                      <Trash2 className="w-5 h-5" />
                    </button>
                  )}
                </div>
              </div>

              <div>
                <label className="block text-sm font-semibold text-slate-700 mb-2">Note Tecniche Aggiuntive</label>
                <div className="relative">
                  <StickyNote className="absolute left-3 top-3 w-5 h-5 text-slate-400" />
                  <textarea 
                    placeholder="Inserisci note aggiuntive che compariranno alla fine del report..."
                    className="w-full pl-10 pr-4 py-3 bg-slate-50 border border-slate-200 rounded-xl focus:ring-2 focus:ring-indigo-500 outline-none h-32 resize-none transition-all"
                    value={data.technicalNotes}
                    onChange={(e) => setData({...data, technicalNotes: e.target.value})}
                  />
                </div>
              </div>
            </div>
            <button 
              disabled={!isSetupValid}
              onClick={() => setStep(AppStep.PHOTOS)}
              className="mt-8 w-full bg-indigo-600 hover:bg-indigo-700 disabled:bg-slate-300 text-white font-bold py-4 rounded-xl shadow-lg shadow-indigo-200 flex items-center justify-center gap-2 transition-all active:scale-95"
            >
              Prosegui <ChevronRight className="w-5 h-5" />
            </button>
          </div>
        )}

        {step === AppStep.PHOTOS && (
          <div className="space-y-6 animate-in fade-in slide-in-from-bottom-4 duration-500">
            <div className="flex items-center justify-between">
              <button 
                onClick={() => setStep(AppStep.SETUP)}
                className="flex items-center gap-2 text-slate-500 hover:text-slate-800 transition-colors"
              >
                <ChevronLeft className="w-5 h-5" /> Indietro
              </button>
              <div className="flex items-center gap-3">
                <button 
                  onClick={addCategory}
                  className="text-xs font-bold bg-white border border-slate-200 px-3 py-1 rounded-lg hover:bg-slate-50 flex items-center gap-1 transition-all"
                >
                  <Plus className="w-3 h-3" /> Nuova Categoria
                </button>
                <span className="text-sm font-medium bg-indigo-50 text-indigo-700 px-3 py-1 rounded-full">
                  {data.photos.length} Rilevazioni
                </span>
              </div>
            </div>

            <div className="grid grid-cols-1 gap-6">
              {data.photos.map((photo) => (
                <div key={photo.id} className="bg-white rounded-2xl shadow-sm border border-slate-200 overflow-hidden flex flex-col md:flex-row h-full">
                  <div className="md:w-1/3 relative bg-slate-100 min-h-[200px]">
                    <img src={photo.url} alt="Inspection" className="w-full h-full object-cover" />
                    <button 
                      onClick={() => removePhoto(photo.id)}
                      className="absolute top-2 right-2 p-2 bg-red-500 text-white rounded-full hover:bg-red-600 transition-all shadow-lg"
                    >
                      <Trash2 className="w-4 h-4" />
                    </button>
                    {photo.coordinates && (
                      <div className="absolute bottom-2 left-2 bg-black/50 backdrop-blur-sm text-white text-[10px] px-2 py-1 rounded flex items-center gap-1">
                        <MapPin className="w-3 h-3" />
                        {photo.coordinates.latitude.toFixed(5)}, {photo.coordinates.longitude.toFixed(5)}
                      </div>
                    )}
                  </div>
                  <div className="flex-1 p-6 space-y-4">
                    <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                      <div className="space-y-2">
                        <label className="text-xs font-bold uppercase tracking-wider text-slate-500 flex items-center gap-1">
                          <Tag className="w-3 h-3" /> Categoria
                        </label>
                        <select 
                          className="w-full p-2 bg-slate-50 border border-slate-200 rounded-lg text-sm focus:ring-2 focus:ring-indigo-500 outline-none"
                          value={photo.category}
                          onChange={(e) => updatePhoto(photo.id, { category: e.target.value })}
                        >
                          {data.availableCategories.map(cat => (
                            <option key={cat} value={cat}>{cat}</option>
                          ))}
                        </select>
                      </div>
                      <div className="space-y-2">
                        <label className="text-xs font-bold uppercase tracking-wider text-slate-500 flex items-center gap-1">
                          <CheckCircle2 className="w-3 h-3" /> Fornitore
