            <div className="pt-8">
              <button 
                disabled={!isPhotosValid}
                onClick={handleGenerateReport}
                className="w-full bg-emerald-600 hover:bg-emerald-700 disabled:bg-slate-300 text-white font-bold py-4 rounded-xl shadow-lg shadow-emerald-200 flex items-center justify-center gap-2 transition-all active:scale-95"
              >
                Genera Report Finale <FileText className="w-5 h-5" />
              </button>
            </div>
          </div>
        )}

        {step === AppStep.REPORT && (
          <div className="space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-500">
            <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 print:hidden">
              <button 
                onClick={() => setStep(AppStep.PHOTOS)}
                className="flex items-center gap-2 text-slate-500 hover:text-slate-800 transition-colors"
