              <div className="flex items-center gap-3">
                <div className="flex items-center gap-2 bg-white px-3 py-2 rounded-xl border border-slate-200">
                  <Filter className="w-4 h-4 text-slate-400" />
                  <select 
                    className="text-sm bg-transparent outline-none font-medium"
                    value={selectedCategoryFilter}
                    onChange={(e) => setSelectedCategoryFilter(e.target.value)}
                  >
                    {reportCategories.map(cat => (
                      <option key={cat} value={cat}>{cat}</option>
                    ))}
                  </select>
                </div>
                <button 
                  onClick={printReport}
                  className="bg-slate-900 text-white px-6 py-3 rounded-xl hover:bg-slate-800 transition-all shadow-lg flex items-center gap-2"
                >
                  <Download className="w-5 h-5" /> Stampa PDF
                </button>
              </div>
            </div>

            {/* The Actual Report Content */}
            <div id="final-report" className="bg-white shadow-2xl rounded-sm p-10 print:shadow-none print:p-0">
              <div className="border-b-4 border-indigo-600 pb-8 mb-8 flex items-start justify-between">
                <div>
                  <h1 className="text-3xl font-black text-slate-900 uppercase leading-none mb-2">Verbale di Sopralluogo</h1>
                  <p className="text-indigo-600 font-bold tracking-widest uppercase text-xs">Ispezione Tecnica Professionale</p>
                </div>
                {data.logoUrl && (
                  <img src={data.logoUrl} alt="Logo Condominio" className="h-16 w-auto object-contain" />
