                  <p className="text-lg font-bold text-slate-800">{data.condoName}</p>
                </div>
                <div className="bg-slate-50 p-5 rounded-xl border border-slate-100">
                  <h3 className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-1">Data Ispezione</h3>
                  <p className="text-lg font-bold text-slate-800">{new Date(data.inspectionDate).toLocaleDateString('it-IT', { day: 'numeric', month: 'long', year: 'numeric' })}</p>
                </div>
                <div className="bg-indigo-50 p-5 rounded-xl border border-indigo-100 md:col-span-1">
                  <h3 className="text-[10px] font-bold text-indigo-400 uppercase tracking-widest mb-1">Riepilogo</h3>
                  <p className="text-xs text-indigo-900 font-medium">{filteredPhotos.length} criticità rilevate {selectedCategoryFilter !== 'Tutte' ? `in ${selectedCategoryFilter}` : ''}</p>
                </div>
              </div>

              <div className="mb-12 bg-indigo-50/30 p-6 rounded-2xl border-l-4 border-indigo-600">
                <h3 className="text-sm font-bold text-indigo-900 mb-2 uppercase tracking-wide">Sintesi Esecutiva</h3>
                <p className="text-slate-700 italic text-sm leading-relaxed">
                  {isGeneratingSummary ? "Analisi dati in corso..." : summary}
                </p>
              </div>

              <div className="space-y-16">
                {filteredPhotos.map((photo, index) => (
                  <div key={photo.id} className="break-inside-avoid">
                    <div className="flex items-center justify-between mb-4 border-b border-slate-100 pb-2">
                      <div className="flex items-center gap-3">
                        <span className="bg-slate-900 text-white w-7 h-7 rounded-full flex items-center justify-center font-bold text-sm">{index + 1}</span>
                        <h4 className="text-md font-bold text-slate-800 uppercase tracking-tight">Rilievo #{index + 1} - {photo.category}</h4>
                      </div>
                      <div className="text-right">
                        <span className="text-[10px] font-bold text-slate-400 uppercase">Fornitore</span>
                        <p className="text-sm font-bold text-indigo-600">{photo.supplier}</p>
                      </div>
                    </div>

                    <div className="grid grid-cols-1 md:grid-cols-12 gap-6">
                      <div className="md:col-span-5 relative">
                        <img src={photo.url} alt={`Rilievo ${index + 1}`} className="w-full h-64 object-cover rounded-lg shadow-sm" />
                        {photo.coordinates && (
                          <div className="mt-2 flex items-center gap-1.5 text-[10px] font-medium text-slate-400">
                            <MapPin className="w-3 h-3 text-indigo-500" />
                            Coordinate GPS: {photo.coordinates.latitude.toFixed(6)}, {photo.coordinates.longitude.toFixed(6)}
                          </div>
                        )}
                      </div>
                      <div className="md:col-span-7">
                        <div className="h-full flex flex-col justify-between">
                          <div>
                            <h5 className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-2">Osservazione Tecnica</h5>
                            <p className="text-slate-800 text-sm leading-relaxed font-medium bg-slate-50 p-4 rounded-lg border-l-4 border-indigo-400">
                              {photo.aiPolishedIssue || photo.issue}
                            </p>
                          </div>
                          <div className="mt-6 flex items-center gap-4 text-[10px] text-slate-400 font-bold uppercase">
                            <div className="flex items-center gap-1">
                              <CheckCircle2 className="w-3 h-3 text-emerald-500" /> Stato: Da Verificare
                            </div>
                            <div className="flex items-center gap-1">
                              <Tag className="w-3 h-3 text-indigo-500" /> {photo.category}
                            </div>
                          </div>
                        </div>
                      </div>
                    </div>
                  </div>
                ))}
              </div>

              {data.technicalNotes && (
                <div className="mt-20 pt-10 border-t-2 border-slate-100 break-inside-avoid">
                  <h3 className="text-sm font-black text-slate-900 uppercase tracking-widest mb-4 flex items-center gap-2">
                    <StickyNote className="w-5 h-5 text-indigo-600" /> Note Tecniche Integrative
                  </h3>
                  <div className="bg-slate-50 p-6 rounded-xl border border-slate-200 text-slate-700 text-sm leading-relaxed whitespace-pre-wrap">
                    {data.technicalNotes}
                  </div>
                </div>
              )}

              <div className="mt-24 pt-10 border-t-2 border-indigo-600 grid grid-cols-2 gap-20">
                <div className="text-center space-y-16">
                  <div className="h-0.5 bg-slate-200 w-full mb-4"></div>
                  <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Firma Amministratore</p>
                </div>
                <div className="text-center space-y-16">
                  <div className="h-0.5 bg-slate-200 w-full mb-4"></div>
                  <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Firma Tecnico Incaricato</p>
                </div>
              </div>

              <footer className="mt-20 text-center text-[9px] text-slate-300 border-t border-slate-50 pt-4 uppercase tracking-tighter">
                Documento certificato CondoInspect Pro - Generato il {new Date().toLocaleDateString('it-IT')} alle {new Date().toLocaleTimeString('it-IT')}
              </footer>
            </div>
          </div>
        )}
      </main>

      {/* Floating Action Bar for Upload */}
      {step === AppStep.PHOTOS && data.photos.length > 0 && (
        <div className="fixed bottom-6 left-1/2 -translate-x-1/2 bg-white/90 backdrop-blur-md border border-slate-200 px-6 py-4 rounded-full shadow-2xl flex items-center gap-6 z-50 animate-in fade-in slide-in-from-bottom-8">
           <div className="flex items-center gap-2">
              <AlertCircle className="w-5 h-5 text-indigo-600" />
              <span className="text-sm font-bold text-slate-600">{data.photos.length} Foto</span>
           </div>
           <div className="w-px h-6 bg-slate-200"></div>
           <button 
            onClick={() => document.getElementById('footer-upload')?.click()}
            className="flex items-center gap-2 text-indigo-600 hover:text-indigo-700 font-bold transition-colors"
           >
             <Camera className="w-5 h-5" /> Aggiungi
             <input id="footer-upload" type="file" multiple accept="image/*" className="hidden" onChange={handleFileChange} />
           </button>
        </div>
      )}
    </div>
  );
};

export default App;

import React, { useState, useMemo } from 'react';
import { 
  Building2, 
  Calendar, 
  Camera, 
  Trash2, 
  ChevronRight, 
  ChevronLeft, 
  FileText, 
  Download,
  Wand2,
  CheckCircle2,
  AlertCircle,
  MapPin,
  Tag,
  Plus,
  Image as ImageIcon,
  StickyNote,
  Filter
} from 'lucide-react';
import { AppStep, InspectionData, InspectionPhoto, Coordinates } from './types';
import { professionalizeDescription, generateExecutiveSummary } from './services/geminiService';

const DEFAULT_CATEGORIES = ['Strutturale', 'Impianto Idraulico', 'Impianto Elettrico', 'Estetica/Facciata', 'Aree Comuni', 'Sicurezza'];

// Foto di esempio basate sulle immagini caricate dall'utente
const EXAMPLE_PHOTOS: InspectionPhoto[] = [
  {
    id: 'ex1',
    url: 'https://images.unsplash.com/photo-1590059390250-983633857e33?auto=format&fit=crop&q=80&w=800',
    issue: 'Citofoniera esterna e area cassette postali: necessità di verifica integrità pannello frontale.',
    supplier: 'ElettroDomus Srl',
    category: 'Aree Comuni',
    coordinates: { latitude: 45.695, longitude: 9.670 } // Bergamo area
  },
  {
    id: 'ex2',
    url: 'https://images.unsplash.com/photo-1584622650111-993a426fbf0a?auto=format&fit=crop&q=80&w=800',
    issue: 'Dettaglio facciata: infiltrazione puntuale visibile sopra il blocco cassette postali.',
    supplier: 'EdilBergamo',
    category: 'Estetica/Facciata',
    coordinates: { latitude: 45.695, longitude: 9.671 }
  },
  {
    id: 'ex3',
    url: 'https://images.unsplash.com/photo-1545324418-cc1a3fa10c00?auto=format&fit=crop&q=80&w=800',
    issue: 'Panoramica edificio: verifica stato manutentivo balconi e gronde ultimo piano.',
    supplier: 'Manutenzioni Generali',
    category: 'Strutturale',
    coordinates: { latitude: 45.694, longitude: 9.670 }
  }
];

const App: React.FC = () => {
  const [step, setStep] = useState<AppStep>(AppStep.SETUP);
  const [data, setData] = useState<InspectionData>({
    condoName: 'Condominio Belvedere - Via Roma 12',
    inspectionDate: new Date().toISOString().split('T')[0],
    logoUrl: undefined,
    technicalNotes: 'Sopralluogo programmato per verifica ordinaria stato immobile. Si segnalano criticità minori in area ingresso.',
    photos: EXAMPLE_PHOTOS,
    availableCategories: DEFAULT_CATEGORIES
  });
  const [summary, setSummary] = useState('');
  const [isGeneratingSummary, setIsGeneratingSummary] = useState(false);
  const [selectedCategoryFilter, setSelectedCategoryFilter] = useState<string>('Tutte');

  const getCoordinates = (): Promise<Coordinates | undefined> => {
    return new Promise((resolve) => {
      if (!navigator.geolocation) {
        resolve(undefined);
        return;
      }
      navigator.geolocation.getCurrentPosition(
        (position) => {
          resolve({
            latitude: position.coords.latitude,
            longitude: position.coords.longitude
          });
        },
        () => resolve(undefined),
        { timeout: 10000 }
      );
    });
  };

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files) {
      const coords = await getCoordinates();
      const newFiles = Array.from(e.target.files) as File[];
      const newPhotos: InspectionPhoto[] = newFiles.map(file => ({
        id: Math.random().toString(36).substr(2, 9),
        url: URL.createObjectURL(file),
        issue: '',
        supplier: '',
        category: DEFAULT_CATEGORIES[0],
        coordinates: coords
      }));
      setData(prev => ({ ...prev, photos: [...prev.photos, ...newPhotos] }));
    }
  };

  const handleLogoChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files?.[0]) {
      const url = URL.createObjectURL(e.target.files[0]);
      setData(prev => ({ ...prev, logoUrl: url }));
    }
  };

  const updatePhoto = (id: string, updates: Partial<InspectionPhoto>) => {
    setData(prev => ({
      ...prev,
      photos: prev.photos.map(p => p.id === id ? { ...p, ...updates } : p)
    }));
  };

  const removePhoto = (id: string) => {
    setData(prev => ({
      ...prev,
      photos: prev.photos.filter(p => p.id !== id)
    }));
  };

  const addCategory = () => {
    const newCat = prompt("Inserisci il nome della nuova categoria:");
    if (newCat && !data.availableCategories.includes(newCat)) {
      setData(prev => ({
        ...prev,
        availableCategories: [...prev.availableCategories, newCat]
      }));
    }
  };

  const handleAIEnhance = async (id: string, currentIssue: string) => {
    if (!currentIssue) return;
    updatePhoto(id, { isLoading: true });
    const polished = await professionalizeDescription(currentIssue);
    updatePhoto(id, { aiPolishedIssue: polished, isLoading: false });
  };

  const handleGenerateReport = async () => {
    setStep(AppStep.REPORT);
    setIsGeneratingSummary(true);
    const issues = data.photos.map(p => p.aiPolishedIssue || p.issue).filter(Boolean);
    const execSummary = await generateExecutiveSummary(data.condoName, issues);
    setSummary(execSummary);
    setIsGeneratingSummary(false);
  };

  const filteredPhotos = useMemo(() => {
    if (selectedCategoryFilter === 'Tutte') return data.photos;
    return data.photos.filter(p => p.category === selectedCategoryFilter);
  }, [data.photos, selectedCategoryFilter]);

  const reportCategories = useMemo(() => {
    const cats = new Set(data.photos.map(p => p.category));
    return ['Tutte', ...Array.from(cats)];
  }, [data.photos]);

  const printReport = () => {
    window.print();
  };

  const isSetupValid = data.condoName && data.inspectionDate;
  const isPhotosValid = data.photos.length > 0 && data.photos.every(p => p.issue && p.supplier);

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col">
      {/* Header */}
      <header className="bg-white border-b border-slate-200 sticky top-0 z-50 px-4 py-4 print:hidden">
        <div className="max-w-4xl mx-auto flex items-center justify-between">
          <div className="flex items-center gap-2">
            <div className="bg-indigo-600 p-2 rounded-lg">
              <Building2 className="text-white w-6 h-6" />
            </div>
            <h1 className="text-xl font-bold text-slate-800">CondoInspect <span className="text-indigo-600">Pro</span></h1>
          </div>
          <div className="flex items-center gap-4">
            <div className="hidden sm:flex items-center gap-1 text-xs font-medium text-slate-400">
               <span className={step === AppStep.SETUP ? 'text-indigo-600' : ''}>Setup</span>
               <ChevronRight className="w-3 h-3" />
               <span className={step === AppStep.PHOTOS ? 'text-indigo-600' : ''}>Foto</span>
               <ChevronRight className="w-3 h-3" />
               <span className={step === AppStep.REPORT ? 'text-indigo-600' : ''}>Report</span>
            </div>
          </div>
        </div>
      </header>

      <main className="flex-1 max-w-4xl mx-auto w-full p-4 sm:p-6 pb-32">
        {step === AppStep.SETUP && (
          <div className="bg-white rounded-2xl shadow-sm border border-slate-200 p-8 animate-in fade-in slide-in-from-bottom-4 duration-500">
            <div className="flex items-center justify-between mb-6">
              <h2 className="text-2xl font-bold text-slate-900">Configurazione Report</h2>
              <div className="bg-emerald-50 text-emerald-700 text-xs font-bold px-3 py-1 rounded-full border border-emerald-100">
                Dati di esempio caricati
              </div>
            </div>

            <div className="space-y-6">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div>
                  <label className="block text-sm font-semibold text-slate-700 mb-2">Nome Condominio</label>
                  <div className="relative">
                    <Building2 className="absolute left-3 top-3 w-5 h-5 text-slate-400" />
                    <input 
                      type="text" 
                      placeholder="Esempio: Condominio Belvedere"
                      className="w-full pl-10 pr-4 py-3 bg-slate-50 border border-slate-200 rounded-xl focus:ring-2 focus:ring-indigo-500 outline-none transition-all"
                      value={data.condoName}
                      onChange={(e) => setData({...data, condoName: e.target.value})}
                    />
                  </div>
                </div>
                <div>
                  <label className="block text-sm font-semibold text-slate-700 mb-2">Data Sopralluogo</label>
                  <div className="relative">
                    <Calendar className="absolute left-3 top-3 w-5 h-5 text-slate-400" />
                    <input 
                      type="date" 
                      className="w-full pl-10 pr-4 py-3 bg-slate-50 border border-slate-200 rounded-xl focus:ring-2 focus:ring-indigo-500 outline-none transition-all"
                      value={data.inspectionDate}
                      onChange={(e) => setData({...data, inspectionDate: e.target.value})}
                    />
                  </div>
                </div>
              </div>

              <div>
                <label className="block text-sm font-semibold text-slate-700 mb-2">Logo Condominio (opzionale)</label>
                <div className="flex items-center gap-4">
                  <label className="flex-1 border-2 border-dashed border-slate-200 rounded-xl p-4 flex items-center justify-center gap-3 cursor-pointer hover:bg-slate-50 hover:border-indigo-300 transition-all">
                    {data.logoUrl ? (
                      <img src={data.logoUrl} alt="Logo" className="h-12 w-auto object-contain" />
                    ) : (
                      <div className="flex items-center gap-2 text-slate-400">
                        <ImageIcon className="w-5 h-5" />
                        <span className="text-sm">Carica Logo</span>
                      </div>
                    )}
                    <input type="file" accept="image/*" className="hidden" onChange={handleLogoChange} />
                  </label>
                  {data.logoUrl && (
                    <button onClick={() => setData({...data, logoUrl: undefined})} className="p-3 text-red-500 hover:bg-red-50 rounded-xl transition-all">
                      <Trash2 className="w-5 h-5" />
                    </button>
                  )}
                </div>
              </div>

              <div>
                <label className="block text-sm font-semibold text-slate-700 mb-2">Note Tecniche Aggiuntive</label>
                <div className="relative">
                  <StickyNote className="absolute left-3 top-3 w-5 h-5 text-slate-400" />
                  <textarea 
                    placeholder="Inserisci note aggiuntive che compariranno alla fine del report..."
                    className="w-full pl-10 pr-4 py-3 bg-slate-50 border border-slate-200 rounded-xl focus:ring-2 focus:ring-indigo-500 outline-none h-32 resize-none transition-all"
                    value={data.technicalNotes}
                    onChange={(e) => setData({...data, technicalNotes: e.target.value})}
                  />
                </div>
              </div>
            </div>
            <button 
              disabled={!isSetupValid}
              onClick={() => setStep(AppStep.PHOTOS)}
              className="mt-8 w-full bg-indigo-600 hover:bg-indigo-700 disabled:bg-slate-300 text-white font-bold py-4 rounded-xl shadow-lg shadow-indigo-200 flex items-center justify-center gap-2 transition-all active:scale-95"
            >
              Prosegui <ChevronRight className="w-5 h-5" />
            </button>
          </div>
        )}

        {step === AppStep.PHOTOS && (
          <div className="space-y-6 animate-in fade-in slide-in-from-bottom-4 duration-500">
            <div className="flex items-center justify-between">
              <button 
                onClick={() => setStep(AppStep.SETUP)}
                className="flex items-center gap-2 text-slate-500 hover:text-slate-800 transition-colors"
              >
                <ChevronLeft className="w-5 h-5" /> Indietro
              </button>
              <div className="flex items-center gap-3">
                <button 
                  onClick={addCategory}
                  className="text-xs font-bold bg-white border border-slate-200 px-3 py-1 rounded-lg hover:bg-slate-50 flex items-center gap-1 transition-all"
                >
                  <Plus className="w-3 h-3" /> Nuova Categoria
                </button>
