              <div className="grid grid-cols-1 md:grid-cols-3 gap-8 mb-12">
                <div className="bg-slate-50 p-6 rounded-2xl border border-slate-100">
                  <h3 className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-2">Condominio</h3>
                  <p className="text-xl font-black text-slate-800">{data.condoName}</p>
                </div>
                <div className="bg-slate-50 p-6 rounded-2xl border border-slate-100">
                  <h3 className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-2">Data</h3>
                  <p className="text-xl font-black text-slate-800">{new Date(data.inspectionDate).toLocaleDateString('it-IT', { day: 'numeric', month: 'long', year: 'numeric' })}</p>
                </div>
                <div className="bg-indigo-50 p-6 rounded-2xl border border-indigo-100">
                  <h3 className="text-[10px] font-bold text-indigo-400 uppercase tracking-widest mb-2">Volume Rilievi</h3>
                  <p className="text-indigo-900 font-black text-xl">{filteredPhotos.length} <span className="text-sm font-medium">Segnalazioni</span></p>
                </div>
              </div>

              <div className="mb-16 bg-slate-900 p-8 rounded-3xl text-white relative group overflow-hidden">
                <div className="absolute top-0 right-0 w-32 h-32 bg-indigo-500/10 rounded-full -mr-16 -mt-16 blur-3xl"></div>
                <div className="flex items-center justify-between mb-3">
                  <h3 className="text-xs font-bold text-indigo-400 uppercase tracking-[0.2em]">Sintesi Esecutiva</h3>
