                    className="w-full bg-transparent border-none text-white text-lg leading-relaxed font-light italic resize-none focus:ring-1 focus:ring-indigo-500/50 p-0 outline-none print:h-auto overflow-hidden"
                    rows={4}
                    value={summary}
                    onChange={(e) => {
                      setSummary(e.target.value);
                      e.target.style.height = 'auto';
                      e.target.style.height = e.target.scrollHeight + 'px';
                    }}
                    onFocus={(e) => {
                      e.target.style.height = 'auto';
                      e.target.style.height = e.target.scrollHeight + 'px';
                    }}
                  />
                )}
              </div>

              <div className="space-y-24">
                {filteredPhotos.map((indexPhoto, idx) => (
                  <div key={indexPhoto.id} className="break-inside-avoid">
                    <div className="flex items-center justify-between mb-6 border-b-2 border-slate-50 pb-4">
                      <div className="flex items-center gap-4">
                        <span className="bg-indigo-600 text-white w-10 h-10 rounded-2xl flex items-center justify-center font-black text-lg rotate-3">{idx + 1}</span>
                        <div>
                          <h4 className="text-xl font-black text-slate-800 tracking-tight">{indexPhoto.category}</h4>
                          <div className="flex items-center gap-2 mt-0.5">
                            <Tag className="w-3 h-3 text-slate-300" />
                            <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Id Rilievo: {indexPhoto.id}</span>
                          </div>
                        </div>
                      </div>
                      <div className="text-right">
                        <span className="text-[9px] font-bold text-slate-400 uppercase tracking-widest">Incaricato</span>
                        <p className="text-lg font-black text-indigo-600">{indexPhoto.supplier}</p>
                      </div>
                    </div>

                    <div className="grid grid-cols-1 md:grid-cols-12 gap-10">
                      <div className="md:col-span-5 space-y-3">
                        <div className="aspect-[4/3] rounded-3xl overflow-hidden shadow-2xl border-4 border-white">
                          <img src={indexPhoto.url} alt={`Rilievo ${idx + 1}`} className="w-full h-full object-cover" />
                        </div>
                        {indexPhoto.coordinates && (
                          <div className="flex items-center gap-2 text-[10px] font-bold text-slate-400 bg-slate-50 p-2 rounded-xl">
                            <MapPin className="w-3 h-3 text-indigo-500" />
                            GEO-REF: {indexPhoto.coordinates.latitude.toFixed(6)}, {indexPhoto.coordinates.longitude.toFixed(6)}
                          </div>
                        )}
                      </div>
                      <div className="md:col-span-7 py-2">
                        <div className="h-full flex flex-col">
                          <div className="flex-1">
                            <div className="flex items-center justify-between mb-4">
                              <h5 className="text-[10px] font-bold text-slate-300 uppercase tracking-widest flex items-center gap-2">
                                <span className="w-1.5 h-1.5 bg-indigo-500 rounded-full"></span>
                                Osservazione del Rilevatore
                              </h5>
                              <Edit3 className="w-3 h-3 text-slate-300 print:hidden" />
                            </div>
                            <textarea 
                              className="w-full text-slate-800 text-lg leading-relaxed font-medium bg-indigo-50/30 p-8 rounded-[2rem] border-2 border-indigo-50 resize-none outline-none focus:ring-2 focus:ring-indigo-200/50 transition-all print:border-none print:p-0"
                              rows={5}
                              value={indexPhoto.aiPolishedIssue || indexPhoto.issue}
                              onChange={(e) => {
                                updatePhoto(indexPhoto.id, { 
                                  aiPolishedIssue: e.target.value,
                                  issue: e.target.value 
                                });
                                e.target.style.height = 'auto';
                                e.target.style.height = e.target.scrollHeight + 'px';
                              }}
                              onFocus={(e) => {
                                e.target.style.height = 'auto';
                                e.target.style.height = e.target.scrollHeight + 'px';
                              }}
                            />
                          </div>
                          <div className="mt-8 grid grid-cols-2 gap-4">
                            <div className="bg-slate-50 px-4 py-3 rounded-2xl flex items-center gap-3 border border-slate-100">
                              <CheckCircle2 className="w-5 h-5 text-emerald-500" />
                              <span className="text-[10px] font-bold uppercase text-slate-500 tracking-widest">Stato: Da Approvare</span>
                            </div>
                            <div className="bg-slate-50 px-4 py-3 rounded-2xl flex items-center gap-3 border border-slate-100">
                              <Tag className="w-5 h-5 text-indigo-500" />
                              <span className="text-[10px] font-bold uppercase text-slate-500 tracking-widest">Priorità: Alta</span>
                            </div>
                          </div>
                        </div>
                      </div>
                    </div>
                  </div>
                ))}
              </div>

              {data.technicalNotes && (
                <div className="mt-32 pt-16 border-t-4 border-indigo-600/10 break-inside-avoid">
                  <h3 className="text-xl font-black text-slate-900 uppercase tracking-tight mb-6 flex items-center gap-3">
                    <StickyNote className="w-8 h-8 text-indigo-600" /> Note Integrative del Sopralluogo
                  </h3>
                  <div className="bg-slate-50 p-10 rounded-[3rem] border-2 border-slate-100 text-slate-700 text-lg leading-relaxed whitespace-pre-wrap font-medium italic shadow-inner">
                    {data.technicalNotes}
                  </div>
                </div>
              )}

              <div className="mt-40 pt-16 border-t-4 border-slate-900 flex justify-end">
                <div className="text-center w-80">
                  <div className="h-0.5 bg-slate-200 w-full mb-6"></div>
                  <p className="text-xs font-black text-slate-400 uppercase tracking-[0.3em]">L'Amministratore / Collaboratore</p>
                </div>
              </div>

              <footer className="mt-32 text-center text-[10px] text-slate-300 font-bold uppercase tracking-[0.4em] pt-8 border-t border-slate-50">
                Documentazione Digitale CondoInspect Pro - {new Date().toLocaleDateString('it-IT')} {new Date().toLocaleTimeString('it-IT')}
              </footer>
            </div>
          </div>
        )}
      </main>
    </div>
  );
};

export default App;

import React, { useState, useMemo } from 'react';
import { 
  Building2, 
  Calendar, 
  Camera, 
  Trash2, 
  ChevronRight, 
  ChevronLeft, 
  FileText, 
  Download,
  Wand2,
  CheckCircle2,
  AlertCircle,
  MapPin,
  Tag,
  Plus,
  Image as ImageIcon,
  StickyNote,
  Filter,
  X,
  Check,
  Edit3
} from 'lucide-react';
import { AppStep, InspectionData, InspectionPhoto, Coordinates } from './types';
import { professionalizeDescription, generateExecutiveSummary } from './services/geminiService';

const DEFAULT_CATEGORIES = ['Strutturale', 'Impianto Idraulico', 'Impianto Elettrico', 'Estetica/Facciata', 'Aree Comuni', 'Sicurezza'];

// Foto di esempio basate sulle immagini caricate dall'utente
const EXAMPLE_PHOTOS: InspectionPhoto[] = [
  {
    id: 'ex1',
    url: 'https://images.unsplash.com/photo-1590059390250-983633857e33?auto=format&fit=crop&q=80&w=800',
    issue: 'Citofoniera esterna al civico 2: verificare funzionamento pulsantiera e stato estetico cornice metallica.',
    supplier: 'ElettroDomus Srl',
    category: 'Aree Comuni',
    coordinates: { latitude: 45.695, longitude: 9.670 }
  },
  {
    id: 'ex2',
    url: 'https://images.unsplash.com/photo-1584622650111-993a426fbf0a?auto=format&fit=crop&q=80&w=800',
    issue: 'Dettaglio muro area cassette postali: presenza di sporcizia e segni di umidità di risalita sulla finitura superficiale.',
    supplier: 'EdilBergamo',
    category: 'Estetica/Facciata',
    coordinates: { latitude: 45.695, longitude: 9.671 }
  },
  {
    id: 'ex3',
    url: 'https://images.unsplash.com/photo-1545324418-cc1a3fa10c00?auto=format&fit=crop&q=80&w=800',
    issue: 'Vista stabile principale: sopralluogo per verifica facciate e area commerciale al piano terra (Bar/Tabacchi).',
    supplier: 'Manutenzioni Generali',
    category: 'Strutturale',
    coordinates: { latitude: 45.694, longitude: 9.670 }
  }
];

const App: React.FC = () => {
  const [step, setStep] = useState<AppStep>(AppStep.SETUP);
  const [data, setData] = useState<InspectionData>({
    condoName: 'Condominio San Carlo - Via Luzzatti 5',
    inspectionDate: new Date().toISOString().split('T')[0],
    logoUrl: undefined,
    technicalNotes: 'Sopralluogo effettuato per verifica stato conservativo generale dell\'immobile e delle pertinenze comuni.',
    photos: EXAMPLE_PHOTOS,
    availableCategories: DEFAULT_CATEGORIES
  });

  const [isAddingCategory, setIsAddingCategory] = useState(false);
  const [newCatName, setNewCatName] = useState('');
  const [summary, setSummary] = useState('');
  const [isGeneratingSummary, setIsGeneratingSummary] = useState(false);
  const [selectedCategoryFilter, setSelectedCategoryFilter] = useState<string>('Tutte');

  const getCoordinates = (): Promise<Coordinates | undefined> => {
    return new Promise((resolve) => {
      if (!navigator.geolocation) {
        resolve(undefined);
        return;
      }
      navigator.geolocation.getCurrentPosition(
        (position) => {
          resolve({
            latitude: position.coords.latitude,
            longitude: position.coords.longitude
          });
        },
        () => resolve(undefined),
        { timeout: 10000 }
      );
    });
  };

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files) {
      const coords = await getCoordinates();
      const newFiles = Array.from(e.target.files) as File[];
      const newPhotos: InspectionPhoto[] = newFiles.map(file => ({
        id: Math.random().toString(36).substr(2, 9),
        url: URL.createObjectURL(file),
        issue: '',
        supplier: '',
        category: data.availableCategories[0] || DEFAULT_CATEGORIES[0],
        coordinates: coords
      }));
      setData(prev => ({ ...prev, photos: [...prev.photos, ...newPhotos] }));
    }
  };

  const handleLogoChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files?.[0]) {
      const url = URL.createObjectURL(e.target.files[0]);
      setData(prev => ({ ...prev, logoUrl: url }));
    }
  };

  const updatePhoto = (id: string, updates: Partial<InspectionPhoto>) => {
    setData(prev => ({
      ...prev,
      photos: prev.photos.map(p => p.id === id ? { ...p, ...updates } : p)
    }));
  };

  const removePhoto = (id: string) => {
    setData(prev => ({
      ...prev,
      photos: prev.photos.filter(p => p.id !== id)
    }));
  };

  const handleAddCategory = () => {
    const trimmed = newCatName.trim();
    if (trimmed && !data.availableCategories.includes(trimmed)) {
      setData(prev => ({
        ...prev,
        availableCategories: [...prev.availableCategories, trimmed]
      }));
      setNewCatName('');
      setIsAddingCategory(false);
    }
  };

  const handleAIEnhance = async (id: string, currentIssue: string) => {
    if (!currentIssue) return;
    updatePhoto(id, { isLoading: true });
    const polished = await professionalizeDescription(currentIssue);
    updatePhoto(id, { aiPolishedIssue: polished, isLoading: false });
  };

  const handleGenerateReport = async () => {
    setStep(AppStep.REPORT);
    setIsGeneratingSummary(true);
    const issues = data.photos.map(p => p.aiPolishedIssue || p.issue).filter(Boolean);
    const execSummary = await generateExecutiveSummary(data.condoName, issues);
    setSummary(execSummary);
    setIsGeneratingSummary(false);
  };

  const filteredPhotos = useMemo(() => {
    if (selectedCategoryFilter === 'Tutte') return data.photos;
    return data.photos.filter(p => p.category === selectedCategoryFilter);
  }, [data.photos, selectedCategoryFilter]);

  const reportCategories = useMemo(() => {
    const cats = new Set(data.photos.map(p => p.category));
    return ['Tutte', ...Array.from(cats)];
  }, [data.photos]);

  const printReport = () => {
    window.print();
  };

  const isSetupValid = data.condoName && data.inspectionDate;

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col">
      {/* Header */}
      <header className="bg-white border-b border-slate-200 sticky top-0 z-50 px-4 py-4 print:hidden">
        <div className="max-w-4xl mx-auto flex items-center justify-between">
          <div className="flex items-center gap-2">
            <div className="bg-indigo-600 p-2 rounded-lg">
              <Building2 className="text-white w-6 h-6" />
            </div>
            <h1 className="text-xl font-bold text-slate-800">CondoInspect <span className="text-indigo-600">Pro</span></h1>
          </div>
          <div className="flex items-center gap-4">
            <div className="hidden sm:flex items-center gap-1 text-xs font-medium text-slate-400">
               <span className={step === AppStep.SETUP ? 'text-indigo-600' : ''}>Setup</span>
               <ChevronRight className="w-3 h-3" />
               <span className={step === AppStep.PHOTOS ? 'text-indigo-600' : ''}>Foto</span>
               <ChevronRight className="w-3 h-3" />
               <span className={step === AppStep.REPORT ? 'text-indigo-600' : ''}>Report</span>
            </div>
          </div>
        </div>
      </header>

      <main className="flex-1 max-w-4xl mx-auto w-full p-4 sm:p-6 pb-20">
        {step === AppStep.SETUP && (
          <div className="bg-white rounded-2xl shadow-sm border border-slate-200 p-8 animate-in fade-in slide-in-from-bottom-4 duration-500">
            <div className="flex items-center justify-between mb-6">
              <h2 className="text-2xl font-bold text-slate-900">Configurazione Report</h2>
              <div className="bg-emerald-50 text-emerald-700 text-xs font-bold px-3 py-1 rounded-full border border-emerald-100">
                Esempi caricati
              </div>
            </div>

            <div className="space-y-6">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div>
                  <label className="block text-sm font-semibold text-slate-700 mb-2">Nome Condominio</label>
                  <div className="relative">
                    <Building2 className="absolute left-3 top-3 w-5 h-5 text-slate-400" />
                    <input 
                      type="text" 
                      placeholder="Esempio: Condominio Belvedere"
                      className="w-full pl-10 pr-4 py-3 bg-slate-50 border border-slate-200 rounded-xl focus:ring-2 focus:ring-indigo-500 outline-none transition-all"
                      value={data.condoName}
                      onChange={(e) => setData({...data, condoName: e.target.value})}
                    />
                  </div>
                </div>
                <div>
                  <label className="block text-sm font-semibold text-slate-700 mb-2">Data Sopralluogo</label>
                  <div className="relative">
                    <Calendar className="absolute left-3 top-3 w-5 h-5 text-slate-400" />
                    <input 
                      type="date" 
                      className="w-full pl-10 pr-4 py-3 bg-slate-50 border border-slate-200 rounded-xl focus:ring-2 focus:ring-indigo-500 outline-none transition-all"
                      value={data.inspectionDate}
                      onChange={(e) => setData({...data, inspectionDate: e.target.value})}
                    />
                  </div>
                </div>
              </div>

              <div>
                <label className="block text-sm font-semibold text-slate-700 mb-2">Logo Condominio (opzionale)</label>
                <div className="flex items-center gap-4">
                  <label className="flex-1 border-2 border-dashed border-slate-200 rounded-xl p-4 flex items-center justify-center gap-3 cursor-pointer hover:bg-slate-50 hover:border-indigo-300 transition-all">
                    {data.logoUrl ? (
                      <img src={data.logoUrl} alt="Logo" className="h-12 w-auto object-contain" />
                    ) : (
                      <div className="flex items-center gap-2 text-slate-400">
                        <ImageIcon className="w-5 h-5" />
                        <span className="text-sm">Carica Logo</span>
                      </div>
                    )}
                    <input type="file" accept="image/*" className="hidden" onChange={handleLogoChange} />
                  </label>
                  {data.logoUrl && (
                    <button onClick={() => setData({...data, logoUrl: undefined})} className="p-3 text-red-500 hover:bg-red-50 rounded-xl transition-all">
                      <Trash2 className="w-5 h-5" />
                    </button>
                  )}
                </div>
              </div>

              <div>
                <label className="block text-sm font-semibold text-slate-700 mb-2">Note Aggiuntive</label>
                <div className="relative">
                  <StickyNote className="absolute left-3 top-3 w-5 h-5 text-slate-400" />
                  <textarea 
                    placeholder="Inserisci note aggiuntive che compariranno alla fine del report..."
                    className="w-full pl-10 pr-4 py-3 bg-slate-50 border border-slate-200 rounded-xl focus:ring-2 focus:ring-indigo-500 outline-none h-32 resize-none transition-all"
                    value={data.technicalNotes}
                    onChange={(e) => setData({...data, technicalNotes: e.target.value})}
                  />
                </div>
              </div>
            </div>
            <button 
              disabled={!isSetupValid}
              onClick={() => setStep(AppStep.PHOTOS)}
              className="mt-8 w-full bg-indigo-600 hover:bg-indigo-700 disabled:bg-slate-300 text-white font-bold py-4 rounded-xl shadow-lg shadow-indigo-200 flex items-center justify-center gap-2 transition-all active:scale-95"
            >
              Prosegui <ChevronRight className="w-5 h-5" />
            </button>
          </div>
        )}

        {step === AppStep.PHOTOS && (
          <div className="space-y-6 animate-in fade-in slide-in-from-bottom-4 duration-500">
            <div className="flex items-center justify-between bg-white p-4 rounded-2xl shadow-sm border border-slate-200 sticky top-20 z-40">
              <button 
                onClick={() => setStep(AppStep.SETUP)}
                className="flex items-center gap-2 text-slate-500 hover:text-slate-800 transition-colors"
              >
                <ChevronLeft className="w-5 h-5" /> Indietro
              </button>

              <div className="flex items-center gap-3">
                <label className="flex items-center gap-2 bg-indigo-600 text-white px-4 py-2 rounded-xl hover:bg-indigo-700 cursor-pointer transition-all shadow-md shadow-indigo-100 font-bold text-sm">
                  <Camera className="w-4 h-4" /> Aggiungi Foto
                  <input type="file" multiple accept="image/*" className="hidden" onChange={handleFileChange} />
                </label>

                {isAddingCategory ? (
                  <div className="flex items-center gap-2 animate-in slide-in-from-right-2">
                    <input 
                      autoFocus
                      type="text"
                      placeholder="Nuova cat..."
                      className="text-xs p-1.5 border border-indigo-200 rounded-lg outline-none focus:ring-1 focus:ring-indigo-500 w-24"
                      value={newCatName}
                      onChange={(e) => setNewCatName(e.target.value)}
                      onKeyDown={(e) => e.key === 'Enter' && handleAddCategory()}
                    />
                    <button onClick={handleAddCategory} className="p-1.5 bg-emerald-500 text-white rounded-lg">
                      <Check className="w-3 h-3" />
                    </button>
                    <button onClick={() => { setIsAddingCategory(false); setNewCatName(''); }} className="p-1.5 bg-slate-200 text-slate-600 rounded-lg">
                      <X className="w-3 h-3" />
                    </button>
                  </div>
                ) : (
                  <button 
                    onClick={() => setIsAddingCategory(true)}
                    className="p-2 bg-indigo-50 text-indigo-700 border border-indigo-100 rounded-xl hover:bg-indigo-100"
                    title="Nuova Categoria"
                  >
                    <Plus className="w-5 h-5" />
                  </button>
                )}
                <div className="hidden sm:block w-px h-6 bg-slate-200 mx-1"></div>
                <span className="text-xs font-bold text-slate-500 uppercase tracking-widest hidden sm:block">
                  {data.photos.length} Foto
                </span>
              </div>
