import React, { useState, useMemo, useEffect } from 'react';
import { 
  Building2, 
  Calendar, 
  Camera, 
  Trash2, 
  ChevronRight, 
  ChevronLeft, 
  FileText, 
  Download,
  Wand2,
  CheckCircle2,
  AlertCircle,
  MapPin,
  Tag,
  Plus,
  Image as ImageIcon,
  StickyNote,
  Filter,
  X,
  Check,
  Edit3,
  Loader2
} from 'lucide-react';
import { AppStep, InspectionData, InspectionPhoto, Coordinates } from './types';
import { professionalizeDescription, generateExecutiveSummary } from './services/geminiService';

const DEFAULT_CATEGORIES = ['Strutturale', 'Impianto Idraulico', 'Impianto Elettrico', 'Estetica/Facciata', 'Aree Comuni', 'Sicurezza'];

const App: React.FC = () => {
  const [step, setStep] = useState<AppStep>(AppStep.SETUP);
  const [isExporting, setIsExporting] = useState(false);
  const [data, setData] = useState<InspectionData>({
    condoName: 'Condominio San Carlo - Via Luzzatti 5',
    inspectionDate: new Date().toISOString().split('T')[0],
    logoUrl: undefined,
    technicalNotes: 'Sopralluogo effettuato per verifica stato conservativo generale dell\'immobile e delle pertinenze comuni.',
    photos: [],
    availableCategories: DEFAULT_CATEGORIES
  });

  const [isAddingCategory, setIsAddingCategory] = useState(false);
  const [newCatName, setNewCatName] = useState('');
  const [summary, setSummary] = useState('');
  const [isGeneratingSummary, setIsGeneratingSummary] = useState(false);
  const [selectedCategoryFilter, setSelectedCategoryFilter] = useState<string>('Tutte');

  const getCoordinates = (): Promise<Coordinates | undefined> => {
    return new Promise((resolve) => {
      if (!navigator.geolocation) {
        resolve(undefined);
        return;
      }
      navigator.geolocation.getCurrentPosition(
        (position) => {
          resolve({
            latitude: position.coords.latitude,
            longitude: position.coords.longitude
          });
        },
        () => resolve(undefined),
        { timeout: 10000 }
      );
    });
  };

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files) {
      const coords = await getCoordinates();
      const newFiles = Array.from(e.target.files) as File[];
      const newPhotos: InspectionPhoto[] = newFiles.map(file => ({
        id: Math.random().toString(36).substr(2, 9),
        url: URL.createObjectURL(file),
        issue: '',
        supplier: '',
        category: data.availableCategories[0] || DEFAULT_CATEGORIES[0],
        coordinates: coords
      }));
      setData(prev => ({ ...prev, photos: [...prev.photos, ...newPhotos] }));
    }
  };

  const handleLogoChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files?.[0]) {
      const url = URL.createObjectURL(e.target.files[0]);
      setData(prev => ({ ...prev, logoUrl: url }));
    }
  };

  const updatePhoto = (id: string, updates: Partial<InspectionPhoto>) => {
    setData(prev => ({
      ...prev,
      photos: prev.photos.map(p => p.id === id ? { ...p, ...updates } : p)
    }));
  };

  const removePhoto = (id: string) => {
    setData(prev => ({
      ...prev,
      photos: prev.photos.filter(p => p.id !== id)
    }));
  };

  const handleAddCategory = () => {
    const trimmed = newCatName.trim();
    if (trimmed && !data.availableCategories.includes(trimmed)) {
      setData(prev => ({
        ...prev,
        availableCategories: [...prev.availableCategories, trimmed]
      }));
      setNewCatName('');
      setIsAddingCategory(false);
    }
  };

  const handleAIEnhance = async (id: string, currentIssue: string) => {
    if (!currentIssue) return;
    updatePhoto(id, { isLoading: true });
    const polished = await professionalizeDescription(currentIssue);
    updatePhoto(id, { aiPolishedIssue: polished, isLoading: false });
  };

  const handleGenerateReport = async () => {
    setStep(AppStep.REPORT);
    setIsGeneratingSummary(true);
    const issues = data.photos.map(p => p.aiPolishedIssue || p.issue).filter(Boolean);
    const execSummary = await generateExecutiveSummary(data.condoName, issues);
    setSummary(execSummary);
    setIsGeneratingSummary(false);
  };

  const filteredPhotos = useMemo(() => {
    if (selectedCategoryFilter === 'Tutte') return data.photos;
    return data.photos.filter(p => p.category === selectedCategoryFilter);
  }, [data.photos, selectedCategoryFilter]);

  const reportCategories = useMemo(() => {
    const cats = new Set(data.photos.map(p => p.category));
    return ['Tutte', ...Array.from(cats)];
  }, [data.photos]);

  const printReport = async () => {
    setIsExporting(true);
    const reportElement = document.getElementById('final-report');
    if (!reportElement) {
      setIsExporting(false);
      return;
    }

    // Creiamo un clone per manipolare i contenuti prima della stampa
    const clone = reportElement.cloneNode(true) as HTMLElement;

    // Sincronizziamo i valori correnti delle textarea dal DOM originale al clone
    const originalTextareas = reportElement.querySelectorAll('textarea');
    const clonedTextareas = clone.querySelectorAll('textarea');
    const currentValues: string[] = [];

    originalTextareas.forEach((ta, i) => {
      const val = (ta as HTMLTextAreaElement).value;
      currentValues.push(val);
      const clonedTa = clonedTextareas[i] as HTMLTextAreaElement;
      if (clonedTa) {
        clonedTa.value = val;
        clonedTa.style.height = ta.style.height;
      }
    });

    // Creazione iframe nascosto per isolare la stampa
    const iframe = document.createElement('iframe');
    iframe.style.position = 'fixed';
    iframe.style.right = '100vw';
    iframe.style.bottom = '100vh';
    iframe.style.width = '0';
    iframe.style.height = '0';
    iframe.style.border = '0';
    document.body.appendChild(iframe);

    const doc = iframe.contentWindow?.document;
    if (!doc) {
      setIsExporting(false);
      document.body.removeChild(iframe);
      return;
    }

    // Copia tutti gli stili (Tailwind e custom)
    let styles = '';
    document.querySelectorAll('style, link[rel="stylesheet"]').forEach(el => {
      styles += el.outerHTML;
    });

    doc.open();
    doc.write(`
      <html>
        <head>
          <title>Report_${data.condoName.replace(/\s+/g, '_')}</title>
          ${styles}
          <style>
            body { background: white !important; margin: 0; padding: 0; }
            #final-report { box-shadow: none !important; margin: 0 !important; width: 100% !important; padding: 40px !important; }
            @page { margin: 1.5cm; }
            * { -webkit-print-color-adjust: exact !important; print-color-adjust: exact !important; }
            textarea { 
              border: none !important; 
              outline: none !important; 
              resize: none !important; 
              background: transparent !important; 
              overflow: hidden !important; 
              width: 100% !important;
              font-family: inherit !important;
              color: inherit !important;
            }
          </style>
        </head>
        <body>
          <div id="final-report">${clone.innerHTML}</div>
          <script>
            // Re-iniettiamo i valori nelle textarea (innerHTML non mantiene il valore corrente del DOM)
            const textareas = document.querySelectorAll('textarea');
            const vals = ${JSON.stringify(currentValues)};
            textareas.forEach((ta, i) => {
              if (vals[i] !== undefined) ta.value = vals[i];
            });

            window.onload = () => {
              window.print();
              setTimeout(() => {
                window.parent.postMessage('printDone', '*');
              }, 500);
            };
          </script>
        </body>
      </html>
    `);
    doc.close();

    // Pulizia dopo la stampa
    const handlePrintMessage = (e: MessageEvent) => {
      if (e.data === 'printDone') {
        document.body.removeChild(iframe);
        setIsExporting(false);
        window.removeEventListener('message', handlePrintMessage);
      }
    };
    window.addEventListener('message', handlePrintMessage);
  };

  // Aggiorna l'altezza delle textarea al caricamento
  useEffect(() => {
    if (step === AppStep.REPORT) {
      const adjustHeights = () => {
        const textareas = document.querySelectorAll('textarea');
        textareas.forEach(textarea => {
          textarea.style.height = 'auto';
          textarea.style.height = textarea.scrollHeight + 'px';
        });
      };

      adjustHeights();
      // Un secondo passaggio dopo il rendering completo
      const timer = setTimeout(adjustHeights, 300);
      return () => clearTimeout(timer);
    }
  }, [step, summary, filteredPhotos]);

  const isSetupValid = data.condoName && data.inspectionDate;

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col">
      <header className="bg-white border-b border-slate-200 sticky top-0 z-50 px-4 py-4 print:hidden">
        <div className="max-w-4xl mx-auto flex items-center justify-between">
          <div className="flex items-center gap-2">
            <div className="bg-indigo-600 p-2 rounded-lg">
              <Building2 className="text-white w-6 h-6" />
            </div>
            <h1 className="text-xl font-bold text-slate-800">CondoInspect <span className="text-indigo-600">Pro</span></h1>
          </div>
          <div className="flex items-center gap-4">
            <div className="hidden sm:flex items-center gap-1 text-xs font-medium text-slate-400">
               <span className={step === AppStep.SETUP ? 'text-indigo-600' : ''}>Setup</span>
               <ChevronRight className="w-3 h-3" />
               <span className={step === AppStep.PHOTOS ? 'text-indigo-600' : ''}>Foto</span>
               <ChevronRight className="w-3 h-3" />
               <span className={step === AppStep.REPORT ? 'text-indigo-600' : ''}>Report</span>
            </div>
          </div>
        </div>
      </header>

      <main className="flex-1 max-w-4xl mx-auto w-full p-4 sm:p-6 pb-20">
        {step === AppStep.SETUP && (
          <div className="bg-white rounded-2xl shadow-sm border border-slate-200 p-8 animate-in fade-in slide-in-from-bottom-4 duration-500">
            <div className="flex items-center justify-between mb-6">
              <h2 className="text-2xl font-bold text-slate-900">Configurazione Report</h2>
            </div>

            <div className="space-y-6">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div>
                  <label className="block text-sm font-semibold text-slate-700 mb-2">Nome Condominio</label>
                  <div className="relative">
                    <Building2 className="absolute left-3 top-3 w-5 h-5 text-slate-400" />
