                          </div>
                        </div>
                        <div className="space-y-1.5">
                          <label className="text-[10px] font-bold uppercase tracking-widest text-slate-400">Dettagli Problema</label>
                          <div className="relative">
                            <textarea 
                              placeholder="Descrivi cosa hai notato..."
                              className="w-full p-4 bg-slate-50 border border-slate-200 rounded-2xl focus:ring-2 focus:ring-indigo-500 outline-none h-28 resize-none transition-all text-sm leading-relaxed"
                              value={photo.issue}
                              onChange={(e) => updatePhoto(photo.id, { issue: e.target.value })}
                            />
                            <button 
                              onClick={() => handleAIEnhance(photo.id, photo.issue)}
                              disabled={!photo.issue || photo.isLoading}
                              className="absolute bottom-3 right-3 p-2 bg-white border border-slate-200 rounded-xl text-indigo-600 hover:bg-indigo-50 transition-all shadow-sm flex items-center gap-2 disabled:opacity-50"
                            >
                              {photo.isLoading ? <Loader2 className="animate-spin h-3 w-3 text-indigo-600" /> : <Wand2 className="w-3.5 h-3.5" />}
                              <span className="text-[10px] font-black uppercase">Ottimizza con IA</span>
                            </button>
                          </div>
                        </div>
                      </div>
                    </div>

                    {/* AI Suggestion Box - Redesigned to be spacious and adaptive */}
                    {(photo.isLoading || photo.aiPolishedIssue) && (
                      <div className="p-6 bg-gradient-to-br from-indigo-50/80 to-indigo-100/50 border-t border-indigo-200/60 animate-in slide-in-from-top-2 duration-300">
                        <div className="flex flex-col gap-4">
                          <div className="flex items-center justify-between">
                            <div className="flex items-center gap-2 text-indigo-800">
                              <Sparkles className="w-4 h-4 text-indigo-600 animate-pulse" />
                              <span className="text-xs font-black uppercase tracking-widest">Proposta Revisione IA</span>
                            </div>
                            {photo.aiPolishedIssue && (
                              <button 
                                onClick={() => updatePhoto(photo.id, { aiPolishedIssue: undefined })}
                                className="text-slate-400 hover:text-slate-600"
                              >
                                <X className="w-4 h-4" />
                              </button>
                            )}
                          </div>

                          {photo.isLoading ? (
                            <div className="space-y-2 py-2">
                              <div className="h-4 bg-indigo-200/50 rounded-full w-full animate-pulse"></div>
                              <div className="h-4 bg-indigo-200/50 rounded-full w-4/5 animate-pulse"></div>
                            </div>
                          ) : (
                            <div className="flex flex-col md:flex-row gap-6 items-start">
                              <div className="flex-1">
                                <p className="text-sm text-indigo-900 leading-relaxed font-medium italic bg-white/60 p-4 rounded-xl border border-white shadow-sm">
                                  {photo.aiPolishedIssue}
                                </p>
                              </div>
                              <button 
                                onClick={() => updatePhoto(photo.id, { issue: photo.aiPolishedIssue, aiPolishedIssue: undefined })}
                                className="w-full md:w-auto flex items-center justify-center gap-2 bg-indigo-600 text-white px-6 py-3 rounded-xl hover:bg-indigo-700 transition-all shadow-lg shadow-indigo-200 font-bold text-sm shrink-0 whitespace-nowrap active:scale-95"
                              >
                                <ArrowDownLeft className="w-4 h-4" />
                                Applica Revisione
                              </button>
                            </div>
                          )}
                        </div>
                      </div>
                    )}
                  </div>
                ))
              )}
            </div>

            <div className="pt-10 border-t border-slate-200 mt-10">
              <button 
                disabled={!isSetupValid}
                onClick={handleGenerateReport}
                className="w-full bg-emerald-600 hover:bg-emerald-700 disabled:bg-slate-300 text-white font-bold py-5 rounded-2xl shadow-xl shadow-emerald-200 flex items-center justify-center gap-3 transition-all active:scale-95"
              >
                Genera Documento Finale <FileText className="w-6 h-6" />
              </button>
            </div>
          </div>
        )}

        {step === AppStep.REPORT && (
          <div className="space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-500 print:p-0 print:m-0">
            <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 print:hidden">
              <button 
                onClick={() => setStep(AppStep.PHOTOS)}
                className="flex items-center gap-2 text-slate-500 hover:text-slate-800 transition-colors font-medium"
              >
                <ChevronLeft className="w-5 h-5" /> Torna alle Rilevazioni
              </button>

              <div className="flex items-center gap-3">
                <div className="flex items-center gap-2 bg-white px-4 py-2.5 rounded-2xl border border-slate-200 shadow-sm">
                  <Filter className="w-4 h-4 text-slate-400" />
                  <select 
                    className="text-sm bg-transparent outline-none font-bold text-slate-700"
                    value={selectedCategoryFilter}
                    onChange={(e) => setSelectedCategoryFilter(e.target.value)}
                  >
                    {reportCategories.map(cat => (
                      <option key={cat} value={cat}>{cat}</option>
                    ))}
                  </select>
                </div>
                <button 
                  onClick={printReport}
                  disabled={isExporting}
                  className="bg-slate-900 text-white px-8 py-3 rounded-2xl hover:bg-slate-800 disabled:bg-slate-400 transition-all shadow-xl flex items-center gap-3 font-bold"
                >
                  {isExporting ? <Loader2 className="animate-spin w-5 h-5" /> : <Download className="w-5 h-5" />}
                  {isExporting ? 'Esportazione...' : 'Salva PDF'}
                </button>
              </div>
            </div>

            <div id="final-report" className="bg-white shadow-2xl rounded-sm p-12 print:shadow-none print:p-0 print:m-0">
              <div className="border-b-8 border-indigo-600 pb-10 mb-10 flex items-start justify-between">
                <div>
                  <h1 className="text-4xl font-black text-slate-900 uppercase tracking-tighter mb-2">Verbale di Sopralluogo</h1>
                  <div className="flex items-center gap-2 text-indigo-600">
                    <CheckCircle2 className="w-4 h-4" />
                    <p className="font-black tracking-widest uppercase text-xs">Certificato CondoInspect Pro</p>
                  </div>
                </div>
                {data.logoUrl && (
                  <img src={data.logoUrl} alt="Logo Condominio" className="h-20 w-auto object-contain" />
                )}
              </div>

              <div className="grid grid-cols-1 md:grid-cols-3 gap-8 mb-12">
                <div className="bg-slate-50 p-6 rounded-2xl border border-slate-100">
                  <h3 className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-2">Condominio</h3>
                  <p className="text-xl font-black text-slate-800">{data.condoName}</p>
                </div>
                <div className="bg-slate-50 p-6 rounded-2xl border border-slate-100">
                  <h3 className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-2">Data</h3>
                  <p className="text-xl font-black text-slate-800">{new Date(data.inspectionDate).toLocaleDateString('it-IT', { day: 'numeric', month: 'long', year: 'numeric' })}</p>
                </div>
                <div className="bg-indigo-50 p-6 rounded-2xl border border-indigo-100">
                  <h3 className="text-[10px] font-bold text-indigo-400 uppercase tracking-widest mb-2">Volume Rilievi</h3>
                  <p className="text-indigo-900 font-black text-xl">{filteredPhotos.length} <span className="text-sm font-medium">Segnalazioni</span></p>
                </div>
              </div>

              <div className="mb-16 bg-slate-900 p-8 rounded-3xl text-white relative group overflow-hidden">
                <div className="absolute top-0 right-0 w-32 h-32 bg-indigo-500/10 rounded-full -mr-16 -mt-16 blur-3xl"></div>
                <div className="flex items-center justify-between mb-3">
                  <h3 className="text-xs font-bold text-indigo-400 uppercase tracking-[0.2em]">Sintesi Esecutiva</h3>
                  <Edit3 className="w-4 h-4 text-indigo-400/50 print:hidden" />
                </div>
                {isGeneratingSummary ? (
                   <p className="text-lg font-light italic text-indigo-200">Generazione riepilogo professionale...</p>
                ) : (
                  <>
                    <textarea 
                      className="w-full bg-transparent border-none text-white text-lg leading-relaxed font-light italic resize-none focus:ring-1 focus:ring-indigo-500/50 p-0 outline-none print-text-area"
                      rows={4}
                      value={summary}
                      onChange={(e) => setSummary(e.target.value)}
                    />
                    <div className="print-text-mirror text-white text-lg leading-relaxed font-light italic">
                      {summary}
                    </div>
                  </>
                )}
              </div>

              <div className="space-y-24">
                {filteredPhotos.map((indexPhoto, idx) => (
                  <div key={indexPhoto.id} className="break-inside-avoid">
                    <div className="flex items-center justify-between mb-6 border-b-2 border-slate-50 pb-4">
                      <div className="flex items-center gap-4">
                        <span className="bg-indigo-600 text-white w-10 h-10 rounded-2xl flex items-center justify-center font-black text-lg rotate-3">{idx + 1}</span>
                        <div>
                          <h4 className="text-xl font-black text-slate-800 tracking-tight">{indexPhoto.category}</h4>
                        </div>
                      </div>
                      <div className="text-right">
                        <span className="text-[9px] font-bold text-slate-400 uppercase tracking-widest">Incaricato</span>
                        <p className="text-lg font-black text-indigo-600">{indexPhoto.supplier}</p>
                      </div>
                    </div>

                    <div className="grid grid-cols-1 md:grid-cols-12 gap-10">
                      <div className="md:col-span-5 space-y-3">
                        <div className="aspect-[4/3] rounded-3xl overflow-hidden shadow-2xl border-4 border-white">
                          <img src={indexPhoto.url} alt={`Rilievo ${idx + 1}`} className="w-full h-full object-cover" />
                        </div>
                        {indexPhoto.coordinates && (
                          <div className="flex items-center gap-2 text-[10px] font-bold text-slate-400 bg-slate-50 p-2 rounded-xl">
                            <MapPin className="w-3 h-3 text-indigo-500" />
                            GEO-REF: {indexPhoto.coordinates.latitude.toFixed(6)}, {indexPhoto.coordinates.longitude.toFixed(6)}
                          </div>
                        )}
                      </div>
                      <div className="md:col-span-7 py-2">
                        <div className="h-full flex flex-col">
                          <div className="flex-1">
                            <div className="flex items-center justify-between mb-4">
                              <h5 className="text-[10px] font-bold text-slate-300 uppercase tracking-widest flex items-center gap-2">
                                <span className="w-1.5 h-1.5 bg-indigo-500 rounded-full"></span>
                                Osservazione del Rilevatore
                              </h5>
                              <Edit3 className="w-3 h-3 text-slate-300 print:hidden" />
                            </div>
                            <textarea 
                              className="w-full text-slate-800 text-lg leading-relaxed font-medium bg-indigo-50/30 p-8 rounded-[2rem] border-2 border-indigo-50 resize-none outline-none focus:ring-2 focus:ring-indigo-200/50 transition-all print-text-area"
                              rows={4}
                              value={indexPhoto.aiPolishedIssue || indexPhoto.issue}
                              onChange={(e) => {
                                updatePhoto(indexPhoto.id, { 
                                  aiPolishedIssue: e.target.value,
                                  issue: e.target.value 
                                });
                              }}
                            />
                            <div className="print-text-mirror text-slate-800 text-lg leading-relaxed font-medium bg-indigo-50/30 p-8 rounded-[2rem]">
                              {indexPhoto.aiPolishedIssue || indexPhoto.issue}
                            </div>
                          </div>
                          <div className="mt-8 grid grid-cols-2 gap-4">
                            <div className="bg-slate-50 px-4 py-3 rounded-2xl flex items-center gap-3 border border-slate-100">
                              <CheckCircle2 className="w-5 h-5 text-emerald-500" />
                              <span className="text-[10px] font-bold uppercase text-slate-500 tracking-widest">Stato: Confermato</span>
                            </div>
                            <div className="bg-slate-50 px-4 py-3 rounded-2xl flex items-center gap-3 border border-slate-100">
                              <Tag className="w-5 h-5 text-indigo-500" />
                              <span className="text-[10px] font-bold uppercase text-slate-500 tracking-widest">Priorità: Alta</span>
                            </div>
                          </div>
                        </div>
                      </div>
                    </div>
                  </div>
                ))}
              </div>

              {data.technicalNotes && (
                <div className="mt-32 pt-16 border-t-4 border-indigo-600/10 break-inside-avoid">
                  <h3 className="text-xl font-black text-slate-900 uppercase tracking-tight mb-6 flex items-center gap-3">
                    <StickyNote className="w-8 h-8 text-indigo-600" /> Note Integrative
                  </h3>
                  <div className="bg-slate-50 p-10 rounded-[3rem] border-2 border-slate-100 text-slate-700 text-lg leading-relaxed whitespace-pre-wrap font-medium italic shadow-inner">
                    {data.technicalNotes}
                  </div>
                </div>
              )}

              <div className="mt-40 pt-16 border-t-4 border-slate-900 flex justify-end">
                <div className="text-center w-80">
                  <div className="h-0.5 bg-slate-200 w-full mb-6"></div>
                  <p className="text-xs font-black text-slate-400 uppercase tracking-[0.3em]">L'Amministratore</p>
                </div>
              </div>

              <footer className="mt-32 text-center text-[10px] text-slate-300 font-bold uppercase tracking-[0.4em] pt-8 border-t border-slate-50">
                Documentazione Digitale CondoInspect Pro - {new Date().toLocaleDateString('it-IT')}
              </footer>
            </div>
          </div>
        )}
      </main>
    </div>
  );
};

export default App;

import React, { useState, useMemo, useEffect } from 'react';
import { 
  Building2, 
  Calendar, 
  Camera, 
  Trash2, 
  ChevronRight, 
  ChevronLeft, 
  FileText, 
  Download,
  Wand2,
  CheckCircle2,
  MapPin,
  Tag,
  Plus,
  Image as ImageIcon,
  StickyNote,
  Filter,
  X,
  Check,
  Edit3,
  Loader2,
  Sparkles,
  ArrowDownLeft
} from 'lucide-react';
import { AppStep, InspectionData, InspectionPhoto, Coordinates } from './types';
import { professionalizeDescription, generateExecutiveSummary } from './services/geminiService';

const DEFAULT_CATEGORIES = ['Strutturale', 'Impianto Idraulico', 'Impianto Elettrico', 'Estetica/Facciata', 'Aree Comuni', 'Sicurezza'];

const App: React.FC = () => {
  const [step, setStep] = useState<AppStep>(AppStep.SETUP);
  const [isExporting, setIsExporting] = useState(false);
  const [data, setData] = useState<InspectionData>({
    condoName: 'Condominio San Carlo - Via Luzzatti 5',
    inspectionDate: new Date().toISOString().split('T')[0],
    logoUrl: undefined,
    technicalNotes: 'Sopralluogo effettuato per verifica stato conservativo generale dell\'immobile e delle pertinenze comuni.',
    photos: [],
    availableCategories: DEFAULT_CATEGORIES
  });

  const [isAddingCategory, setIsAddingCategory] = useState(false);
  const [newCatName, setNewCatName] = useState('');
  const [summary, setSummary] = useState('');
  const [isGeneratingSummary, setIsGeneratingSummary] = useState(false);
  const [selectedCategoryFilter, setSelectedCategoryFilter] = useState<string>('Tutte');

  // Funzione helper per ricalcolare l'altezza di una textarea
  const adjustTextareaHeight = (target: HTMLTextAreaElement) => {
    target.style.height = 'auto';
    target.style.height = `${target.scrollHeight}px`;
  };

  // Effetto per aggiustare le altezze iniziali quando cambiano i dati o lo step
  useEffect(() => {
    const timer = setTimeout(() => {
      document.querySelectorAll('textarea').forEach(ta => adjustTextareaHeight(ta as HTMLTextAreaElement));
    }, 100);
    return () => clearTimeout(timer);
  }, [step, summary, data.photos, filteredPhotos]);

  useEffect(() => {
    const handleAfterPrint = () => {
      setIsExporting(false);
    };
    window.addEventListener('afterprint', handleAfterPrint);
    return () => window.removeEventListener('afterprint', handleAfterPrint);
  }, []);

  const getCoordinates = (): Promise<Coordinates | undefined> => {
    return new Promise((resolve) => {
      if (!navigator.geolocation) {
        resolve(undefined);
        return;
      }
      navigator.geolocation.getCurrentPosition(
        (position) => {
          resolve({
            latitude: position.coords.latitude,
            longitude: position.coords.longitude
          });
        },
        () => resolve(undefined),
        { timeout: 10000 }
      );
    });
  };

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files) {
      const coords = await getCoordinates();
      const newFiles = Array.from(e.target.files) as File[];
      const newPhotos: InspectionPhoto[] = newFiles.map(file => ({
        id: Math.random().toString(36).substr(2, 9),
        url: URL.createObjectURL(file),
        issue: '',
        supplier: '',
        category: data.availableCategories[0] || DEFAULT_CATEGORIES[0],
        coordinates: coords
      }));
      setData(prev => ({ ...prev, photos: [...prev.photos, ...newPhotos] }));
    }
  };

  const handleLogoChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files?.[0]) {
      const url = URL.createObjectURL(e.target.files[0]);
      setData(prev => ({ ...prev, logoUrl: url }));
    }
  };

  const updatePhoto = (id: string, updates: Partial<InspectionPhoto>) => {
    setData(prev => ({
      ...prev,
      photos: prev.photos.map(p => p.id === id ? { ...p, ...updates } : p)
    }));
  };

  const removePhoto = (id: string) => {
    setData(prev => ({
      ...prev,
      photos: prev.photos.filter(p => p.id !== id)
    }));
  };

  const handleAddCategory = () => {
    const trimmed = newCatName.trim();
    if (trimmed && !data.availableCategories.includes(trimmed)) {
      setData(prev => ({
        ...prev,
        availableCategories: [...prev.availableCategories, trimmed]
      }));
      setNewCatName('');
      setIsAddingCategory(false);
    }
  };

  const handleAIEnhance = async (id: string, currentIssue: string) => {
    if (!currentIssue) return;
    updatePhoto(id, { isLoading: true, aiPolishedIssue: undefined });
    const polished = await professionalizeDescription(currentIssue);
    updatePhoto(id, { aiPolishedIssue: polished, isLoading: false });
  };

  const handleGenerateReport = async () => {
    setStep(AppStep.REPORT);
    setIsGeneratingSummary(true);
    const issues = data.photos.map(p => p.aiPolishedIssue || p.issue).filter(Boolean);
    const execSummary = await generateExecutiveSummary(data.condoName, issues);
    setSummary(execSummary);
    setIsGeneratingSummary(false);
  };

  const filteredPhotos = useMemo(() => {
    if (selectedCategoryFilter === 'Tutte') return data.photos;
    return data.photos.filter(p => p.category === selectedCategoryFilter);
  }, [data.photos, selectedCategoryFilter]);

  const reportCategories = useMemo(() => {
    const cats = new Set(data.photos.map(p => p.category));
    return ['Tutte', ...Array.from(cats)];
  }, [data.photos]);

  const printReport = () => {
    setIsExporting(true);
    setTimeout(() => {
      window.print();
    }, 100);
  };

  const isSetupValid = data.condoName && data.inspectionDate;

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col">
      <header className="bg-white border-b border-slate-200 sticky top-0 z-50 px-4 py-4 print:hidden">
        <div className="max-w-4xl mx-auto flex items-center justify-between">
          <div className="flex items-center gap-2">
            <div className="bg-indigo-600 p-2 rounded-lg">
              <Building2 className="text-white w-6 h-6" />
            </div>
            <h1 className="text-xl font-bold text-slate-800">CondoInspect <span className="text-indigo-600">Pro</span></h1>
          </div>
          <div className="flex items-center gap-4">
            <div className="hidden sm:flex items-center gap-1 text-xs font-medium text-slate-400">
               <span className={step === AppStep.SETUP ? 'text-indigo-600' : ''}>Setup</span>
               <ChevronRight className="w-3 h-3" />
               <span className={step === AppStep.PHOTOS ? 'text-indigo-600' : ''}>Foto</span>
               <ChevronRight className="w-3 h-3" />
               <span className={step === AppStep.REPORT ? 'text-indigo-600' : ''}>Report</span>
            </div>
          </div>
        </div>
      </header>

      <main className="flex-1 max-w-4xl mx-auto w-full p-4 sm:p-6 pb-20 print:p-0 print:m-0">
        {step === AppStep.SETUP && (
          <div className="bg-white rounded-2xl shadow-sm border border-slate-200 p-8 animate-in fade-in slide-in-from-bottom-4 duration-500">
            <div className="flex items-center justify-between mb-6">
              <h2 className="text-2xl font-bold text-slate-900">Configurazione Report</h2>
            </div>

            <div className="space-y-6">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div>
                  <label className="block text-sm font-semibold text-slate-700 mb-2">Nome Condominio</label>
                  <div className="relative">
                    <Building2 className="absolute left-3 top-3 w-5 h-5 text-slate-400" />
                    <input 
                      type="text" 
                      placeholder="Esempio: Condominio Belvedere"
                      className="w-full pl-10 pr-4 py-3 bg-slate-50 border border-slate-200 rounded-xl focus:ring-2 focus:ring-indigo-500 outline-none transition-all"
                      value={data.condoName}
                      onChange={(e) => setData({...data, condoName: e.target.value})}
                    />
                  </div>
                </div>
                <div>
                  <label className="block text-sm font-semibold text-slate-700 mb-2">Data Sopralluogo</label>
                  <div className="relative">
                    <Calendar className="absolute left-3 top-3 w-5 h-5 text-slate-400" />
                    <input 
                      type="date" 
                      className="w-full pl-10 pr-4 py-3 bg-slate-50 border border-slate-200 rounded-xl focus:ring-2 focus:ring-indigo-500 outline-none transition-all"
                      value={data.inspectionDate}
                      onChange={(e) => setData({...data, inspectionDate: e.target.value})}
                    />
                  </div>
                </div>
              </div>

              <div>
                <label className="block text-sm font-semibold text-slate-700 mb-2">Logo Condominio (opzionale)</label>
                <div className="flex items-center gap-4">
                  <label className="flex-1 border-2 border-dashed border-slate-200 rounded-xl p-4 flex items-center justify-center gap-3 cursor-pointer hover:bg-slate-50 hover:border-indigo-300 transition-all">
                    {data.logoUrl ? (
                      <img src={data.logoUrl} alt="Logo" className="h-12 w-auto object-contain" />
                    ) : (
                      <div className="flex items-center gap-2 text-slate-400">
                        <ImageIcon className="w-5 h-5" />
                        <span className="text-sm">Carica Logo</span>
                      </div>
                    )}
                    <input type="file" accept="image/*" className="hidden" onChange={handleLogoChange} />
                  </label>
                  {data.logoUrl && (
                    <button onClick={() => setData({...data, logoUrl: undefined})} className="p-3 text-red-500 hover:bg-red-50 rounded-xl transition-all">
                      <Trash2 className="w-5 h-5" />
                    </button>
                  )}
                </div>
              </div>

              <div>
                <label className="block text-sm font-semibold text-slate-700 mb-2">Note Aggiuntive</label>
                <div className="relative">
                  <StickyNote className="absolute left-3 top-3 w-5 h-5 text-slate-400" />
                  <textarea 
                    placeholder="Inserisci note aggiuntive che compariranno alla fine del report..."
                    className="w-full pl-10 pr-4 py-3 bg-slate-50 border border-slate-200 rounded-xl focus:ring-2 focus:ring-indigo-500 outline-none min-h-[120px] resize-none transition-all overflow-hidden"
                    value={data.technicalNotes}
                    onChange={(e) => {
                      setData({...data, technicalNotes: e.target.value});
                      adjustTextareaHeight(e.target);
                    }}
                  />
                </div>
              </div>
            </div>
            <button 
              disabled={!isSetupValid}
              onClick={() => setStep(AppStep.PHOTOS)}
