            <div className="p-2 rounded-lg" style={{ backgroundColor: PRIMARY_COLOR }}>
              <Briefcase className="text-white w-6 h-6" />
            </div>
            <div>
              <h1 className="text-lg font-bold text-slate-800 leading-tight">Studio Ing. Serra</h1>
              <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest">CondoInspect Pro</p>
            </div>
          </div>
          <div className="flex items-center gap-4">
            <div className="hidden sm:flex items-center gap-1 text-xs font-medium text-slate-400">
               <span className={step === AppStep.SETUP ? 'font-bold' : ''} style={{ color: step === AppStep.SETUP ? PRIMARY_COLOR : undefined }}>Setup</span>
               <ChevronRight className="w-3 h-3" />
               <span className={step === AppStep.PHOTOS ? 'font-bold' : ''} style={{ color: step === AppStep.PHOTOS ? PRIMARY_COLOR : undefined }}>Foto</span>
               <ChevronRight className="w-3 h-3" />
               <span className={step === AppStep.REPORT ? 'font-bold' : ''} style={{ color: step === AppStep.REPORT ? PRIMARY_COLOR : undefined }}>Report</span>
            </div>
          </div>
        </div>
      </header>

      <main className="flex-1 max-w-4xl mx-auto w-full p-4 sm:p-6 pb-20 print:p-0 print:m-0">
        {step === AppStep.SETUP && (
          <div className="bg-white rounded-2xl shadow-sm border border-slate-200 p-8 animate-in fade-in slide-in-from-bottom-4 duration-500">
            <div className="flex items-center justify-between mb-8 pb-4 border-b border-slate-100">
              <div>
                <h2 className="text-2xl font-bold text-slate-900">Nuovo Sopralluogo</h2>
                <p className="text-sm text-slate-500 mt-1">{STUDIO_NAME}</p>
              </div>
              <div className="hidden sm:block">
                 <img src="https://api.dicebear.com/7.x/initials/svg?seed=SS&backgroundColor=64a1a4&fontFamily=Inter&fontWeight=bold" className="w-12 h-12 rounded-xl shadow-sm" alt="Studio Logo" />
              </div>
            </div>

            <div className="space-y-6">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div>
                  <label className="block text-sm font-semibold text-slate-700 mb-2">Nome Condominio</label>
                  <div className="relative">
                    <Building2 className="absolute left-3 top-3 w-5 h-5 text-slate-400" />
                    <input 
                      type="text" 
                      placeholder="es. Condominio Roma 24"
                      className="w-full pl-10 pr-4 py-3 bg-slate-50 border border-slate-200 rounded-xl focus:ring-2 outline-none transition-all"
                      style={{ '--tw-ring-color': PRIMARY_COLOR } as any}
                      value={data.condoName}
                      onChange={(e) => setData({...data, condoName: e.target.value})}
                    />
                  </div>
                </div>
                <div>
                  <label className="block text-sm font-semibold text-slate-700 mb-2">Data Sopralluogo</label>
                  <div className="relative">
                    <Calendar className="absolute left-3 top-3 w-5 h-5 text-slate-400" />
                    <input 
                      type="date" 
                      className="w-full pl-10 pr-4 py-3 bg-slate-50 border border-slate-200 rounded-xl focus:ring-2 outline-none transition-all"
                      style={{ '--tw-ring-color': PRIMARY_COLOR } as any}
                      value={data.inspectionDate}
                      onChange={(e) => setData({...data, inspectionDate: e.target.value})}
                    />
                  </div>
                </div>
