                              value={indexPhoto.aiPolishedIssue || indexPhoto.issue}
                              onChange={(e) => {
                                updatePhoto(indexPhoto.id, { 
                                  aiPolishedIssue: e.target.value,
                                  issue: e.target.value 
                                });
                                adjustTextareaHeight(e.target);
                              }}
                            />
                            <div className="print-text-mirror text-slate-800 text-xl leading-relaxed font-bold italic bg-slate-50/50 p-12 rounded-[3.5rem] border-2 border-slate-50">
                              {indexPhoto.aiPolishedIssue || indexPhoto.issue}
                            </div>
                          </div>
                        </div>
                      </div>
                    </div>
                  </div>
                ))}
              </div>

              {/* Note Integrative */}
              {data.technicalNotes && (
                <div className="mt-40 pt-20 border-t-8 border-slate-50 break-inside-avoid">
                  <h3 className="text-2xl font-black text-slate-900 uppercase tracking-tight mb-10 flex items-center gap-5 italic" style={{ color: PRIMARY_COLOR }}>
                    <StickyNote className="w-10 h-10" /> Note Integrative
                  </h3>
                  <div className="bg-slate-50 p-14 rounded-[4rem] border border-slate-100 text-slate-800 text-xl leading-relaxed whitespace-pre-wrap font-bold italic">
                    {data.technicalNotes}
