              <div className="mt-48 pt-20 border-t-4 border-slate-900 flex justify-between items-end">
                <div className="max-w-md">
                  <p className="text-[11px] font-black text-slate-400 uppercase tracking-[0.4em] mb-6">Emesso da:</p>
                  <p className="text-base font-black text-slate-900 uppercase tracking-tight leading-tight">{STUDIO_NAME}</p>
                </div>
                <div className="text-center w-96">
                  <div className="h-0.5 bg-slate-200 w-full mb-8"></div>
                  <p className="text-xs font-black text-slate-400 uppercase tracking-[0.5em] mb-2">Firma Ing. Serra</p>
                </div>
              </div>
            </div>
          </div>
        )}
      </main>
    </div>
  );
};

export default App;

import React, { useState, useMemo, useEffect } from 'react';
import { 
  Building2, 
  Calendar, 
  Camera, 
  Trash2, 
  ChevronRight, 
  ChevronLeft, 
  FileText, 
  Download,
  Wand2,
  CheckCircle2,
  MapPin,
  Tag,
  Plus,
  Image as ImageIcon,
  StickyNote,
  Filter,
  X,
  Check,
  Edit3,
  Loader2,
  Sparkles,
  ArrowDownLeft,
  Briefcase,
  Search
} from 'lucide-react';
import { AppStep, InspectionData, InspectionPhoto, Coordinates } from './types';
import { professionalizeDescription, generateExecutiveSummary } from './services/geminiService';

const DEFAULT_CATEGORIES = ['Strutturale', 'Impianto Idraulico', 'Impianto Elettrico', 'Estetica/Facciata', 'Aree Comuni', 'Sicurezza'];
const STUDIO_NAME = "Studio Amministrazioni Condominiali Ing. Serra";
const STUDIO_TAGLINE = "il condominio trasparente: tutto limpido, tutto evidente";
const PRIMARY_COLOR = "#64a1a4"; // Colore ufficiale estratto dal logo Studio Serra

const App: React.FC = () => {
  const [step, setStep] = useState<AppStep>(AppStep.SETUP);
  const [isExporting, setIsExporting] = useState(false);
  const [data, setData] = useState<InspectionData>({
    condoName: '',
    inspectionDate: new Date().toISOString().split('T')[0],
    logoUrl: undefined,
    technicalNotes: 'Sopralluogo effettuato per verifica stato conservativo generale dell\'immobile e delle pertinenze comuni.',
    photos: [],
    availableCategories: DEFAULT_CATEGORIES
  });

  const [isAddingCategory, setIsAddingCategory] = useState(false);
  const [newCatName, setNewCatName] = useState('');
  const [summary, setSummary] = useState('');
  const [isGeneratingSummary, setIsGeneratingSummary] = useState(false);
  const [selectedCategoryFilter, setSelectedCategoryFilter] = useState<string>('Tutte');

  // Calcolo validazione step iniziale
  const isSetupValid = useMemo(() => {
    return data.condoName.trim().length > 0 && data.inspectionDate.length > 0;
  }, [data.condoName, data.inspectionDate]);

  const filteredPhotos = useMemo(() => {
    if (selectedCategoryFilter === 'Tutte') return data.photos;
    return data.photos.filter(p => p.category === selectedCategoryFilter);
  }, [data.photos, selectedCategoryFilter]);

  const reportCategories = useMemo(() => {
    const cats = new Set(data.photos.map(p => p.category));
    return ['Tutte', ...Array.from(cats)];
  }, [data.photos]);

  const adjustTextareaHeight = (target: HTMLTextAreaElement) => {
    if (!target) return;
    target.style.height = 'auto';
    target.style.height = `${target.scrollHeight}px`;
  };

  // Effetto per aggiustare le altezze iniziali quando cambiano i dati o lo step
  useEffect(() => {
    // Non ricalcoliamo le altezze se stiamo esportando per non bloccare il thread
    if (isExporting) return;

    const timer = setTimeout(() => {
      document.querySelectorAll('textarea').forEach(ta => adjustTextareaHeight(ta as HTMLTextAreaElement));
    }, 150);
    return () => clearTimeout(timer);
  }, [step, summary, data.photos, filteredPhotos, isExporting]);

  useEffect(() => {
    const handleAfterPrint = () => {
      setIsExporting(false);
    };
    window.addEventListener('afterprint', handleAfterPrint);
    return () => window.removeEventListener('afterprint', handleAfterPrint);
  }, []);

  const getCoordinates = (): Promise<Coordinates | undefined> => {
    return new Promise((resolve) => {
      if (!navigator.geolocation) {
        resolve(undefined);
        return;
      }
      navigator.geolocation.getCurrentPosition(
        (position) => {
          resolve({
            latitude: position.coords.latitude,
            longitude: position.coords.longitude
          });
        },
        () => resolve(undefined),
        { timeout: 5000 } // Ridotto timeout per evitare attese infinite
      );
    });
  };

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files) {
      const coords = await getCoordinates();
      const newFiles = Array.from(e.target.files) as File[];
      const newPhotos: InspectionPhoto[] = newFiles.map(file => ({
        id: Math.random().toString(36).substr(2, 9),
        url: URL.createObjectURL(file),
        issue: '',
        supplier: '',
        category: data.availableCategories[0] || DEFAULT_CATEGORIES[0],
        coordinates: coords
      }));
      setData(prev => ({ ...prev, photos: [...prev.photos, ...newPhotos] }));
    }
  };

  const handleLogoChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files?.[0]) {
      const url = URL.createObjectURL(e.target.files[0]);
      setData(prev => ({ ...prev, logoUrl: url }));
    }
  };

  const updatePhoto = (id: string, updates: Partial<InspectionPhoto>) => {
    setData(prev => ({
      ...prev,
      photos: prev.photos.map(p => p.id === id ? { ...p, ...updates } : p)
    }));
  };

  const removePhoto = (id: string) => {
    setData(prev => ({
      ...prev,
      photos: prev.photos.filter(p => p.id !== id)
    }));
  };

  const handleAddCategory = () => {
    const trimmed = newCatName.trim();
    if (trimmed && !data.availableCategories.includes(trimmed)) {
      setData(prev => ({
        ...prev,
        availableCategories: [...prev.availableCategories, trimmed]
      }));
      setNewCatName('');
      setIsAddingCategory(false);
    }
  };

  const handleAIEnhance = async (id: string, currentIssue: string) => {
    if (!currentIssue) return;
    updatePhoto(id, { isLoading: true, aiPolishedIssue: undefined });
    const polished = await professionalizeDescription(currentIssue);
    updatePhoto(id, { aiPolishedIssue: polished, isLoading: false });
  };

  const handleGenerateReport = async () => {
    setStep(AppStep.REPORT);
    setIsGeneratingSummary(true);
    const issues = data.photos.map(p => p.aiPolishedIssue || p.issue).filter(Boolean);
    const execSummary = await generateExecutiveSummary(data.condoName, issues);
    setSummary(execSummary);
    setIsGeneratingSummary(false);
  };

  const printReport = () => {
    if (isExporting) return;

    setIsExporting(true);
    // Un timeout più lungo permette al browser di finire il rendering degli elementi grafici
    // e di liberare risorse prima di avviare il processo di stampa PDF
    setTimeout(() => {
      window.print();
      // In alcuni browser afterprint non viene chiamato se la finestra si chiude subito
      // Aggiungiamo un fallback per resettare lo stato dopo un po'
      setTimeout(() => setIsExporting(false), 3000);
    }, 500);
  };

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col">
      <header className="bg-white border-b border-slate-200 sticky top-0 z-50 px-4 py-4 print:hidden">
        <div className="max-w-4xl mx-auto flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="p-2.5 rounded-xl shadow-sm" style={{ backgroundColor: PRIMARY_COLOR }}>
              <Briefcase className="text-white w-5 h-5" />
            </div>
            <div>
              <h1 className="text-base font-black text-slate-800 leading-none">Studio Ing. Serra</h1>
              <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest mt-1">Management Pro</p>
            </div>
          </div>
          <div className="flex items-center gap-4">
            <div className="hidden sm:flex items-center gap-1 text-[10px] font-black uppercase tracking-widest text-slate-400">
               <span className={step === AppStep.SETUP ? 'font-black' : ''} style={{ color: step === AppStep.SETUP ? PRIMARY_COLOR : undefined }}>01 Setup</span>
               <ChevronRight className="w-3 h-3 mx-1" />
               <span className={step === AppStep.PHOTOS ? 'font-black' : ''} style={{ color: step === AppStep.PHOTOS ? PRIMARY_COLOR : undefined }}>02 Rilievi</span>
               <ChevronRight className="w-3 h-3 mx-1" />
               <span className={step === AppStep.REPORT ? 'font-black' : ''} style={{ color: step === AppStep.REPORT ? PRIMARY_COLOR : undefined }}>03 Verbale</span>
            </div>
          </div>
        </div>
      </header>

      <main className="flex-1 max-w-4xl mx-auto w-full p-4 sm:p-6 pb-20 print:p-0 print:m-0">
        {step === AppStep.SETUP && (
          <div className="bg-white rounded-3xl shadow-sm border border-slate-200 p-8 sm:p-10 animate-in fade-in slide-in-from-bottom-4 duration-500">
            <div className="flex flex-col sm:flex-row items-center justify-between mb-10 pb-6 border-b border-slate-100 gap-6">
              <div className="text-center sm:text-left">
                <h2 className="text-3xl font-black text-slate-900 tracking-tight italic" style={{ color: PRIMARY_COLOR }}>STUDIO SERRA</h2>
                <p className="text-sm font-bold text-slate-500 mt-1 uppercase tracking-wider">{STUDIO_NAME}</p>
                <p className="text-xs text-slate-400 mt-1 italic">{STUDIO_TAGLINE}</p>
              </div>
              <div className="flex shrink-0">
                 {data.logoUrl && (
                   <div className="w-20 h-20 rounded-2xl border-2 border-slate-100 p-1 flex items-center justify-center bg-slate-50 shadow-inner">
                     <img src={data.logoUrl} className="w-full h-full rounded-xl object-contain" alt="Logo Studio" />
                   </div>
                 )}
              </div>
            </div>

            <div className="space-y-8">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                <div className="space-y-2">
                  <label className="text-xs font-black uppercase tracking-widest text-slate-500 ml-1">Nome del Condominio <span className="text-red-500">*</span></label>
                  <div className="relative group">
                    <Building2 className="absolute left-4 top-1/2 -translate-y-1/2 w-5 h-5 text-slate-400 transition-colors group-focus-within:text-[#64a1a4]" />
                    <input 
                      type="text" 
                      placeholder="es. Condominio San Giacomo"
                      className="w-full pl-12 pr-4 py-4 bg-slate-50 border border-slate-200 rounded-2xl focus:ring-2 outline-none transition-all font-medium text-slate-800"
                      style={{ '--tw-ring-color': PRIMARY_COLOR } as any}
                      value={data.condoName}
                      onChange={(e) => setData({...data, condoName: e.target.value})}
                    />
                  </div>
                </div>
                <div className="space-y-2">
                  <label className="text-xs font-black uppercase tracking-widest text-slate-500 ml-1">Data del Sopralluogo <span className="text-red-500">*</span></label>
                  <div className="relative group">
                    <Calendar className="absolute left-4 top-1/2 -translate-y-1/2 w-5 h-5 text-slate-400 transition-colors group-focus-within:text-[#64a1a4]" />
                    <input 
                      type="date" 
                      className="w-full pl-12 pr-4 py-4 bg-slate-50 border border-slate-200 rounded-2xl focus:ring-2 outline-none transition-all font-medium text-slate-800"
                      style={{ '--tw-ring-color': PRIMARY_COLOR } as any}
                      value={data.inspectionDate}
                      onChange={(e) => setData({...data, inspectionDate: e.target.value})}
                    />
                  </div>
                </div>
              </div>

              <div className="space-y-2">
                <label className="text-xs font-black uppercase tracking-widest text-slate-500 ml-1">Logo Ufficiale Studio Serra</label>
                <div className="flex items-center gap-4">
                  <label className="flex-1 border-2 border-dashed border-slate-200 rounded-2xl p-6 flex flex-col items-center justify-center gap-2 cursor-pointer hover:bg-slate-50 transition-all">
                    {data.logoUrl ? (
                      <div className="flex flex-col items-center gap-2">
                        <img src={data.logoUrl} alt="Logo" className="h-16 w-auto object-contain" />
                        <span className="text-[10px] font-bold text-emerald-600 uppercase">Logo Caricato</span>
                      </div>
                    ) : (
                      <>
                        <ImageIcon className="w-8 h-8 text-slate-300" />
                        <span className="text-sm font-bold text-slate-400 uppercase tracking-tight">Carica Logo dello Studio</span>
                      </>
                    )}
                    <input type="file" accept="image/*" className="hidden" onChange={handleLogoChange} />
                  </label>
                  {data.logoUrl && (
                    <button onClick={() => setData({...data, logoUrl: undefined})} className="p-4 text-red-500 hover:bg-red-50 rounded-2xl transition-all shadow-sm border border-red-100">
                      <Trash2 className="w-6 h-6" />
                    </button>
                  )}
                </div>
              </div>

              <div className="space-y-2">
                <label className="text-xs font-black uppercase tracking-widest text-slate-500 ml-1">Premessa Generale / Note Tecniche</label>
                <div className="relative group">
                  <StickyNote className="absolute left-4 top-4 w-5 h-5 text-slate-400 transition-colors group-focus-within:text-[#64a1a4]" />
                  <textarea 
                    placeholder="Inserisci la premessa tecnica del sopralluogo..."
                    className="w-full pl-12 pr-4 py-4 bg-slate-50 border border-slate-200 rounded-2xl focus:ring-2 outline-none min-h-[140px] resize-none transition-all overflow-hidden font-medium text-slate-700 leading-relaxed"
                    style={{ '--tw-ring-color': PRIMARY_COLOR } as any}
                    value={data.technicalNotes}
                    onChange={(e) => {
                      setData({...data, technicalNotes: e.target.value});
                      adjustTextareaHeight(e.target);
                    }}
                  />
                </div>
              </div>
            </div>

            <div className="mt-12 flex flex-col gap-4">
              <button 
                disabled={!isSetupValid}
                onClick={() => setStep(AppStep.PHOTOS)}
                className="w-full text-white font-black py-5 rounded-2xl shadow-xl flex items-center justify-center gap-3 transition-all active:scale-95 disabled:bg-slate-200 disabled:text-slate-400 disabled:shadow-none uppercase tracking-[0.2em] text-sm"
                style={{ backgroundColor: isSetupValid ? PRIMARY_COLOR : undefined }}
              >
                Inizia Rilevazione Fotografica <ChevronRight className="w-6 h-6" />
              </button>
              {!isSetupValid && (
                <p className="text-center text-[10px] font-black uppercase tracking-widest text-slate-400 animate-pulse">
                  Inserire nome condominio e data per procedere
                </p>
              )}
            </div>
          </div>
        )}

        {step === AppStep.PHOTOS && (
          <div className="space-y-6 animate-in fade-in slide-in-from-bottom-4 duration-500">
            <div className="flex items-center justify-between bg-white p-5 rounded-3xl shadow-sm border border-slate-200 sticky top-20 z-40">
              <button 
                onClick={() => setStep(AppStep.SETUP)}
                className="flex items-center gap-2 text-slate-400 hover:text-slate-800 transition-colors font-black text-xs uppercase tracking-widest"
              >
                <ChevronLeft className="w-5 h-5" /> Indietro
              </button>

              <div className="flex items-center gap-3">
                <label className="flex items-center gap-2 text-white px-5 py-2.5 rounded-2xl cursor-pointer transition-all shadow-lg font-black text-xs uppercase tracking-widest" style={{ backgroundColor: PRIMARY_COLOR }}>
                  <Camera className="w-4 h-4" /> Aggiungi Rilievo
                  <input type="file" multiple accept="image/*" className="hidden" onChange={handleFileChange} />
                </label>

                {isAddingCategory ? (
                  <div className="flex items-center gap-2 animate-in slide-in-from-right-2">
