                      value={data.inspectionDate}
                      onChange={(e) => setData({...data, inspectionDate: e.target.value})}
                    />
                  </div>
                </div>
              </div>

              <div className="space-y-2">
                <label className="text-xs font-black uppercase tracking-widest text-slate-500 ml-1">Carica Logo Studio</label>
                <div className="flex items-center gap-4">
                  <label className="flex-1 border-2 border-dashed border-slate-200 rounded-2xl p-6 flex flex-col items-center justify-center gap-2 cursor-pointer hover:bg-slate-50 transition-all">
                    {data.logoUrl ? (
                      <div className="flex flex-col items-center gap-2">
                        <img src={data.logoUrl} alt="Logo" className="h-16 w-auto object-contain" />
                        <span className="text-[10px] font-bold text-emerald-600 uppercase">Logo Pronto</span>
                      </div>
                    ) : (
                      <>
                        <ImageIcon className="w-8 h-8 text-slate-300" />
                        <span className="text-sm font-bold text-slate-400 uppercase tracking-tight">Trascina o carica logo</span>
                      </>
                    )}
                    <input type="file" accept="image/*" className="hidden" onChange={handleLogoChange} />
                  </label>
                  {data.logoUrl && (
                    <button onClick={() => setData({...data, logoUrl: undefined})} className="p-4 text-red-500 hover:bg-red-50 rounded-2xl transition-all shadow-sm">
                      <Trash2 className="w-6 h-6" />
                    </button>
                  )}
                </div>
              </div>

              <div className="space-y-2">
                <label className="text-xs font-black uppercase tracking-widest text-slate-500 ml-1">Note Tecniche Preliminari</label>
                <div className="relative group">
                  <StickyNote className="absolute left-4 top-4 w-5 h-5 text-slate-400 transition-colors group-focus-within:text-[#64a1a4]" />
                  <textarea 
