                        {photo.coordinates && (
                          <div className="absolute bottom-4 left-4 bg-white/90 backdrop-blur-md text-slate-900 text-[10px] px-3 py-2 rounded-xl flex items-center gap-2 shadow-sm font-black">
                            <MapPin className="w-3 h-3 text-[#64a1a4]" /> GPS: {photo.coordinates.latitude.toFixed(4)}, {photo.coordinates.longitude.toFixed(4)}
