                  <select className="text-xs bg-transparent outline-none font-black text-slate-700 uppercase tracking-widest" value={selectedCategoryFilter} onChange={(e) => setSelectedCategoryFilter(e.target.value)}>
                    {reportCategories.map(cat => ( <option key={cat} value={cat}>{cat}</option> ))}
                  </select>
                </div>
                <button onClick={printReport} disabled={isExporting} className="text-white px-10 py-3.5 rounded-[2rem] disabled:bg-slate-400 shadow-2xl flex items-center gap-4 font-black text-xs uppercase tracking-widest transition-all hover:scale-105 active:scale-95" style={{ backgroundColor: isExporting ? undefined : PRIMARY_COLOR }}>
                  {isExporting ? <Loader2 className="animate-spin w-5 h-5" /> : <Download className="w-5 h-5" />}
                  {isExporting ? 'Generazione...' : 'Salva Verbale PDF'}
                </button>
              </div>
            </div>

            <div id="final-report" className="bg-white shadow-2xl rounded-sm p-14 print:shadow-none print:p-0 print:m-0">
              <div className="border-b-8 pb-10 mb-12 flex items-start justify-between" style={{ borderColor: PRIMARY_COLOR }}>
                <div className="flex items-center gap-8">
                  {data.logoUrl && <img src={data.logoUrl} alt="Logo" className="h-32 w-auto object-contain" />}
                  <div className="space-y-1">
                    <h2 className="text-3xl font-black uppercase italic leading-none" style={{ color: PRIMARY_COLOR }}>STUDIO SERRA</h2>
                    <p className="text-sm font-black text-slate-800 uppercase tracking-tight">{STUDIO_NAME}</p>
                    <p className="text-xs font-bold text-slate-500 italic tracking-tight">{STUDIO_TAGLINE}</p>
                  </div>
                </div>
                <div className="text-right">
                  <h1 className="text-4xl font-black text-slate-900 uppercase tracking-tighter mb-2">VERBALE DI SOPRALLUOGO</h1>
                  <p className="font-black tracking-[0.3em] uppercase text-[9px]" style={{ color: PRIMARY_COLOR }}>Documento Professionale</p>
                </div>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-3 gap-8 mb-14">
                <div className="bg-slate-50/50 p-8 rounded-3xl border border-slate-100">
