import { GoogleGenAI, Type } from "@google/genai";

// Inizializzazione del client con la chiave API dall'ambiente
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const professionalizeDescription = async (issue: string): Promise<string> => {
  if (!issue || issue.trim().length < 3) return issue;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Agisci come un ingegnere civile esperto in manutenzioni condominiali. 
      Trasforma la seguente descrizione informale in un'osservazione tecnica formale, precisa e asciutta per un verbale di sopralluogo. 
      Evita preamboli come "Ecco la descrizione". Vai dritto al punto tecnico.

      Descrizione da ottimizzare: "${issue}"`,
      config: {
        temperature: 0.4, // Più basso per maggiore precisione tecnica
        maxOutputTokens: 300,
      },
    });

    const result = response.text?.trim();
    return result || issue;
  } catch (error) {
    console.error("Errore durante l'ottimizzazione IA:", error);
    // In caso di errore, restituiamo il testo originale per non bloccare l'utente
    return issue;
  }
};

export const generateExecutiveSummary = async (condoName: string, issues: string[]): Promise<string> => {
  if (issues.length === 0) return "Sopralluogo tecnico effettuato per verificare lo stato manutentivo generale dell'immobile.";

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Scrivi una sintesi esecutiva (massimo 50 parole) per un verbale di sopralluogo presso il condominio "${condoName}". 
      I punti principali rilevati sono: ${issues.join("; ")}. 
      Usa un tono autorevole, professionale e sintetico.`,
      config: {
        temperature: 0.5,
      }
    });
    return response.text?.trim() || "Sopralluogo effettuato con rilievo di diverse criticità tecniche.";
  } catch (error) {
    console.error("Errore sintesi IA:", error);
    return "Relazione tecnica sullo stato conservativo delle parti comuni dell'edificio.";
  }
};

