import { 
  Building2, 
  Calendar, 
  Camera, 
  Trash2, 
  ChevronRight, 
  ChevronLeft, 
  FileText, 
  Download,
  Wand2,
  CheckCircle2,
  MapPin,
  Tag,
  Plus,
  Image as ImageIcon,
  StickyNote,
  Filter,
  X,
  Check,
  Edit3,
  Loader2,
  Sparkles,
  ArrowDownLeft,
  Briefcase,
  Search,
  Printer
} from 'lucide-react';
import { AppStep, InspectionData, InspectionPhoto, Coordinates } from './types';
