import { GoogleGenAI, Type } from "@google/genai";

// Inizializzazione del client con la chiave API dall'ambiente
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const professionalizeDescription = async (issue: string): Promise<string> => {
  if (!issue || issue.trim().length < 3) return issue;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Agisci come un ingegnere civile esperto in perizie e manutenzioni condominiali. 
      Trasforma la seguente descrizione in un'osservazione tecnica formale, esaustiva e approfondita per un verbale di sopralluogo ufficiale.

      REGOLE:
      1. Usa una terminologia tecnica precisa (es. "fenomeni di capillarità", "ammaloramento corticale", "quadro fessurativo").
      2. Fornisci una descrizione COMPLETA e dettagliata, non limitarti a poche parole.
      3. Non includere introduzioni come "Ecco la versione ottimizzata".
      4. Se la descrizione originale è breve, espandila basandoti sulle buone pratiche dell'ingegneria civile.

      Descrizione originale: "${issue}"`,
      config: {
        temperature: 0.3,
        maxOutputTokens: 1000, // Aumentato drasticamente per evitare testi incompleti
      },
    });

    const result = response.text?.trim();
    return result || issue;
  } catch (error) {
    console.error("Errore durante l'ottimizzazione IA:", error);
    return issue;
  }
};

export const generateExecutiveSummary = async (condoName: string, issues: string[]): Promise<string> => {
  if (issues.length === 0) return "Sopralluogo tecnico effettuato per verificare lo stato manutentivo generale dell'immobile.";

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Scrivi una sintesi esecutiva dettagliata e professionale per un verbale di sopralluogo presso il condominio "${condoName}". 
      I problemi rilevati sono: ${issues.join("; ")}. 
      Sintetizza lo stato generale dell'immobile, la gravità dei rilievi e le azioni consigliate. 
      Sii esaustivo ma formale.`,
      config: {
        temperature: 0.4,
        maxOutputTokens: 800,
      }
    });
    return response.text?.trim() || "Sopralluogo effettuato con rilievo di diverse criticità tecniche.";
  } catch (error) {
    console.error("Errore sintesi IA:", error);
    return "Relazione tecnica sullo stato conservativo delle parti comuni dell' ed edificio.";
  }
};

import React, { useState, useMemo, useEffect } from 'react';
import { 
  Building2, 
  Calendar, 
  Camera, 
  Trash2, 
  ChevronRight, 
  ChevronLeft, 
  FileText, 
  Download,
  Wand2,
  CheckCircle2,
  MapPin,
  Tag,
  Plus,
  Image as ImageIcon,
  StickyNote,
  Filter,
  X,
  Check,
  Edit3,
  Loader2,
  Sparkles,
  ArrowDownLeft,
  Briefcase,
  Search,
  Printer
} from 'lucide-react';
import { AppStep, InspectionData, InspectionPhoto, Coordinates } from './types';
import { professionalizeDescription, generateExecutiveSummary } from './services/geminiService';

const DEFAULT_CATEGORIES = ['Strutturale', 'Impianto Idraulico', 'Impianto Elettrico', 'Estetica/Facciata', 'Aree Comuni', 'Sicurezza'];
const STUDIO_NAME = "Studio Amministrazioni Condominiali Ing. Serra";
const STUDIO_TAGLINE = "il condominio trasparente: tutto limpido, tutto evidente";
const PRIMARY_COLOR = "#64a1a4";

const App: React.FC = () => {
  const [step, setStep] = useState<AppStep>(AppStep.SETUP);
  const [isExporting, setIsExporting] = useState(false);
  const [data, setData] = useState<InspectionData>({
    condoName: '',
    inspectionDate: new Date().toISOString().split('T')[0],
    logoUrl: undefined,
    technicalNotes: 'Sopralluogo effettuato per verifica stato conservativo generale dell\'immobile e delle pertinenze comuni.',
    photos: [],
    availableCategories: DEFAULT_CATEGORIES
  });

  const [isAddingCategory, setIsAddingCategory] = useState(false);
  const [newCatName, setNewCatName] = useState('');
  const [summary, setSummary] = useState('');
  const [isGeneratingSummary, setIsGeneratingSummary] = useState(false);
  const [selectedCategoryFilter, setSelectedCategoryFilter] = useState<string>('Tutte');

  const isSetupValid = useMemo(() => {
    return data.condoName.trim().length > 0 && data.inspectionDate.length > 0;
  }, [data.condoName, data.inspectionDate]);

  const filteredPhotos = useMemo(() => {
    if (selectedCategoryFilter === 'Tutte') return data.photos;
    return data.photos.filter(p => p.category === selectedCategoryFilter);
  }, [data.photos, selectedCategoryFilter]);

  const reportCategories = useMemo(() => {
    const cats = new Set(data.photos.map(p => p.category));
    return ['Tutte', ...Array.from(cats)];
  }, [data.photos]);

  const adjustTextareaHeight = (target: HTMLTextAreaElement) => {
    if (!target) return;
    target.style.height = 'auto';
    target.style.height = `${target.scrollHeight}px`;
  };

  useEffect(() => {
    if (isExporting) return;
    const timer = setTimeout(() => {
      document.querySelectorAll('textarea').forEach(ta => adjustTextareaHeight(ta as HTMLTextAreaElement));
    }, 150);
    return () => clearTimeout(timer);
  }, [step, summary, data.photos, filteredPhotos, isExporting]);

  useEffect(() => {
    const handleAfterPrint = () => {
      setIsExporting(false);
    };
    window.addEventListener('afterprint', handleAfterPrint);
    return () => window.removeEventListener('afterprint', handleAfterPrint);
  }, []);

  const getCoordinates = (): Promise<Coordinates | undefined> => {
    return new Promise((resolve) => {
      if (!navigator.geolocation) {
        resolve(undefined);
        return;
      }
      navigator.geolocation.getCurrentPosition(
        (position) => {
          resolve({
            latitude: position.coords.latitude,
            longitude: position.coords.longitude
          });
        },
        () => resolve(undefined),
        { timeout: 4000 }
      );
    });
  };

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files) {
      const coords = await getCoordinates();
      const newFiles = Array.from(e.target.files) as File[];
      const newPhotos: InspectionPhoto[] = newFiles.map(file => ({
        id: Math.random().toString(36).substr(2, 9),
        url: URL.createObjectURL(file),
        issue: '',
        supplier: '',
        category: data.availableCategories[0] || DEFAULT_CATEGORIES[0],
        coordinates: coords
      }));
      setData(prev => ({ ...prev, photos: [...prev.photos, ...newPhotos] }));
    }
  };

  const handleLogoChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files?.[0]) {
      const url = URL.createObjectURL(e.target.files[0]);
      setData(prev => ({ ...prev, logoUrl: url }));
    }
  };

  const updatePhoto = (id: string, updates: Partial<InspectionPhoto>) => {
    setData(prev => ({
      ...prev,
      photos: prev.photos.map(p => p.id === id ? { ...p, ...updates } : p)
    }));
  };

  const removePhoto = (id: string) => {
    setData(prev => ({
      ...prev,
      photos: prev.photos.filter(p => p.id !== id)
    }));
  };

  const handleAddCategory = () => {
    const trimmed = newCatName.trim();
    if (trimmed && !data.availableCategories.includes(trimmed)) {
      setData(prev => ({
        ...prev,
        availableCategories: [...prev.availableCategories, trimmed]
      }));
      setNewCatName('');
      setIsAddingCategory(false);
    }
  };

  const handleAIEnhance = async (id: string, currentIssue: string) => {
    if (!currentIssue || currentIssue.trim().length < 3) return;
    updatePhoto(id, { isLoading: true, aiPolishedIssue: undefined });
    const polished = await professionalizeDescription(currentIssue);
    updatePhoto(id, { aiPolishedIssue: polished, isLoading: false });
  };

  const handleGenerateReport = async () => {
    setStep(AppStep.REPORT);
    setIsGeneratingSummary(true);
    const issues = data.photos.map(p => p.aiPolishedIssue || p.issue).filter(Boolean);
    const execSummary = await generateExecutiveSummary(data.condoName, issues);
    setSummary(execSummary);
    setIsGeneratingSummary(false);
  };

  // Funzione di stampa migliorata per evitare blocchi del browser
  const printReport = () => {
    if (isExporting) return;

    // Mostriamo uno stato di caricamento immediato
    setIsExporting(true);

    // Piccolissimo timeout per permettere alla UI di aggiornarsi prima del blocco window.print
    setTimeout(() => {
      try {
        window.print();
      } catch (e) {
        console.error("Errore stampa:", e);
        alert("Si è verificato un errore durante l'apertura del modulo di stampa. Riprova.");
        setIsExporting(false);
      }
    }, 100);
  };

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col">
      <header className="bg-white border-b border-slate-200 sticky top-0 z-50 px-4 py-4 print:hidden">
        <div className="max-w-4xl mx-auto flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="p-2.5 rounded-xl shadow-sm" style={{ backgroundColor: PRIMARY_COLOR }}>
              <Briefcase className="text-white w-5 h-5" />
            </div>
            <div>
              <h1 className="text-base font-black text-slate-800 leading-none">Studio Ing. Serra</h1>
              <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest mt-1">Management Pro</p>
            </div>
          </div>
          <div className="flex items-center gap-4">
            <div className="hidden sm:flex items-center gap-1 text-[10px] font-black uppercase tracking-widest text-slate-400">
               <span style={{ color: step === AppStep.SETUP ? PRIMARY_COLOR : undefined }} className="font-bold">01 Setup</span>
               <ChevronRight className="w-3 h-3 mx-1" />
               <span style={{ color: step === AppStep.PHOTOS ? PRIMARY_COLOR : undefined }} className="font-bold">02 Rilievi</span>
               <ChevronRight className="w-3 h-3 mx-1" />
               <span style={{ color: step === AppStep.REPORT ? PRIMARY_COLOR : undefined }} className="font-bold">03 Verbale</span>
            </div>
          </div>
        </div>
      </header>

      <main className="flex-1 max-w-4xl mx-auto w-full p-4 sm:p-6 pb-20 print:p-0 print:m-0">
        {step === AppStep.SETUP && (
          <div className="bg-white rounded-3xl shadow-sm border border-slate-200 p-8 sm:p-10 animate-in fade-in duration-500">
            <div className="flex flex-col sm:flex-row items-center justify-between mb-10 pb-6 border-b border-slate-100 gap-6">
              <div className="text-center sm:text-left">
                <h2 className="text-3xl font-black text-slate-900 tracking-tight italic" style={{ color: PRIMARY_COLOR }}>STUDIO SERRA</h2>
                <p className="text-sm font-bold text-slate-500 mt-1 uppercase tracking-wider">{STUDIO_NAME}</p>
                <p className="text-xs text-slate-400 mt-1 italic">{STUDIO_TAGLINE}</p>
              </div>
              <div className="flex shrink-0">
                 {data.logoUrl && (
                   <div className="w-20 h-20 rounded-2xl border-2 border-slate-100 p-1 flex items-center justify-center bg-slate-50 shadow-inner">
                     <img src={data.logoUrl} className="w-full h-full rounded-xl object-contain" alt="Logo Studio" />
                   </div>
                 )}
              </div>
            </div>

            <div className="space-y-8">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                <div className="space-y-2">
                  <label className="text-xs font-black uppercase tracking-widest text-slate-500 ml-1">Nome del Condominio <span className="text-red-500">*</span></label>
                  <input type="text" placeholder="es. Condominio San Giacomo" className="w-full px-5 py-4 bg-slate-50 border border-slate-200 rounded-2xl focus:ring-2 outline-none transition-all font-medium text-slate-800" style={{ '--tw-ring-color': PRIMARY_COLOR } as any} value={data.condoName} onChange={(e) => setData({...data, condoName: e.target.value})} />
                </div>
                <div className="space-y-2">
                  <label className="text-xs font-black uppercase tracking-widest text-slate-500 ml-1">Data del Sopralluogo <span className="text-red-500">*</span></label>
                  <input type="date" className="w-full px-5 py-4 bg-slate-50 border border-slate-200 rounded-2xl focus:ring-2 outline-none transition-all font-medium text-slate-800" style={{ '--tw-ring-color': PRIMARY_COLOR } as any} value={data.inspectionDate} onChange={(e) => setData({...data, inspectionDate: e.target.value})} />
                </div>
              </div>

              <div className="space-y-2">
                <label className="text-xs font-black uppercase tracking-widest text-slate-500 ml-1">Logo Ufficiale Studio</label>
                <div className="flex items-center gap-4">
                  <label className="flex-1 border-2 border-dashed border-slate-200 rounded-2xl p-6 flex flex-col items-center justify-center gap-2 cursor-pointer hover:bg-slate-50 transition-all">
                    {data.logoUrl ? (
                      <div className="flex flex-col items-center gap-2">
                        <img src={data.logoUrl} alt="Logo" className="h-16 w-auto object-contain" />
                        <span className="text-[10px] font-bold text-emerald-600 uppercase tracking-widest">Logo Pronto</span>
                      </div>
                    ) : (
                      <>
                        <ImageIcon className="w-8 h-8 text-slate-300" />
                        <span className="text-sm font-bold text-slate-400 uppercase tracking-tight">Carica Logo</span>
                      </>
                    )}
                    <input type="file" accept="image/*" className="hidden" onChange={handleLogoChange} />
                  </label>
                  {data.logoUrl && (
                    <button onClick={() => setData({...data, logoUrl: undefined})} className="p-4 text-red-500 hover:bg-red-50 rounded-2xl transition-all shadow-sm">
                      <Trash2 className="w-6 h-6" />
                    </button>
                  )}
                </div>
              </div>

              <div className="space-y-2">
                <label className="text-xs font-black uppercase tracking-widest text-slate-500 ml-1">Note Tecniche Preliminari</label>
                <textarea placeholder="Note generali..." className="w-full px-5 py-4 bg-slate-50 border border-slate-200 rounded-2xl focus:ring-2 outline-none min-h-[120px] resize-none transition-all font-medium text-slate-700 leading-relaxed" style={{ '--tw-ring-color': PRIMARY_COLOR } as any} value={data.technicalNotes} onChange={(e) => { setData({...data, technicalNotes: e.target.value}); adjustTextareaHeight(e.target); }} />
              </div>
            </div>

            <div className="mt-12">
              <button disabled={!isSetupValid} onClick={() => setStep(AppStep.PHOTOS)} className="w-full text-white font-black py-5 rounded-2xl shadow-xl flex items-center justify-center gap-3 transition-all active:scale-95 disabled:bg-slate-200 disabled:text-slate-400 uppercase tracking-widest text-sm" style={{ backgroundColor: isSetupValid ? PRIMARY_COLOR : undefined }}>
                Vai ai Rilievi <ChevronRight className="w-6 h-6" />
              </button>
            </div>
          </div>
        )}

        {step === AppStep.PHOTOS && (
          <div className="space-y-6 animate-in fade-in duration-500">
            <div className="flex items-center justify-between bg-white p-5 rounded-3xl shadow-sm border border-slate-200 sticky top-20 z-40">
              <button onClick={() => setStep(AppStep.SETUP)} className="flex items-center gap-2 text-slate-400 hover:text-slate-800 font-bold text-xs uppercase tracking-widest transition-colors">
                <ChevronLeft className="w-5 h-5" /> Indietro
              </button>
              <div className="flex items-center gap-3">
                <label className="flex items-center gap-2 text-white px-5 py-2.5 rounded-2xl cursor-pointer shadow-lg font-black text-xs uppercase tracking-widest transition-opacity hover:opacity-90" style={{ backgroundColor: PRIMARY_COLOR }}>
                  <Camera className="w-4 h-4" /> Aggiungi Foto
                  <input type="file" multiple accept="image/*" className="hidden" onChange={handleFileChange} />
                </label>
              </div>
            </div>

            <div className="grid grid-cols-1 gap-8">
              {data.photos.length === 0 ? (
                <div className="bg-white border-2 border-dashed border-slate-200 rounded-[3rem] p-24 flex flex-col items-center justify-center text-center gap-6">
                  <ImageIcon className="w-12 h-12 text-slate-200" />
                  <p className="text-xl font-black text-slate-800 uppercase">Nessuna foto caricata</p>
                  <label className="text-white px-10 py-4 rounded-[2rem] font-black text-xs uppercase tracking-widest cursor-pointer shadow-xl" style={{ backgroundColor: PRIMARY_COLOR }}>
                    Scegli Immagini
                    <input type="file" multiple accept="image/*" className="hidden" onChange={handleFileChange} />
                  </label>
                </div>
              ) : (
                data.photos.map((photo) => (
                  <div key={photo.id} className="bg-white rounded-3xl shadow-sm border border-slate-200 overflow-hidden flex flex-col group hover:border-[#64a1a4]/30 transition-all">
                    <div className="flex flex-col md:flex-row h-full">
                      <div className="md:w-1/3 relative bg-slate-100 min-h-[260px]">
                        <img src={photo.url} alt="Rilievo" className="w-full h-full object-cover" />
                        <button onClick={() => removePhoto(photo.id)} className="absolute top-4 right-4 p-2.5 bg-red-500 text-white rounded-2xl opacity-0 group-hover:opacity-100 transition-opacity shadow-lg"><Trash2 className="w-4 h-4" /></button>
                        {photo.coordinates && (
                          <div className="absolute bottom-4 left-4 bg-white/90 text-slate-900 text-[10px] px-3 py-2 rounded-xl flex items-center gap-2 shadow-sm font-black uppercase">
                            <MapPin className="w-3 h-3 text-[#64a1a4]" /> GPS Attivo
                          </div>
                        )}
                      </div>
                      <div className="flex-1 p-8 space-y-6">
                        <div className="grid grid-cols-1 sm:grid-cols-2 gap-6">
                          <div className="space-y-2">
                            <label className="text-[10px] font-black uppercase tracking-widest text-slate-400">Categoria</label>
                            <select className="w-full p-3.5 bg-slate-50 border border-slate-200 rounded-2xl text-sm font-bold text-slate-700 outline-none" style={{ '--tw-ring-color': PRIMARY_COLOR } as any} value={photo.category} onChange={(e) => updatePhoto(photo.id, { category: e.target.value })}>
                              {data.availableCategories.map(cat => ( <option key={cat} value={cat}>{cat}</option> ))}
                            </select>
                          </div>
                          <div className="space-y-2">
                            <label className="text-[10px] font-black uppercase tracking-widest text-slate-400">Rif. Fornitore</label>
                            <input type="text" placeholder="Ditta Rossi..." className="w-full px-4 py-3.5 bg-slate-50 border border-slate-200 rounded-2xl text-sm font-bold text-slate-700 outline-none" style={{ '--tw-ring-color': PRIMARY_COLOR } as any} value={photo.supplier} onChange={(e) => updatePhoto(photo.id, { supplier: e.target.value })} />
                          </div>
                        </div>
                        <div className="space-y-2">
                          <label className="text-[10px] font-black uppercase tracking-widest text-slate-400">Descrizione Problema</label>
                          <div className="relative">
                            <textarea placeholder="Descrivi l'anomalia..." className="w-full p-5 bg-slate-50 border border-slate-200 rounded-[2rem] focus:ring-1 outline-none min-h-[120px] resize-none text-sm font-medium text-slate-700 shadow-inner" style={{ '--tw-ring-color': PRIMARY_COLOR } as any} value={photo.issue} onChange={(e) => { updatePhoto(photo.id, { issue: e.target.value }); adjustTextareaHeight(e.target); }} />
                            <button onClick={() => handleAIEnhance(photo.id, photo.issue)} disabled={!photo.issue || photo.issue.length < 3 || photo.isLoading} className="absolute bottom-4 right-4 p-2.5 bg-white border border-slate-200 rounded-2xl hover:bg-slate-50 shadow-md flex items-center gap-2 disabled:opacity-50" style={{ color: PRIMARY_COLOR }}>
                              {photo.isLoading ? <Loader2 className="animate-spin h-4 w-4" /> : <Wand2 className="w-4 h-4" />}
                              <span className="text-[10px] font-black uppercase tracking-tighter">Ottimizza IA</span>
                            </button>
                          </div>
                        </div>
                      </div>
                    </div>
                    {/* Blocco Revisione IA */}
                    {(photo.isLoading || photo.aiPolishedIssue) && (
                      <div className="p-8 border-t border-slate-100 animate-in slide-in-from-top-2" style={{ backgroundColor: `${PRIMARY_COLOR}08` }}>
                        <div className="flex flex-col gap-4">
                          <div className="flex items-center justify-between">
                            <div className="flex items-center gap-3" style={{ color: PRIMARY_COLOR }}>
                              <Sparkles className="w-4 h-4" />
                              <span className="text-[10px] font-black uppercase tracking-widest">Revisione Tecnica Suggerita</span>
                            </div>
                            {photo.aiPolishedIssue && !photo.isLoading && (
                              <button onClick={() => updatePhoto(photo.id, { aiPolishedIssue: undefined })} className="text-slate-400 p-1 hover:text-slate-600 transition-colors">
                                <X className="w-4 h-4" />
                              </button>
                            )}
                          </div>

                          {photo.isLoading ? (
                            <div className="flex items-center gap-4 py-4">
                              <Loader2 className="animate-spin h-5 w-5" style={{ color: PRIMARY_COLOR }} />
                              <p className="text-xs font-bold text-slate-500 italic">Analisi tecnica approfondita in corso...</p>
                            </div>
                          ) : (
                            <div className="flex flex-col md:flex-row gap-6 items-start">
                              <div className="flex-1 w-full">
                                <div className="text-sm text-slate-800 leading-relaxed font-bold italic bg-white/80 p-6 rounded-3xl border border-white shadow-sm">
                                  {photo.aiPolishedIssue}
                                </div>
                              </div>
                              <button 
                                onClick={() => updatePhoto(photo.id, { issue: photo.aiPolishedIssue, aiPolishedIssue: undefined })}
                                className="w-full md:w-auto flex items-center justify-center gap-3 text-white px-8 py-4 rounded-2xl shadow-xl font-black text-[10px] uppercase tracking-widest transition-transform active:scale-95 shrink-0"
                                style={{ backgroundColor: PRIMARY_COLOR }}
                              >
                                <ArrowDownLeft className="w-4 h-4" /> Conferma e Applica
                              </button>
                            </div>
                          )}
                        </div>
                      </div>
                    )}
                  </div>
                ))
              )}
            </div>

            <div className="pt-12 border-t border-slate-200 mt-12">
              <button disabled={!isSetupValid || data.photos.length === 0} onClick={handleGenerateReport} className="w-full bg-slate-900 hover:bg-slate-800 disabled:bg-slate-100 text-white font-black py-6 rounded-[2rem] shadow-2xl flex items-center justify-center gap-4 transition-all uppercase tracking-widest text-sm">
                Genera Verbale <FileText className="w-7 h-7" />
              </button>
            </div>
          </div>
        )}

        {step === AppStep.REPORT && (
          <div className="space-y-8 animate-in fade-in duration-500 print:p-0 print:m-0">
            <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 print:hidden">
              <button onClick={() => setStep(AppStep.PHOTOS)} className="flex items-center gap-2 text-slate-500 font-bold text-xs uppercase tracking-widest"><ChevronLeft className="w-5 h-5" /> Rilievi</button>
              <div className="flex items-center gap-3">
                <button 
                  onClick={printReport} 
                  disabled={isExporting} 
                  className="text-white px-10 py-4 rounded-[2rem] disabled:bg-slate-400 shadow-2xl flex items-center gap-4 font-black text-xs uppercase tracking-[0.2em] transition-all hover:scale-105 active:scale-95" 
                  style={{ backgroundColor: isExporting ? undefined : PRIMARY_COLOR }}
                >
                  {isExporting ? <Loader2 className="animate-spin w-5 h-5" /> : <Printer className="w-5 h-5" />}
                  {isExporting ? 'Preparazione PDF...' : 'Esporta PDF'}
                </button>
              </div>
            </div>

            <div id="final-report" className="bg-white shadow-2xl rounded-sm p-14 print:shadow-none print:p-0 print:m-0">
              {/* Header Verbale */}
              <div className="border-b-8 pb-10 mb-12 flex items-start justify-between" style={{ borderColor: PRIMARY_COLOR }}>
                <div className="flex items-center gap-8">
                  {data.logoUrl && <img src={data.logoUrl} alt="Logo" className="h-32 w-auto object-contain" />}
                  <div className="space-y-1">
                    <h2 className="text-3xl font-black uppercase italic leading-none" style={{ color: PRIMARY_COLOR }}>STUDIO SERRA</h2>
                    <p className="text-sm font-black text-slate-800 uppercase">{STUDIO_NAME}</p>
                    <p className="text-xs font-bold text-slate-500 italic">{STUDIO_TAGLINE}</p>
                  </div>
                </div>
                <div className="text-right">
                  <h1 className="text-4xl font-black text-slate-900 uppercase tracking-tighter mb-2">VERBALE DI SOPRALLUOGO</h1>
                  <p className="font-black tracking-[0.3em] uppercase text-[9px]" style={{ color: PRIMARY_COLOR }}>Documento Tecnico Ufficiale</p>
                </div>
              </div>

              {/* Dati Condominio */}
              <div className="grid grid-cols-1 md:grid-cols-3 gap-8 mb-14">
                <div className="bg-slate-50/50 p-8 rounded-3xl border border-slate-100">
                  <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-3">Condominio</h3>
                  <p className="text-2xl font-black text-slate-900 tracking-tight">{data.condoName}</p>
                </div>
                <div className="bg-slate-50/50 p-8 rounded-3xl border border-slate-100">
                  <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-3">Data</h3>
                  <p className="text-2xl font-black text-slate-900 tracking-tight">{new Date(data.inspectionDate).toLocaleDateString('it-IT', { day: 'numeric', month: 'long', year: 'numeric' })}</p>
                </div>
                <div className="bg-slate-50/50 p-8 rounded-3xl border border-slate-100">
                  <h3 className="text-[10px] font-black uppercase tracking-widest mb-3" style={{ color: PRIMARY_COLOR }}>Rilievi Totali</h3>
                  <p className="font-black text-2xl text-slate-900 tracking-tight">{filteredPhotos.length}</p>
                </div>
              </div>

              {/* Sintesi Esecutiva */}
              <div className="mb-20 bg-slate-900 p-10 rounded-[3rem] text-white relative">
                <h3 className="text-xs font-black uppercase tracking-[0.4em] mb-6" style={{ color: PRIMARY_COLOR }}>Sintesi Esecutiva Professionale</h3>
                {isGeneratingSummary ? (
                   <p className="text-xl font-light italic text-slate-300 animate-pulse">Analisi in corso...</p>
                ) : (
                  <>
                    <textarea className="w-full bg-transparent border-none text-white text-xl font-light italic resize-none focus:ring-0 p-0 outline-none print-text-area overflow-hidden" value={summary} onChange={(e) => { setSummary(e.target.value); adjustTextareaHeight(e.target); }} />
                    <div className="print-text-mirror text-white text-xl font-light italic">{summary}</div>
                  </>
                )}
              </div>

              {/* Lista Rilievi */}
              <div className="space-y-32">
                {filteredPhotos.map((indexPhoto, idx) => (
                  <div key={indexPhoto.id} className="break-inside-avoid">
                    <div className="flex items-center justify-between mb-10 border-b-4 border-slate-50 pb-8">
                      <div className="flex items-center gap-8">
                        <span className="text-white w-14 h-14 rounded-[1.5rem] flex items-center justify-center font-black text-2xl rotate-3 shadow-sm" style={{ backgroundColor: PRIMARY_COLOR }}>{idx + 1}</span>
                        <div>
                          <p className="text-[11px] font-black text-slate-400 uppercase tracking-widest mb-1">Dettaglio Rilievo n. {idx + 1}</p>
                          <h4 className="text-3xl font-black text-slate-900 uppercase italic" style={{ color: PRIMARY_COLOR }}>{indexPhoto.category}</h4>
                        </div>
                      </div>
                      <div className="text-right">
                        <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Fornitore di Riferimento</span>
                        <p className="text-xl font-black text-slate-800 uppercase">{indexPhoto.supplier || "Da Definire"}</p>
                      </div>
                    </div>
                    <div className="grid grid-cols-1 md:grid-cols-12 gap-16">
                      <div className="md:col-span-5">
                        <div className="aspect-[4/3] rounded-[3rem] overflow-hidden border-4 border-slate-50 shadow-sm mb-6">
                          <img src={indexPhoto.url} alt={`Dettaglio ${idx + 1}`} className="w-full h-full object-cover" />
                        </div>
                      </div>
                      <div className="md:col-span-7">
                        <h5 className="text-[11px] font-black text-slate-400 uppercase tracking-[0.3em] flex items-center gap-3 mb-6">
                          <span className="w-2.5 h-2.5 rounded-full" style={{ backgroundColor: PRIMARY_COLOR }}></span> Analisi dello Studio
                        </h5>
                        <textarea className="w-full text-slate-800 text-xl font-bold italic bg-slate-50/50 p-10 rounded-[3rem] border-2 border-slate-50 resize-none outline-none print-text-area overflow-hidden" value={indexPhoto.aiPolishedIssue || indexPhoto.issue} onChange={(e) => { updatePhoto(indexPhoto.id, { aiPolishedIssue: e.target.value, issue: e.target.value }); adjustTextareaHeight(e.target); }} />
                        <div className="print-text-mirror text-slate-800 text-xl font-bold italic bg-slate-50/50 p-10 rounded-[3rem] border-2 border-slate-50">
                          {indexPhoto.aiPolishedIssue || indexPhoto.issue}
                        </div>
                      </div>
                    </div>
                  </div>
                ))}
              </div>

              {/* Firme e Chiusura */}
              <div className="mt-48 pt-20 border-t-4 border-slate-900 flex justify-between items-end break-inside-avoid">
                <div className="max-w-md">
                  <p className="text-[11px] font-black text-slate-400 uppercase tracking-widest mb-6">Documento emesso da:</p>
                  <p className="text-base font-black text-slate-900 uppercase">{STUDIO_NAME}</p>
                </div>
                <div className="text-center w-96">
                  <div className="h-0.5 bg-slate-200 w-full mb-8"></div>
                  <p className="text-xs font-black text-slate-400 uppercase tracking-widest mb-2">Firma Ing. Serra</p>
                </div>
              </div>
            </div>
          </div>
        )}
      </main>
    </div>
  );
};

export default App;

export interface Coordinates {
  latitude: number;
  longitude: number;
}

export interface InspectionPhoto {
  id: string;
  url: string; // Blob URL per anteprima locale
  base64Data?: string; // Dati per l'invio all'IA
  mimeType?: string;
  issue: string;
  supplier: string;
  category: string;
  coordinates?: Coordinates;
  aiPolishedIssue?: string;
  isLoading?: boolean;
}

export interface InspectionData {
  condoName: string;
  inspectionDate: string;
  logoUrl?: string;
  technicalNotes: string;
  photos: InspectionPhoto[];
  availableCategories: string[];
}

export enum AppStep {
  SETUP = 'setup',
  PHOTOS = 'photos',
  REPORT = 'report'
}

import { GoogleGenAI } from "@google/genai";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const professionalizeDescription = async (
  issue: string, 
  base64Data?: string, 
  mimeType?: string
): Promise<string> => {
  try {
    const parts: any[] = [
      {
        text: `Agisci come un ingegnere civile esperto in perizie condominiali. 
        Analizza l'immagine fornita e incrociala con la nota dell'utente: "${issue || 'Nessuna nota fornita'}".

        REGOLE:
        1. Identifica con precisione tecnica ciò che appare nella foto (es. fessurazioni, efflorescenze, distacchi, ossidazione).
        2. Scrivi una descrizione formale per un verbale di sopralluogo ufficiale.
        3. Sii specifico sui materiali e sulla natura del degrado visibile.
        4. Non usare introduzioni. Vai diretto al punto tecnico.
        5. Se l'utente ha scritto una nota, usala come contesto ma dai priorità all'evidenza visiva della foto.`
      }
    ];

    if (base64Data && mimeType) {
      parts.push({
        inlineData: {
          data: base64Data,
          mimeType: mimeType
        }
      });
    }

    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-preview-09-2025', // Utilizziamo un modello con ottime capacità vision
      contents: [{ parts }],
      config: {
        temperature: 0.2,
        maxOutputTokens: 1000,
      },
    });

    return response.text?.trim() || issue;
  } catch (error) {
    console.error("Errore analisi multimodale:", error);
    return issue;
  }
};

export const generateExecutiveSummary = async (condoName: string, issues: string[]): Promise<string> => {
  if (issues.length === 0) return "Sopralluogo tecnico effettuato per verificare lo stato manutentivo generale dell'immobile.";

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Scrivi una sintesi esecutiva professionale (circa 80-100 parole) per un verbale di sopralluogo presso il condominio "${condoName}". 
      Criticità riscontrate: ${issues.join("; ")}. 
      Valuta la priorità degli interventi e lo stato generale di decoro e sicurezza.`,
      config: {
        temperature: 0.5,
        maxOutputTokens: 800,
      }
    });
    return response.text?.trim() || "Sopralluogo effettuato con rilievo di diverse criticità tecniche.";
  } catch (error) {
    console.error("Errore sintesi IA:", error);
    return "Relazione tecnica sullo stato conservativo delle parti comuni dell'edificio.";
  }
};

import React, { useState, useMemo, useEffect } from 'react';
import { 
  Building2, 
  Calendar, 
  Camera, 
  Trash2, 
  ChevronRight, 
  ChevronLeft, 
  FileText, 
  Download,
  Wand2,
  CheckCircle2,
  MapPin,
  Tag,
  Plus,
  Image as ImageIcon,
  StickyNote,
  Filter,
  X,
  Check,
  Edit3,
  Loader2,
  Sparkles,
  ArrowDownLeft,
  Briefcase,
  Search,
  Printer
} from 'lucide-react';
import { AppStep, InspectionData, InspectionPhoto, Coordinates } from './types';
import { professionalizeDescription, generateExecutiveSummary } from './services/geminiService';

const DEFAULT_CATEGORIES = ['Strutturale', 'Impianto Idraulico', 'Impianto Elettrico', 'Estetica/Facciata', 'Aree Comuni', 'Sicurezza'];
const STUDIO_NAME = "Studio Amministrazioni Condominiali Ing. Serra";
const STUDIO_TAGLINE = "il condominio trasparente: tutto limpido, tutto evidente";
const PRIMARY_COLOR = "#64a1a4";

const App: React.FC = () => {
  const [step, setStep] = useState<AppStep>(AppStep.SETUP);
  const [isExporting, setIsExporting] = useState(false);
  const [data, setData] = useState<InspectionData>({
    condoName: '',
    inspectionDate: new Date().toISOString().split('T')[0],
    logoUrl: undefined,
    technicalNotes: 'Sopralluogo effettuato per verifica stato conservativo generale dell\'immobile e delle pertinenze comuni.',
    photos: [],
    availableCategories: DEFAULT_CATEGORIES
  });

  const [isAddingCategory, setIsAddingCategory] = useState(false);
  const [newCatName, setNewCatName] = useState('');
  const [summary, setSummary] = useState('');
  const [isGeneratingSummary, setIsGeneratingSummary] = useState(false);
  const [selectedCategoryFilter, setSelectedCategoryFilter] = useState<string>('Tutte');

  const isSetupValid = useMemo(() => {
    return data.condoName.trim().length > 0 && data.inspectionDate.length > 0;
  }, [data.condoName, data.inspectionDate]);

  const filteredPhotos = useMemo(() => {
    if (selectedCategoryFilter === 'Tutte') return data.photos;
    return data.photos.filter(p => p.category === selectedCategoryFilter);
  }, [data.photos, selectedCategoryFilter]);

  const adjustTextareaHeight = (target: HTMLTextAreaElement) => {
    if (!target) return;
    target.style.height = 'auto';
    target.style.height = `${target.scrollHeight}px`;
  };

  useEffect(() => {
    if (isExporting) return;
    const timer = setTimeout(() => {
      document.querySelectorAll('textarea').forEach(ta => adjustTextareaHeight(ta as HTMLTextAreaElement));
    }, 150);
    return () => clearTimeout(timer);
  }, [step, summary, data.photos, filteredPhotos, isExporting]);

  useEffect(() => {
    const handleAfterPrint = () => setIsExporting(false);
    window.addEventListener('afterprint', handleAfterPrint);
    return () => window.removeEventListener('afterprint', handleAfterPrint);
  }, []);

  const fileToBase64 = (file: File): Promise<string> => {
    return new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.readAsDataURL(file);
      reader.onload = () => {
        const base64String = (reader.result as string).split(',')[1];
        resolve(base64String);
      };
      reader.onerror = error => reject(error);
    });
  };

  const getCoordinates = (): Promise<Coordinates | undefined> => {
    return new Promise((resolve) => {
      if (!navigator.geolocation) {
        resolve(undefined);
        return;
      }
      navigator.geolocation.getCurrentPosition(
        (position) => {
          resolve({
            latitude: position.coords.latitude,
            longitude: position.coords.longitude
          });
        },
        () => resolve(undefined),
        { timeout: 4000 }
      );
    });
  };

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files) {
      const coords = await getCoordinates();
      const newFiles = Array.from(e.target.files) as File[];

      const newPhotosPromises = newFiles.map(async (file) => {
        const base64 = await fileToBase64(file);
        return {
          id: Math.random().toString(36).substr(2, 9),
          url: URL.createObjectURL(file),
          base64Data: base64,
          mimeType: file.type,
          issue: '',
          supplier: '',
          category: data.availableCategories[0] || DEFAULT_CATEGORIES[0],
          coordinates: coords
        };
      });

      const newPhotos = await Promise.all(newPhotosPromises);
      setData(prev => ({ ...prev, photos: [...prev.photos, ...newPhotos] }));
    }
  };

  const handleLogoChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files?.[0]) {
      const url = URL.createObjectURL(e.target.files[0]);
      setData(prev => ({ ...prev, logoUrl: url }));
    }
  };

  const updatePhoto = (id: string, updates: Partial<InspectionPhoto>) => {
    setData(prev => ({
      ...prev,
      photos: prev.photos.map(p => p.id === id ? { ...p, ...updates } : p)
    }));
  };

  const removePhoto = (id: string) => {
    setData(prev => ({
      ...prev,
      photos: prev.photos.filter(p => p.id !== id)
    }));
  };

  const handleAIEnhance = async (photo: InspectionPhoto) => {
    updatePhoto(photo.id, { isLoading: true, aiPolishedIssue: undefined });
    const polished = await professionalizeDescription(
      photo.issue, 
      photo.base64Data, 
      photo.mimeType
    );
    updatePhoto(photo.id, { aiPolishedIssue: polished, isLoading: false });
  };

  const handleGenerateReport = async () => {
    setStep(AppStep.REPORT);
    setIsGeneratingSummary(true);
    const issues = data.photos.map(p => p.aiPolishedIssue || p.issue).filter(Boolean);
    const execSummary = await generateExecutiveSummary(data.condoName, issues);
    setSummary(execSummary);
    setIsGeneratingSummary(false);
  };

  const printReport = () => {
    if (isExporting) return;
    setIsExporting(true);
    setTimeout(() => {
      try {
        window.print();
      } catch (e) {
        setIsExporting(false);
      }
    }, 100);
  };

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col">
      <header className="bg-white border-b border-slate-200 sticky top-0 z-50 px-4 py-4 print:hidden">
        <div className="max-w-4xl mx-auto flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="p-2.5 rounded-xl shadow-sm" style={{ backgroundColor: PRIMARY_COLOR }}>
              <Briefcase className="text-white w-5 h-5" />
            </div>
            <div>
              <h1 className="text-base font-black text-slate-800 leading-none">Studio Ing. Serra</h1>
              <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest mt-1">Management Pro</p>
            </div>
          </div>
          <div className="flex items-center gap-4">
            <div className="hidden sm:flex items-center gap-1 text-[10px] font-black uppercase tracking-widest text-slate-400">
               <span style={{ color: step === AppStep.SETUP ? PRIMARY_COLOR : undefined }} className="font-bold">01 Setup</span>
               <ChevronRight className="w-3 h-3 mx-1" />
               <span style={{ color: step === AppStep.PHOTOS ? PRIMARY_COLOR : undefined }} className="font-bold">02 Rilievi</span>
               <ChevronRight className="w-3 h-3 mx-1" />
               <span style={{ color: step === AppStep.REPORT ? PRIMARY_COLOR : undefined }} className="font-bold">03 Verbale</span>
            </div>
          </div>
        </div>
      </header>

      <main className="flex-1 max-w-4xl mx-auto w-full p-4 sm:p-6 pb-20 print:p-0 print:m-0">
        {step === AppStep.SETUP && (
          <div className="bg-white rounded-3xl shadow-sm border border-slate-200 p-8 sm:p-10 animate-in fade-in duration-500">
            <div className="flex flex-col sm:flex-row items-center justify-between mb-10 pb-6 border-b border-slate-100 gap-6">
              <div className="text-center sm:text-left">
                <h2 className="text-3xl font-black text-slate-900 tracking-tight italic" style={{ color: PRIMARY_COLOR }}>STUDIO SERRA</h2>
                <p className="text-sm font-bold text-slate-500 mt-1 uppercase tracking-wider">{STUDIO_NAME}</p>
                <p className="text-xs text-slate-400 mt-1 italic">{STUDIO_TAGLINE}</p>
              </div>
              <div className="flex shrink-0">
                 {data.logoUrl && (
                   <div className="w-20 h-20 rounded-2xl border-2 border-slate-100 p-1 flex items-center justify-center bg-slate-50 shadow-inner">
                     <img src={data.logoUrl} className="w-full h-full rounded-xl object-contain" alt="Logo Studio" />
                   </div>
                 )}
              </div>
            </div>

            <div className="space-y-8">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                <div className="space-y-2">
                  <label className="text-xs font-black uppercase tracking-widest text-slate-500 ml-1">Nome del Condominio <span className="text-red-500">*</span></label>
                  <input type="text" placeholder="es. Condominio San Giacomo" className="w-full px-5 py-4 bg-slate-50 border border-slate-200 rounded-2xl focus:ring-2 outline-none transition-all font-medium text-slate-800" style={{ '--tw-ring-color': PRIMARY_COLOR } as any} value={data.condoName} onChange={(e) => setData({...data, condoName: e.target.value})} />
                </div>
                <div className="space-y-2">
                  <label className="text-xs font-black uppercase tracking-widest text-slate-500 ml-1">Data del Sopralluogo <span className="text-red-500">*</span></label>
                  <input type="date" className="w-full px-5 py-4 bg-slate-50 border border-slate-200 rounded-2xl focus:ring-2 outline-none transition-all font-medium text-slate-800" style={{ '--tw-ring-color': PRIMARY_COLOR } as any} value={data.inspectionDate} onChange={(e) => setData({...data, inspectionDate: e.target.value})} />
                </div>
              </div>

              <div className="space-y-2">
                <label className="text-xs font-black uppercase tracking-widest text-slate-500 ml-1">Logo Ufficiale Studio</label>
                <div className="flex items-center gap-4">
                  <label className="flex-1 border-2 border-dashed border-slate-200 rounded-2xl p-6 flex flex-col items-center justify-center gap-2 cursor-pointer hover:bg-slate-50 transition-all">
                    {data.logoUrl ? (
                      <div className="flex flex-col items-center gap-2">
                        <img src={data.logoUrl} alt="Logo" className="h-16 w-auto object-contain" />
