              <div className="flex items-center gap-3">
                <label className="flex items-center gap-2 text-white px-5 py-2.5 rounded-2xl cursor-pointer shadow-lg font-black text-xs uppercase tracking-widest transition-opacity hover:opacity-90" style={{ backgroundColor: PRIMARY_COLOR }}>
