import { GoogleGenAI } from "@google/genai";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const professionalizeDescription = async (
  issue: string, 
  base64Data?: string, 
  mimeType?: string
): Promise<string> => {
  try {
    const parts: any[] = [
      {
        text: `Agisci come un Ingegnere Civile Senior esperto in patologia edilizia e perizie condominiali.

        IL TUO COMPITO:
        1. Analizza l'immagine fornita con estrema attenzione.
        2. IDENTIFICA visivamente i dettagli tecnici (es: se vedi una macchia, specifica se è umidità di risalita o infiltrazione; se vedi una crepa, descrivine l'andamento - verticale, orizzontale, a 45°).
        3. NON limitarti a ripetere ciò che scrive l'utente. Se l'utente scrive "muro rotto", tu devi descrivere il "distacco dell'intonaco con esposizione del supporto murario e segni di ammaloramento".
        4. Usa termini professionali: "quadro fessurativo", "ossidazione dei ferri d'armatura", "carbonatazione", "distacco corticale", "efflorescenze saline".

        REGOLE DI SCRITTURA:
        - Stile: Formale, asciutto, peritale.
        - Lunghezza: Almeno 2-3 frasi dettagliate.
        - Divieto: Non iniziare con "Dall'analisi dell'immagine..." o "Ecco la descrizione...". Vai dritto al punto.

        Nota dell'utente da integrare: "${issue || 'Nessuna specifica fornita dall'utente'}"`
      }
    ];

    if (base64Data && mimeType) {
      parts.push({
        inlineData: {
          data: base64Data,
          mimeType: mimeType
        }
      });
    }

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: [{ parts }],
      config: {
        temperature: 0.4,
        maxOutputTokens: 1000,
      },
    });

    return response.text?.trim() || issue;
  } catch (error) {
    console.error("Errore analisi IA:", error);
    return issue;
  }
};

export const generateExecutiveSummary = async (condoName: string, issues: string[]): Promise<string> => {
  if (issues.length === 0) return "Sopralluogo tecnico effettuato per verificare lo stato manutentivo generale dell'immobile.";

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Redigi una sintesi tecnica esecutiva professionale per un verbale di sopralluogo presso il condominio "${condoName}".

      Punti rilevati: ${issues.join("; ")}.

      La sintesi deve riassumere la gravità complessiva, suggerire l'urgenza degli interventi e mantenere un tono istituzionale e autorevole. Max 100 parole.`,
      config: {
        temperature: 0.4,
      }
    });
    return response.text?.trim() || "Rilievo tecnico dello stato conservativo delle parti comuni.";
  } catch (error) {
    console.error("Errore sintesi IA:", error);
    return "Sopralluogo tecnico effettuato con rilievo di criticità.";
  }
};

