import { GoogleGenAI } from "@google/genai";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const professionalizeDescription = async (
  issue: string, 
  base64Data?: string, 
  mimeType?: string
): Promise<string> => {
  try {
    const parts: any[] = [
      {
        text: `Agisci come un Ingegnere Civile esperto in perizie forensi e diagnostica degli edifici. 

        PROTOCOLLO DI ANALISI:
        1. ANALISI VISIVA: Osserva l'immagine allegata. Identifica i sintomi reali (es: direzione delle crepe, colore delle efflorescenze, tipo di distacco).
        2. DIAGNOSI TECNICA: Non limitarti a riformulare il testo dell'utente. Se l'utente è vago, tu devi essere specifico basandoti su ciò che VEDI nella foto.
        3. TERMINOLOGIA: Usa esclusivamente termini tecnici (es. "sollevamento del film pittorico", "carbonatazione del calcestruzzo", "quadro fessurativo ad andamento diagonale", "infiltrazione da discontinuità della guaina").
        4. OBIETTIVO: Scrivi un paragrafo tecnico di 30-50 parole che descriva l'anomalia come se fosse parte di un capitolato ufficiale.

        VINCOLI:
        - Non usare frasi introduttive come "Dall'immagine si nota".
        - Non ripetere solo le parole dell'utente.
        - Sii autorevole e preciso.

        Nota di contesto dell'utente: "${issue || "Nessuna nota fornita"}"`
      }
    ];

    if (base64Data && mimeType) {
      parts.push({
        inlineData: {
          data: base64Data,
          mimeType: mimeType
        }
      });
    }

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: [{ parts }],
      config: {
        temperature: 0.2, // Più basso per maggiore precisione tecnica
        maxOutputTokens: 1000,
      },
    });

    const result = response.text?.trim();
    return result || issue;
  } catch (error) {
    console.error("Errore analisi multimodale:", error);
    return issue;
  }
};

