import { GoogleGenAI } from "@google/genai";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const professionalizeDescription = async (
  issue: string, 
  base64Data?: string, 
  mimeType?: string
): Promise<string> => {
  try {
    const parts: any[] = [
      {
        text: `Agisci come un Ingegnere esperto in diagnostica strutturale e patologia edilizia. 

        ISTRUZIONI CRITICHE:
        1. ANALISI MULTIMODALE: Analizza i pixel della foto. Identifica anomalie che l'utente non ha descritto (es: efflorescenze saline, fessurazioni da ritiro, ossidazione dei ferri, umidità capillare).
        2. ARRICCHIMENTO: Non ripetere ciò che scrive l'utente. Se l'utente scrive "muro bagnato", tu scriverai un'analisi tecnica sul "degrado della finitura superficiale causato da probabile infiltrazione meteorica o risalita capillare, con conseguente distacco della pellicola pittorica".
        3. TERMINOLOGIA: Usa termini come "quadro fessurativo", "ammaloramento", "carbonatazione", "sollecitazione meccanica", "discontinuità materica".
        4. OUTPUT: Genera una descrizione di almeno 40-60 parole, densa di dettagli tecnici.

        Nota dell'utente: "${issue || "Nessuna nota fornita"}"`
      }
    ];

    if (base64Data && mimeType) {
      parts.push({
        inlineData: {
          data: base64Data,
          mimeType: mimeType
        }
      });
    }

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: [{ parts }],
      config: {
        temperature: 0.3,
        maxOutputTokens: 1000,
      },
    });

    return response.text?.trim() || issue;
  } catch (error) {
    console.error("Errore analisi multimodale:", error);
    return issue;
  }
};

export const generateExecutiveSummary = async (condoName: string, issues: string[]): Promise<string> => {
  if (issues.length === 0) return "Sopralluogo tecnico effettuato per verificare lo stato manutentivo generale dell'immobile.";

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Sei l'Ing. Serra. Redigi una relazione tecnica esecutiva completa e approfondita per il condominio "${condoName}".

      DATI RILEVATI: ${issues.join("; ")}.

      REGOLE:
      - Sii esaustivo e non sintetico: descrivi lo stato di fatto generale.
      - Valuta la criticità complessiva (Bassa, Media, Alta).
      - Proponi un piano di intervento cronologico.
      - Mantieni un tono di altissima professionalità.
      - La relazione deve essere lunga almeno 150-200 parole per essere credibile ai condomini.`,
      config: {
        temperature: 0.5,
        maxOutputTokens: 1500, // Aumentato per evitare tagli nel testo
      }
    });
    return response.text?.trim() || "Relazione tecnica dettagliata sullo stato dell'immobile.";
  } catch (error) {
    console.error("Errore sintesi IA:", error);
    return "Sopralluogo tecnico effettuato con rilievo di criticità.";
  }
};

