              <div className="grid grid-cols-1 md:grid-cols-3 gap-8 mb-14">
                <div className="bg-slate-50/50 p-8 rounded-3xl border border-slate-100">
                  <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-3">Condominio</h3>
                  <p className="text-2xl font-black text-slate-900 tracking-tight">{data.condoName}</p>
                </div>
                <div className="bg-slate-50/50 p-8 rounded-3xl border border-slate-100">
                  <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-3">Data Sopralluogo</h3>
                  <p className="text-2xl font-black text-slate-900 tracking-tight">{new Date(data.inspectionDate).toLocaleDateString('it-IT', { day: 'numeric', month: 'long', year: 'numeric' })}</p>
                </div>
                <div className="bg-slate-50/50 p-8 rounded-3xl border border-slate-100">
                  <h3 className="text-[10px] font-black uppercase tracking-widest mb-3" style={{ color: PRIMARY_COLOR }}>Punti Rilevati</h3>
                  <p className="font-black text-2xl text-slate-900 tracking-tight">{filteredPhotos.length}</p>
                </div>
              </div>

              <div className="mb-20 bg-slate-900 p-10 rounded-[3rem] text-white relative">
                <h3 className="text-xs font-black uppercase tracking-[0.4em] mb-6" style={{ color: PRIMARY_COLOR }}>Sintesi Esecutiva Professionale</h3>
                {isGeneratingSummary ? (
                   <p className="text-xl font-light italic text-slate-300 animate-pulse">L'IA sta elaborando la relazione tecnica completa...</p>
                ) : (
                  <>
                    <textarea 
                      ref={summaryRef}
                      className="w-full bg-transparent border-none text-white text-xl font-light italic resize-none focus:ring-0 p-0 outline-none print-text-area overflow-hidden" 
                      value={summary} 
                      onChange={(e) => { setSummary(e.target.value); adjustTextareaHeight(e.target); }} 
                    />
                    <div className="print-text-mirror text-white text-xl font-light italic">{summary}</div>
                  </>
                )}
              </div>

              <div className="space-y-32">
                {filteredPhotos.map((indexPhoto, idx) => (
                  <div key={indexPhoto.id} className="break-inside-avoid">
                    <div className="flex items-center justify-between mb-10 border-b-4 border-slate-50 pb-8">
                      <div className="flex items-center gap-8">
                        <span className="text-white w-14 h-14 rounded-[1.5rem] flex items-center justify-center font-black text-2xl rotate-3 shadow-sm" style={{ backgroundColor: PRIMARY_COLOR }}>{idx + 1}</span>
                        <div>
                          <p className="text-[11px] font-black text-slate-400 uppercase tracking-widest mb-1">Rilievo Tecnico Dettagliato n. {idx + 1}</p>
                          <h4 className="text-3xl font-black text-slate-900 uppercase italic" style={{ color: PRIMARY_COLOR }}>{indexPhoto.category}</h4>
                        </div>
                      </div>
                      <div className="text-right">
                        <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Responsabile Ripristino</span>
                        <p className="text-xl font-black text-slate-800 uppercase">{indexPhoto.supplier || "Da assegnare"}</p>
                      </div>
                    </div>
                    <div className="grid grid-cols-1 md:grid-cols-12 gap-16">
                      <div className="md:col-span-5">
                        <div className="aspect-[4/3] rounded-[3rem] overflow-hidden border-4 border-slate-50 shadow-sm mb-6">
                          <img src={indexPhoto.url} alt={`Dettaglio ${idx + 1}`} className="w-full h-full object-cover" />
                        </div>
                      </div>
                      <div className="md:col-span-7">
                        <h5 className="text-[11px] font-black text-slate-400 uppercase tracking-[0.3em] flex items-center gap-3 mb-6">
                          <span className="w-2.5 h-2.5 rounded-full" style={{ backgroundColor: PRIMARY_COLOR }}></span> Analisi dello Stato di Fatto
                        </h5>
                        <textarea className="w-full text-slate-800 text-xl font-bold italic bg-slate-50/50 p-10 rounded-[3rem] border-2 border-slate-50 resize-none outline-none print-text-area overflow-hidden" value={indexPhoto.aiPolishedIssue || indexPhoto.issue} onChange={(e) => { updatePhoto(indexPhoto.id, { aiPolishedIssue: e.target.value, issue: e.target.value }); adjustTextareaHeight(e.target); }} />
                        <div className="print-text-mirror text-slate-800 text-xl font-bold italic bg-slate-50/50 p-10 rounded-[3rem] border-2 border-slate-50">
                          {indexPhoto.aiPolishedIssue || indexPhoto.issue}
                        </div>
                      </div>
                    </div>
                  </div>
                ))}
              </div>

              <div className="mt-48 pt-20 border-t-4 border-slate-900 flex justify-between items-end break-inside-avoid">
                <div className="max-w-md">
                  <p className="text-[11px] font-black text-slate-400 uppercase tracking-widest mb-6">Documento emesso e validato da:</p>
                  <p className="text-base font-black text-slate-900 uppercase">{STUDIO_NAME}</p>
                </div>
                <div className="text-center w-96">
                  <div className="h-0.5 bg-slate-200 w-full mb-8"></div>
                  <p className="text-xs font-black text-slate-400 uppercase tracking-widest mb-2">Timbro e Firma Professionale</p>
                </div>
              </div>
            </div>
          </div>
        )}
      </main>
    </div>
  );
};

export default App;

import React, { useState, useMemo, useEffect, useCallback, useRef } from 'react';
import { 
  Building2, 
  Calendar, 
  Camera, 
  Trash2, 
  ChevronRight, 
  ChevronLeft, 
  FileText, 
  Wand2,
  MapPin,
  Image as ImageIcon,
  X,
  Loader2,
  Sparkles,
  ArrowDownLeft,
  Briefcase,
  Printer
} from 'lucide-react';
import { AppStep, InspectionData, InspectionPhoto, Coordinates } from './types';
import { professionalizeDescription, generateExecutiveSummary } from './services/geminiService';

const DEFAULT_CATEGORIES = ['Strutturale', 'Impianto Idraulico', 'Impianto Elettrico', 'Estetica/Facciata', 'Aree Comuni', 'Sicurezza'];
const STUDIO_NAME = "Studio Amministrazioni Condominiali Ing. Serra";
const STUDIO_TAGLINE = "il condominio trasparente: tutto limpido, tutto evidente";
const PRIMARY_COLOR = "#64a1a4";

const App: React.FC = () => {
  const [step, setStep] = useState<AppStep>(AppStep.SETUP);
  const [isExporting, setIsExporting] = useState(false);
  const summaryRef = useRef<HTMLTextAreaElement>(null);

  const [data, setData] = useState<InspectionData>({
    condoName: '',
    inspectionDate: new Date().toISOString().split('T')[0],
    logoUrl: undefined,
    technicalNotes: 'Sopralluogo effettuato per verifica stato conservativo generale dell\'immobile e delle pertinenze comuni.',
    photos: [],
    availableCategories: DEFAULT_CATEGORIES
  });

  const [summary, setSummary] = useState('');
  const [isGeneratingSummary, setIsGeneratingSummary] = useState(false);

  const isSetupValid = useMemo(() => {
    return data.condoName.trim().length > 0 && data.inspectionDate.length > 0;
  }, [data.condoName, data.inspectionDate]);

  const adjustTextareaHeight = (target: HTMLTextAreaElement | null) => {
    if (!target) return;
    target.style.height = 'auto';
    target.style.height = `${target.scrollHeight}px`;
  };

  useEffect(() => {
    if (step === AppStep.REPORT) {
      setTimeout(() => {
        adjustTextareaHeight(summaryRef.current);
        document.querySelectorAll('textarea').forEach(ta => adjustTextareaHeight(ta as HTMLTextAreaElement));
      }, 300);
    }
  }, [step, summary]);

  const fileToBase64 = (file: File): Promise<string> => {
    return new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.readAsDataURL(file);
      reader.onload = () => {
        const base64String = (reader.result as string).split(',')[1];
        resolve(base64String);
      };
      reader.onerror = error => reject(error);
    });
  };

  const getCoordinates = (): Promise<Coordinates | undefined> => {
    return new Promise((resolve) => {
      if (!navigator.geolocation) {
        resolve(undefined);
        return;
      }
      navigator.geolocation.getCurrentPosition(
        (position) => {
          resolve({ latitude: position.coords.latitude, longitude: position.coords.longitude });
        },
        () => resolve(undefined),
        { timeout: 4000 }
      );
    });
  };

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files) {
      const coords = await getCoordinates();
      const newFiles = Array.from(e.target.files) as File[];

      const newPhotosPromises = newFiles.map(async (file) => {
        const base64 = await fileToBase64(file);
        return {
          id: Math.random().toString(36).substr(2, 9),
          url: URL.createObjectURL(file),
          base64Data: base64,
          mimeType: file.type,
          issue: '',
          supplier: '',
          category: data.availableCategories[0] || DEFAULT_CATEGORIES[0],
          coordinates: coords
        };
      });

      const newPhotos = await Promise.all(newPhotosPromises);
      setData(prev => ({ ...prev, photos: [...prev.photos, ...newPhotos] }));
    }
  };

  const handleLogoChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files?.[0]) {
      const url = URL.createObjectURL(e.target.files[0]);
      setData(prev => ({ ...prev, logoUrl: url }));
    }
  };

  const updatePhoto = (id: string, updates: Partial<InspectionPhoto>) => {
    setData(prev => ({
      ...prev,
      photos: prev.photos.map(p => p.id === id ? { ...p, ...updates } : p)
    }));
  };

  const removePhoto = (id: string) => {
    setData(prev => ({
      ...prev,
      photos: prev.photos.filter(p => p.id !== id)
    }));
  };

  const handleAIEnhance = async (photo: InspectionPhoto) => {
    updatePhoto(photo.id, { isLoading: true, aiPolishedIssue: undefined });
    const polished = await professionalizeDescription(
      photo.issue, 
      photo.base64Data, 
      photo.mimeType
    );
    updatePhoto(photo.id, { aiPolishedIssue: polished, isLoading: false });
  };

  const handleGenerateReport = async () => {
    setStep(AppStep.REPORT);
    setIsGeneratingSummary(true);
    const issues = data.photos.map(p => p.aiPolishedIssue || p.issue).filter(Boolean);
    const execSummary = await generateExecutiveSummary(data.condoName, issues);
    setSummary(execSummary);
    setIsGeneratingSummary(false);
  };

  const printReport = useCallback(() => {
    setIsExporting(true);

    // Piccolo ritardo per assicurarsi che i componenti React siano sincronizzati
    setTimeout(() => {
      try {
        window.print();
      } catch (e) {
        console.error("Errore stampa:", e);
      } finally {
        setIsExporting(false);
      }
    }, 500);
  }, []);

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col">
      <header className="bg-white border-b border-slate-200 sticky top-0 z-50 px-4 py-4 print:hidden">
        <div className="max-w-4xl mx-auto flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="p-2.5 rounded-xl shadow-sm" style={{ backgroundColor: PRIMARY_COLOR }}>
              <Briefcase className="text-white w-5 h-5" />
            </div>
            <div>
              <h1 className="text-base font-black text-slate-800 leading-none">Studio Ing. Serra</h1>
              <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest mt-1 italic">CondoInspect Pro</p>
            </div>
          </div>
          <div className="flex items-center gap-4">
            <span className="text-[10px] font-bold uppercase tracking-widest text-slate-400">
              {step === AppStep.SETUP ? '01 Setup' : step === AppStep.PHOTOS ? '02 Rilievi' : '03 Report'}
            </span>
          </div>
        </div>
      </header>

      <main className="flex-1 max-w-4xl mx-auto w-full p-4 sm:p-6 pb-20 print:p-0">
        {step === AppStep.SETUP && (
          <div className="bg-white rounded-3xl shadow-sm border border-slate-200 p-8 sm:p-10">
            <div className="flex flex-col sm:flex-row items-center justify-between mb-10 pb-6 border-b border-slate-100 gap-6">
              <div className="text-center sm:text-left">
                <h2 className="text-3xl font-black italic" style={{ color: PRIMARY_COLOR }}>STUDIO SERRA</h2>
                <p className="text-sm font-bold text-slate-500 uppercase tracking-wider">{STUDIO_NAME}</p>
                <p className="text-xs text-slate-400 italic">{STUDIO_TAGLINE}</p>
              </div>
              {data.logoUrl && (
                <div className="w-20 h-20 rounded-2xl border-2 border-slate-100 p-1 bg-white">
                  <img src={data.logoUrl} className="w-full h-full object-contain" alt="Logo" />
                </div>
              )}
            </div>

            <div className="space-y-8">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                <div className="space-y-2">
                  <label className="text-xs font-black uppercase text-slate-500">Nome Condominio *</label>
                  <input type="text" className="w-full px-5 py-4 bg-slate-50 border border-slate-200 rounded-2xl focus:ring-2 outline-none font-medium text-slate-800" value={data.condoName} onChange={(e) => setData({...data, condoName: e.target.value})} placeholder="es. Condominio Roma" />
                </div>
                <div className="space-y-2">
                  <label className="text-xs font-black uppercase text-slate-500">Data Sopralluogo *</label>
                  <input type="date" className="w-full px-5 py-4 bg-slate-50 border border-slate-200 rounded-2xl focus:ring-2 outline-none font-medium text-slate-800" value={data.inspectionDate} onChange={(e) => setData({...data, inspectionDate: e.target.value})} />
                </div>
              </div>

              <div className="space-y-2">
                <label className="text-xs font-black uppercase text-slate-500">Logo Studio Professionale</label>
                <label className="border-2 border-dashed border-slate-200 rounded-2xl p-6 flex flex-col items-center justify-center gap-2 cursor-pointer hover:bg-slate-50 transition-all">
                  <ImageIcon className="w-8 h-8 text-slate-300" />
                  <span className="text-sm font-bold text-slate-400 uppercase">{data.logoUrl ? "Logo caricato" : "Clicca per caricare il logo"}</span>
                  <input type="file" accept="image/*" className="hidden" onChange={handleLogoChange} />
                </label>
              </div>

              <div className="space-y-2">
                <label className="text-xs font-black uppercase text-slate-500">Note Generali</label>
                <textarea className="w-full px-5 py-4 bg-slate-50 border border-slate-200 rounded-2xl focus:ring-2 outline-none min-h-[100px] resize-none font-medium text-slate-700" value={data.technicalNotes} onChange={(e) => setData({...data, technicalNotes: e.target.value})} />
              </div>
            </div>

            <div className="mt-12">
              <button disabled={!isSetupValid} onClick={() => setStep(AppStep.PHOTOS)} className="w-full text-white font-black py-5 rounded-2xl shadow-xl flex items-center justify-center gap-3 uppercase tracking-widest text-sm" style={{ backgroundColor: isSetupValid ? PRIMARY_COLOR : "#cbd5e1" }}>
                Prosegui ai Rilievi <ChevronRight className="w-6 h-6" />
              </button>
            </div>
          </div>
        )}

        {step === AppStep.PHOTOS && (
          <div className="space-y-6">
            <div className="flex items-center justify-between bg-white p-4 rounded-2xl border border-slate-200 sticky top-20 z-40 print:hidden">
              <button onClick={() => setStep(AppStep.SETUP)} className="text-slate-400 hover:text-slate-800 font-bold text-xs uppercase flex items-center gap-1">
                <ChevronLeft className="w-4 h-4" /> Indietro
              </button>
              <label className="flex items-center gap-2 text-white px-6 py-2.5 rounded-xl cursor-pointer shadow-lg font-black text-xs uppercase" style={{ backgroundColor: PRIMARY_COLOR }}>
                <Camera className="w-4 h-4" /> Carica Foto
                <input type="file" multiple accept="image/*" className="hidden" onChange={handleFileChange} />
              </label>
            </div>

            <div className="space-y-6">
              {data.photos.length === 0 ? (
                <div className="bg-white border-2 border-dashed border-slate-200 rounded-3xl p-20 flex flex-col items-center gap-4 text-center">
                  <ImageIcon className="w-10 h-10 text-slate-200" />
                  <p className="font-bold text-slate-400">Nessuna foto. Carica le immagini del sopralluogo.</p>
                </div>
              ) : (
                data.photos.map((photo) => (
                  <div key={photo.id} className="bg-white rounded-3xl shadow-sm border border-slate-200 overflow-hidden flex flex-col group">
                    <div className="flex flex-col md:flex-row h-full">
                      <div className="md:w-1/3 relative bg-slate-100 min-h-[220px]">
                        <img src={photo.url} alt="Rilievo" className="w-full h-full object-cover" />
                        <button onClick={() => removePhoto(photo.id)} className="absolute top-3 right-3 p-2 bg-red-500 text-white rounded-xl shadow-lg"><Trash2 className="w-4 h-4" /></button>
                      </div>
                      <div className="flex-1 p-6 space-y-4">
                        <div className="grid grid-cols-2 gap-4">
                          <div className="space-y-1">
                            <label className="text-[10px] font-black uppercase text-slate-400">Ambito</label>
                            <select className="w-full p-2.5 bg-slate-50 border border-slate-200 rounded-xl text-xs font-bold" value={photo.category} onChange={(e) => updatePhoto(photo.id, { category: e.target.value })}>
                              {data.availableCategories.map(cat => <option key={cat} value={cat}>{cat}</option>)}
                            </select>
                          </div>
                          <div className="space-y-1">
                            <label className="text-[10px] font-black uppercase text-slate-400">Fornitore</label>
                            <input type="text" placeholder="Ditta..." className="w-full p-2.5 bg-slate-50 border border-slate-200 rounded-xl text-xs font-bold" value={photo.supplier} onChange={(e) => updatePhoto(photo.id, { supplier: e.target.value })} />
                          </div>
                        </div>
                        <div className="space-y-1">
                          <label className="text-[10px] font-black uppercase text-slate-400">Descrizione</label>
                          <div className="relative">
                            <textarea placeholder="Descrivi il problema..." className="w-full p-4 bg-slate-50 border border-slate-200 rounded-2xl text-sm font-medium min-h-[80px]" value={photo.issue} onChange={(e) => updatePhoto(photo.id, { issue: e.target.value })} />
                            <button onClick={() => handleAIEnhance(photo)} disabled={photo.isLoading} className="absolute bottom-3 right-3 p-2 bg-white border border-slate-200 rounded-xl shadow-sm disabled:opacity-50" style={{ color: PRIMARY_COLOR }}>
                              {photo.isLoading ? <Loader2 className="animate-spin h-4 w-4" /> : <Wand2 className="w-4 h-4" />}
                            </button>
                          </div>
                        </div>
                      </div>
                    </div>
                    {photo.aiPolishedIssue && (
                      <div className="p-6 bg-slate-50 border-t border-slate-100">
                        <p className="text-xs font-bold text-slate-500 uppercase flex items-center gap-2 mb-2"><Sparkles className="w-3 h-3" /> Analisi Professionale IA</p>
                        <p className="text-sm italic font-bold text-slate-700 bg-white p-4 rounded-xl border border-slate-200">{photo.aiPolishedIssue}</p>
                        <button onClick={() => updatePhoto(photo.id, { issue: photo.aiPolishedIssue, aiPolishedIssue: undefined })} className="mt-3 flex items-center gap-2 text-[10px] font-black uppercase px-4 py-2 bg-[#64a1a4] text-white rounded-lg"><CheckCircle2 className="w-3 h-3" /> Usa questa descrizione</button>
                      </div>
                    )}
                  </div>
                ))
              )}
            </div>

            <div className="pt-10">
              <button disabled={data.photos.length === 0} onClick={handleGenerateReport} className="w-full bg-slate-900 text-white font-black py-5 rounded-2xl shadow-xl flex items-center justify-center gap-3 uppercase tracking-widest text-sm">
                Genera Verbale <FileText className="w-6 h-6" />
              </button>
            </div>
          </div>
        )}

        {step === AppStep.REPORT && (
          <div className="space-y-8 animate-in fade-in duration-500 print:p-0">
            <div className="flex items-center justify-between gap-4 print:hidden">
              <button onClick={() => setStep(AppStep.PHOTOS)} className="flex items-center gap-2 text-slate-500 font-bold text-xs uppercase"><ChevronLeft className="w-4 h-4" /> Indietro</button>
              <button onClick={printReport} disabled={isExporting} className="bg-[#64a1a4] text-white px-8 py-3 rounded-xl shadow-lg flex items-center gap-3 font-black text-xs uppercase">
                {isExporting ? <Loader2 className="animate-spin w-4 h-4" /> : <Printer className="w-4 h-4" />}
                Scarica PDF
              </button>
            </div>

            <div id="final-report" className="bg-white p-10 sm:p-14 shadow-sm print:p-0">
              {/* Header Report */}
              <div className="border-b-4 border-[#64a1a4] pb-8 mb-10 flex flex-col md:flex-row justify-between items-start md:items-center gap-6">
                <div className="flex items-center gap-6">
                  {data.logoUrl && <img src={data.logoUrl} alt="Logo" className="h-20 w-auto object-contain" />}
                  <div>
                    <h2 className="text-2xl font-black italic text-primary uppercase leading-tight" style={{ color: PRIMARY_COLOR }}>STUDIO SERRA</h2>
                    <p className="text-xs font-bold text-slate-500">{STUDIO_NAME}</p>
                    <p className="text-[10px] text-slate-400 italic">{STUDIO_TAGLINE}</p>
                  </div>
                </div>
                <div className="md:text-right">
                  <h1 className="text-3xl font-black text-slate-900 leading-none">VERBALE DI SOPRALLUOGO</h1>
                  <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mt-1">Sito: {data.condoName}</p>
                </div>
              </div>

              {/* Dettagli Condominio */}
              <div className="grid grid-cols-2 sm:grid-cols-3 gap-4 mb-10">
                <div className="bg-slate-50 p-6 rounded-2xl print:border print:border-slate-100">
                  <h3 className="text-[9px] font-black text-slate-400 uppercase mb-1">Data Sopralluogo</h3>
                  <p className="font-black text-slate-800">{new Date(data.inspectionDate).toLocaleDateString('it-IT')}</p>
                </div>
                <div className="bg-slate-50 p-6 rounded-2xl print:border print:border-slate-100">
                  <h3 className="text-[9px] font-black text-slate-400 uppercase mb-1">Rilievi Effettuati</h3>
                  <p className="font-black text-slate-800">{data.photos.length}</p>
                </div>
              </div>

              {/* Sintesi Esecutiva */}
              <div className="mb-16">
                <h3 className="text-xs font-black uppercase text-primary mb-4" style={{ color: PRIMARY_COLOR }}>SINTESI TECNICA ESECUTIVA</h3>
                {isGeneratingSummary ? (
                   <p className="text-slate-400 italic animate-pulse">Generazione sintesi in corso...</p>
                ) : (
                  <>
                    <textarea 
                      ref={summaryRef}
                      className="w-full bg-slate-50 border-none p-8 rounded-2xl text-slate-700 italic text-base leading-relaxed font-medium resize-none print:hidden" 
                      value={summary} 
                      onChange={(e) => setSummary(e.target.value)} 
                    />
                    <div className="print-text-content">{summary}</div>
                  </>
                )}
              </div>

              {/* Elenco Rilievi */}
              <div className="space-y-20">
                {data.photos.map((photo, idx) => (
                  <div key={photo.id} className="break-inside-avoid">
                    <div className="flex items-center gap-4 mb-6 border-b pb-4">
                      <span className="bg-primary text-white w-8 h-8 rounded-lg flex items-center justify-center font-black" style={{ backgroundColor: PRIMARY_COLOR }}>{idx + 1}</span>
                      <h4 className="text-xl font-black uppercase text-slate-800 italic">{photo.category}</h4>
                      <span className="ml-auto text-[10px] font-bold text-slate-400 uppercase">Rif: {photo.supplier || "N/A"}</span>
                    </div>
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
