            {/* Action Bar */}
            <div className="flex flex-col sm:flex-row items-center justify-between gap-4 print:hidden bg-white p-6 rounded-3xl border border-slate-200 shadow-lg sticky top-20 z-50">
              <button onClick={() => setStep(AppStep.PHOTOS)} className="flex items-center gap-2 text-slate-500 font-bold text-xs uppercase hover:text-slate-800 transition-colors">
                <ChevronLeft className="w-4 h-4" /> Modifica Rilievi
              </button>

              <div className="flex items-center gap-3">
                <button 
                  onClick={() => setIsEditMode(!isEditMode)} 
                  className={`px-5 py-3 rounded-xl font-black text-xs uppercase border transition-all ${isEditMode ? 'bg-slate-900 text-white border-slate-900' : 'bg-white text-slate-600 border-slate-200 hover:bg-slate-50'}`}
                >
                  {isEditMode ? 'Fine Modifica' : 'Modifica Testi'}
                </button>

                <button 
                  onClick={printReport} 
                  disabled={isExporting} 
                  className="bg-[#1e293b] text-white px-10 py-4 rounded-2xl shadow-2xl flex items-center gap-4 font-black text-sm uppercase tracking-widest transition-all hover:scale-105 active:scale-95 disabled:bg-slate-400 group overflow-hidden relative"
                >
                  <div className="flex items-center gap-3 relative z-10">
                    {isExporting ? <Loader2 className="animate-spin w-5 h-5" /> : <FileDown className="w-5 h-5 group-hover:translate-y-0.5 transition-transform" />}
