                  </div>
                  <div className="absolute inset-0 bg-emerald-500 opacity-0 group-hover:opacity-10 transition-opacity"></div>
                </button>
              </div>
            </div>

            {/* Document Container */}
            <div id="final-report" className="bg-white p-10 sm:p-20 shadow-2xl rounded-sm print:shadow-none print:p-0 print:border-none">

              {/* Report Header */}
