                <div className="bg-slate-50 p-8 rounded-3xl border border-slate-100">
                  <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Rilievi</h3>
                  <p className="text-xl font-black text-slate-900">{data.photos.length} anomalie riscontrate</p>
                </div>
              </div>

              {/* Sezione Sintesi (Editabile) */}
