                <div className="flex items-center justify-between mb-6">
                  <div className="flex items-center gap-3">
                    <div className="h-1 w-12 bg-[#64a1a4]" />
                    <h3 className="text-xs font-black uppercase tracking-widest text-[#64a1a4]">Sintesi Tecnica Professionale</h3>
                  </div>
                  <div className="flex items-center gap-2 text-[10px] font-bold text-slate-400 uppercase print:hidden">
                    <Edit3 className="w-3 h-3" /> Clicca sotto per modificare
                  </div>
                </div>

                {isGeneratingSummary ? (
                   <div className="flex items-center gap-4 p-12 bg-slate-50 rounded-[3rem] border border-slate-100">
                     <Loader2 className="animate-spin w-6 h-6 text-slate-400" />
                     <p className="text-slate-400 italic text-lg animate-pulse font-medium">L'IA sta redigendo la sintesi professionale...</p>
