                    <textarea 
                      className="edit-area w-full bg-slate-900 p-10 sm:p-14 rounded-[3rem] text-white text-xl font-light italic leading-relaxed whitespace-pre-wrap outline-none focus:ring-4 focus:ring-[#64a1a4]/30 transition-all border-none resize-none overflow-hidden"
                      value={summary}
                      onChange={(e) => {
                        setSummary(e.target.value);
                        adjustTextareaHeight(e.target);
