                        <img src={photo.url} alt={`Dettaglio ${idx+1}`} className="w-full h-full object-cover" />
                      </div>
                      <div className="flex flex-col h-full">
                        <h5 className="text-[10px] font-black text-[#64a1a4] uppercase tracking-widest flex items-center gap-2 mb-6">
                          <AlertCircle className="w-3 h-3" /> Analisi Diagnostica
                        </h5>
                        <textarea 
                          className="edit-area w-full bg-slate-50 p-10 rounded-[3rem] border-2 border-slate-100 text-slate-800 text-xl font-bold italic leading-relaxed resize-none outline-none focus:bg-white focus:border-[#64a1a4]/50 transition-all overflow-hidden"
                          value={photo.aiPolishedIssue || photo.issue}
                          onChange={(e) => {
                            updatePhoto(photo.id, { aiPolishedIssue: e.target.value, issue: e.target.value });
                            adjustTextareaHeight(e.target);
                          }}
                          onFocus={(e) => adjustTextareaHeight(e.target)}
                          rows={1}
                        />
                        <div className="print-mirror bg-slate-50 p-10 rounded-[3rem] border-2 border-slate-100 text-slate-800 text-xl font-bold italic">
                          {photo.aiPolishedIssue || photo.issue}
                        </div>
                      </div>
                    </div>
                  </div>
                ))}
              </div>

              {/* Chiusura Verbale */}
              <div className="mt-48 pt-20 border-t-2 border-slate-900 flex flex-col sm:flex-row justify-between items-end break-inside-avoid gap-12">
                <div className="max-w-md">
                  <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-4">Emesso da:</p>
                  <p className="text-lg font-black text-slate-900 uppercase leading-tight">{STUDIO_NAME}</p>
                  <p className="text-xs font-medium text-slate-400 mt-1 italic">Sopralluogo effettuato con tecnologia assistita.</p>
                </div>
                <div className="text-center w-full sm:w-80">
                  <div className="h-0.5 bg-slate-200 w-full mb-6"></div>
                  <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest text-center">Timbro e Firma del Professionista</p>
                </div>
              </div>

              <div className="mt-20 text-[9px] text-slate-300 font-bold uppercase tracking-[0.2em] text-center print:block hidden">
                Verbale generato digitalmente tramite CondoInspect Pro. Data emissione: {new Date().toLocaleDateString('it-IT')}.
              </div>
            </div>
          </div>
        )}
      </main>
    </div>
  );
};

export default App;

import React, { useState, useMemo, useEffect, useCallback, useRef } from 'react';
import { 
  Camera, 
  Trash2, 
  ChevronRight, 
  ChevronLeft, 
  FileText, 
  Wand2,
  Image as ImageIcon,
  Loader2,
  Sparkles,
  Briefcase,
  Printer,
  Check,
  FileDown,
  Edit3,
  AlertCircle,
  X,
  Link as LinkIcon
} from 'lucide-react';
import { AppStep, InspectionData, InspectionPhoto, Coordinates } from './types';
import { professionalizeDescription, generateExecutiveSummary } from './services/geminiService';

const DEFAULT_CATEGORIES = ['Strutturale', 'Impianto Idraulico', 'Impianto Elettrico', 'Estetica/Facciata', 'Aree Comuni', 'Sicurezza'];
const STUDIO_NAME = "Studio Amministrazioni Condominiali Ing. Serra";
const STUDIO_TAGLINE = "il condominio trasparente: tutto limpido, tutto evidente";
const PRIMARY_COLOR = "#64a1a4";

const App: React.FC = () => {
  const [step, setStep] = useState<AppStep>(AppStep.SETUP);
  const [isExporting, setIsExporting] = useState(false);
  const [showFilePrompt, setShowFilePrompt] = useState(false);
  const [customFileName, setCustomFileName] = useState('');

  const [data, setData] = useState<InspectionData>({
    condoName: '',
    inspectionDate: new Date().toISOString().split('T')[0],
    logoUrl: undefined,
    technicalNotes: 'Sopralluogo effettuato per verifica stato conservativo generale dell\'immobile e delle pertinenze comuni.',
    photos: [],
    availableCategories: DEFAULT_CATEGORIES
  });

  const [summary, setSummary] = useState('');
  const [isGeneratingSummary, setIsGeneratingSummary] = useState(false);

  const isSetupValid = useMemo(() => {
    return data.condoName.trim().length > 0 && data.inspectionDate.length > 0;
  }, [data.condoName, data.inspectionDate]);

  useEffect(() => {
    if (data.condoName && !customFileName) {
      setCustomFileName(`Report_${data.condoName.replace(/\s+/g, '_')}_${data.inspectionDate}`);
    }
  }, [data.condoName, data.inspectionDate]);

  const adjustTextareaHeight = (target: HTMLTextAreaElement | null) => {
    if (!target) return;
    target.style.height = 'auto';
    target.style.height = `${target.scrollHeight}px`;
  };

  const fileToBase64 = (file: File): Promise<string> => {
    return new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.readAsDataURL(file);
      reader.onload = () => {
        const base64String = (reader.result as string).split(',')[1];
        resolve(base64String);
      };
      reader.onerror = error => reject(error);
    });
  };

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files) {
      const newFiles = Array.from(e.target.files) as File[];
      const newPhotosPromises = newFiles.map(async (file) => {
        const base64 = await fileToBase64(file);
        return {
          id: Math.random().toString(36).substr(2, 9),
          url: URL.createObjectURL(file),
          base64Data: base64,
          mimeType: file.type,
          issue: '',
          supplier: '',
          category: data.availableCategories[0] || DEFAULT_CATEGORIES[0],
        };
      });
      const newPhotos = await Promise.all(newPhotosPromises);
      setData(prev => ({ ...prev, photos: [...prev.photos, ...newPhotos] }));
    }
  };

  const handleLogoChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files?.[0]) {
      const url = URL.createObjectURL(e.target.files[0]);
      setData(prev => ({ ...prev, logoUrl: url }));
    }
  };

  const updatePhoto = (id: string, updates: Partial<InspectionPhoto>) => {
    setData(prev => ({
      ...prev,
      photos: prev.photos.map(p => p.id === id ? { ...p, ...updates } : p)
    }));
  };

  const removePhoto = (id: string) => {
    setData(prev => ({
      ...prev,
      photos: prev.photos.filter(p => p.id !== id)
    }));
  };

  const handleAIEnhance = async (photo: InspectionPhoto) => {
    updatePhoto(photo.id, { isLoading: true, aiPolishedIssue: undefined });
    const polished = await professionalizeDescription(
      photo.issue, 
      photo.base64Data, 
      photo.mimeType
    );
    updatePhoto(photo.id, { aiPolishedIssue: polished, isLoading: false });
  };

  const handleGenerateReport = async () => {
    setStep(AppStep.REPORT);
    setIsGeneratingSummary(true);
    const issues = data.photos.map(p => p.aiPolishedIssue || p.issue).filter(Boolean);
    const execSummary = await generateExecutiveSummary(data.condoName, issues);
    setSummary(execSummary);
    setIsGeneratingSummary(false);
  };

  const executePrint = useCallback(() => {
    setShowFilePrompt(false);
    setIsExporting(true);

    // Imposta il titolo del documento che il browser userà come nome file
    const originalTitle = document.title;
    document.title = customFileName || "Report_Sopralluogo";

    setTimeout(() => {
      try {
        window.print();
      } catch (e) {
        console.error("Print Error:", e);
        alert("Errore durante la stampa.");
      } finally {
        document.title = originalTitle;
        setIsExporting(false);
      }
    }, 1000);
  }, [customFileName]);

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col font-sans">
      {/* MODAL RICHIESTA NOME FILE / URL */}
      {showFilePrompt && (
        <div className="fixed inset-0 z-[200] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm animate-in fade-in duration-300">
          <div className="bg-white w-full max-w-md rounded-[2.5rem] shadow-2xl p-10 space-y-8 animate-in zoom-in-95 duration-300">
            <div className="flex justify-between items-center">
              <div className="bg-slate-50 p-3 rounded-2xl">
                <LinkIcon className="w-6 h-6 text-[#64a1a4]" />
              </div>
              <button onClick={() => setShowFilePrompt(false)} className="text-slate-300 hover:text-slate-500 transition-colors">
                <X className="w-6 h-6" />
              </button>
            </div>

            <div className="space-y-2">
              <h2 className="text-2xl font-black text-slate-900">Configurazione PDF</h2>
              <p className="text-sm text-slate-500 font-medium">Specifica il nome del file o la posizione URL di riferimento per questo documento.</p>
            </div>

            <div className="space-y-4">
              <div className="space-y-1.5">
                <label className="text-[10px] font-black uppercase tracking-widest text-slate-400 ml-1">Identificativo Documento</label>
                <input 
                  autoFocus
                  type="text" 
                  className="w-full bg-slate-50 border-2 border-slate-100 rounded-2xl px-6 py-4 outline-none focus:border-[#64a1a4] focus:ring-4 focus:ring-[#64a1a4]/10 transition-all font-bold text-slate-800"
                  value={customFileName}
                  onChange={(e) => setCustomFileName(e.target.value)}
                  placeholder="es. Report_Condominio_Marconi_2024"
                />
              </div>
            </div>

            <button 
              onClick={executePrint}
              className="w-full bg-slate-900 text-white font-black py-5 rounded-2xl shadow-xl hover:bg-black transition-all active:scale-95 flex items-center justify-center gap-3"
            >
              Genera e Scarica <ChevronRight className="w-5 h-5" />
            </button>
          </div>
        </div>
      )}

      <header className="bg-white border-b border-slate-200 sticky top-0 z-50 px-4 py-4 print:hidden">
        <div className="max-w-4xl mx-auto flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="p-2.5 rounded-xl shadow-sm" style={{ backgroundColor: PRIMARY_COLOR }}>
              <Briefcase className="text-white w-5 h-5" />
            </div>
            <div>
              <h1 className="text-base font-black text-slate-800 leading-none">Studio Ing. Serra</h1>
              <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest mt-1 italic">CondoInspect Pro</p>
            </div>
          </div>
          <div className="flex items-center gap-4">
             <span className="text-[10px] font-bold uppercase tracking-widest text-slate-400">
               {step === AppStep.SETUP ? '01 Config' : step === AppStep.PHOTOS ? '02 Rilievi' : '03 Documento'}
             </span>
          </div>
        </div>
      </header>

      <main className="flex-1 max-w-4xl mx-auto w-full p-4 sm:p-6 pb-20 print:p-0 print:max-w-none">
        {step === AppStep.SETUP && (
          <div className="bg-white rounded-3xl shadow-sm border border-slate-200 p-8 sm:p-10 animate-in fade-in duration-500">
            <div className="flex flex-col sm:flex-row items-center justify-between mb-10 pb-6 border-b border-slate-100 gap-6">
              <div className="text-center sm:text-left">
                <h2 className="text-3xl font-black italic" style={{ color: PRIMARY_COLOR }}>STUDIO SERRA</h2>
                <p className="text-sm font-bold text-slate-500 uppercase tracking-wider">{STUDIO_NAME}</p>
                <p className="text-xs text-slate-400 italic">{STUDIO_TAGLINE}</p>
              </div>
              {data.logoUrl && (
                <div className="w-20 h-20 rounded-2xl border-2 border-slate-100 p-1 bg-white">
                  <img src={data.logoUrl} className="w-full h-full object-contain" alt="Logo" />
                </div>
              )}
            </div>

            <div className="space-y-8">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                <div className="space-y-2">
                  <label className="text-xs font-black uppercase text-slate-500">Nome Condominio *</label>
                  <input type="text" className="w-full px-5 py-4 bg-slate-50 border border-slate-200 rounded-2xl focus:ring-2 outline-none font-medium text-slate-800" value={data.condoName} onChange={(e) => setData({...data, condoName: e.target.value})} placeholder="es. Condominio Belvedere" />
                </div>
                <div className="space-y-2">
                  <label className="text-xs font-black uppercase text-slate-500">Data Sopralluogo *</label>
                  <input type="date" className="w-full px-5 py-4 bg-slate-50 border border-slate-200 rounded-2xl focus:ring-2 outline-none font-medium text-slate-800" value={data.inspectionDate} onChange={(e) => setData({...data, inspectionDate: e.target.value})} />
                </div>
              </div>

              <div className="space-y-2">
                <label className="text-xs font-black uppercase text-slate-500">Logo Studio Professionale</label>
                <label className="border-2 border-dashed border-slate-200 rounded-2xl p-6 flex flex-col items-center justify-center gap-2 cursor-pointer hover:bg-slate-50 transition-all">
                  <ImageIcon className="w-8 h-8 text-slate-300" />
                  <span className="text-sm font-bold text-slate-400 uppercase">{data.logoUrl ? "Aggiorna Logo" : "Trascina o carica il logo dello studio"}</span>
                  <input type="file" accept="image/*" className="hidden" onChange={handleLogoChange} />
                </label>
              </div>

              <div className="space-y-2">
                <label className="text-xs font-black uppercase text-slate-500">Premessa al Verbale</label>
                <textarea className="w-full px-5 py-4 bg-slate-50 border border-slate-200 rounded-2xl focus:ring-2 outline-none min-h-[100px] resize-none font-medium text-slate-700" value={data.technicalNotes} onChange={(e) => setData({...data, technicalNotes: e.target.value})} />
              </div>
            </div>

            <div className="mt-12">
              <button disabled={!isSetupValid} onClick={() => setStep(AppStep.PHOTOS)} className="w-full text-white font-black py-5 rounded-2xl shadow-xl flex items-center justify-center gap-3 uppercase tracking-widest text-sm transition-all hover:brightness-110 active:scale-[0.98]" style={{ backgroundColor: isSetupValid ? PRIMARY_COLOR : "#cbd5e1" }}>
                Procedi ai Rilievi Fotografici <ChevronRight className="w-6 h-6" />
              </button>
            </div>
          </div>
        )}

        {step === AppStep.PHOTOS && (
          <div className="space-y-6 animate-in slide-in-from-bottom-4">
            <div className="flex items-center justify-between bg-white p-4 rounded-2xl border border-slate-200 sticky top-20 z-40 print:hidden shadow-sm">
              <button onClick={() => setStep(AppStep.SETUP)} className="text-slate-400 hover:text-slate-800 font-bold text-xs uppercase flex items-center gap-1 transition-colors">
                <ChevronLeft className="w-4 h-4" /> Indietro
              </button>
              <label className="flex items-center gap-2 text-white px-6 py-2.5 rounded-xl cursor-pointer shadow-md font-black text-xs uppercase transition-all hover:scale-105 active:scale-95" style={{ backgroundColor: PRIMARY_COLOR }}>
                <Camera className="w-4 h-4" /> Scatta o Carica
                <input type="file" multiple accept="image/*" className="hidden" onChange={handleFileChange} />
              </label>
            </div>

            <div className="space-y-6">
              {data.photos.length === 0 ? (
                <div className="bg-white border-2 border-dashed border-slate-200 rounded-3xl p-20 flex flex-col items-center gap-4 text-center">
                  <ImageIcon className="w-12 h-12 text-slate-200" />
                  <p className="font-bold text-slate-400 italic">Carica le immagini del sopralluogo per iniziare l'analisi professionale.</p>
                </div>
              ) : (
                data.photos.map((photo) => (
                  <div key={photo.id} className="bg-white rounded-3xl shadow-sm border border-slate-200 overflow-hidden flex flex-col group transition-all">
                    <div className="flex flex-col md:flex-row h-full">
                      <div className="md:w-1/3 relative bg-slate-100 min-h-[220px]">
                        <img src={photo.url} alt="Anteprima" className="w-full h-full object-cover" />
                        <button onClick={() => removePhoto(photo.id)} className="absolute top-3 right-3 p-2 bg-red-500 text-white rounded-xl shadow-lg opacity-0 group-hover:opacity-100 transition-opacity"><Trash2 className="w-4 h-4" /></button>
                      </div>
                      <div className="flex-1 p-6 space-y-4">
                        <div className="grid grid-cols-2 gap-4">
                          <div className="space-y-1">
                            <label className="text-[10px] font-black uppercase text-slate-400">Settore</label>
                            <select className="w-full p-2.5 bg-slate-50 border border-slate-200 rounded-xl text-xs font-bold" value={photo.category} onChange={(e) => updatePhoto(photo.id, { category: e.target.value })}>
                              {data.availableCategories.map(cat => <option key={cat} value={cat}>{cat}</option>)}
                            </select>
                          </div>
                          <div className="space-y-1">
                            <label className="text-[10px] font-black uppercase text-slate-400">Ditta Manutentrice</label>
                            <input type="text" placeholder="Nome ditta..." className="w-full p-2.5 bg-slate-50 border border-slate-200 rounded-xl text-xs font-bold" value={photo.supplier} onChange={(e) => updatePhoto(photo.id, { supplier: e.target.value })} />
                          </div>
                        </div>
                        <div className="space-y-1">
                          <label className="text-[10px] font-black uppercase text-slate-400">Descrizione del Difetto</label>
                          <div className="relative">
                            <textarea placeholder="Descrivi il problema riscontrato..." className="w-full p-4 bg-slate-50 border border-slate-200 rounded-2xl text-sm font-medium min-h-[100px] resize-none" value={photo.issue} onChange={(e) => updatePhoto(photo.id, { issue: e.target.value })} />
                            <button onClick={() => handleAIEnhance(photo)} disabled={photo.isLoading} className="absolute bottom-3 right-3 p-2 bg-white border border-slate-200 rounded-xl shadow-sm hover:bg-slate-50 transition-all disabled:opacity-50" style={{ color: PRIMARY_COLOR }}>
                              {photo.isLoading ? <Loader2 className="animate-spin h-4 w-4" /> : <Wand2 className="w-4 h-4" />}
                            </button>
                          </div>
                        </div>
                      </div>
                    </div>
                    {photo.aiPolishedIssue && (
                      <div className="p-6 bg-slate-50 border-t border-slate-100 animate-in fade-in">
                        <p className="text-xs font-bold text-slate-500 uppercase flex items-center gap-2 mb-2"><Sparkles className="w-3 h-3 text-[#64a1a4]" /> Ottimizzazione Professionale</p>
                        <p className="text-sm italic font-bold text-slate-700 bg-white p-5 rounded-xl border border-slate-200 shadow-inner">{photo.aiPolishedIssue}</p>
                        <div className="flex gap-2 mt-4">
                          <button onClick={() => updatePhoto(photo.id, { issue: photo.aiPolishedIssue, aiPolishedIssue: undefined })} className="flex items-center gap-2 text-[10px] font-black uppercase px-5 py-2.5 bg-[#64a1a4] text-white rounded-xl shadow-md transition-transform hover:scale-105 active:scale-95"><Check className="w-3 h-3" /> Applica Testo IA</button>
                        </div>
                      </div>
                    )}
                  </div>
                ))
              )}
            </div>

            <div className="pt-10">
              <button disabled={data.photos.length === 0} onClick={handleGenerateReport} className="w-full bg-slate-900 text-white font-black py-6 rounded-2xl shadow-xl flex items-center justify-center gap-3 uppercase tracking-widest text-sm transition-all hover:brightness-125">
                Genera Report Finale <FileText className="w-6 h-6" />
              </button>
            </div>
          </div>
        )}

        {step === AppStep.REPORT && (
          <div className="space-y-8 animate-in fade-in duration-700 print:p-0 relative">

            <div className="fixed bottom-8 right-8 z-[100] print:hidden">
              <button 
                onClick={() => setShowFilePrompt(true)} 
                disabled={isExporting} 
                className="group flex items-center gap-4 bg-slate-900 text-white px-8 py-5 rounded-full shadow-2xl transition-all hover:scale-110 active:scale-90 disabled:bg-slate-500"
              >
                {isExporting ? <Loader2 className="animate-spin w-6 h-6" /> : <Printer className="w-6 h-6" />}
                <span className="font-black uppercase tracking-widest text-sm">
                  {isExporting ? 'Attendere...' : 'Scarica Verbale (PDF)'}
                </span>
              </button>
            </div>

            <div className="print:hidden">
              <button onClick={() => setStep(AppStep.PHOTOS)} className="flex items-center gap-2 text-slate-500 font-bold text-xs uppercase hover:text-slate-800 transition-colors">
                <ChevronLeft className="w-4 h-4" /> Torna ai Rilievi
              </button>
            </div>

            <div 
              id="final-report" 
              className="bg-white p-10 sm:p-20 shadow-2xl rounded-sm print:shadow-none print:p-0 print:border-none"
            >
              <div className="border-b-4 border-[#64a1a4] pb-10 mb-12 flex flex-col md:flex-row justify-between items-start md:items-center gap-8">
