                    <p className="text-sm font-bold text-slate-800 mt-1">{STUDIO_NAME}</p>
                    <p className="text-[11px] text-slate-400 italic font-medium">{STUDIO_TAGLINE}</p>
                  </div>
                </div>
                <div className="md:text-right">
                  <h1 className="text-4xl font-black text-slate-900 leading-none tracking-tight">VERBALE DI SOPRALLUOGO</h1>
                  <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mt-3">Documento Tecnico Certificato</p>
                </div>
              </div>

              <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6 mb-16">
                <div className="bg-slate-50 p-8 rounded-3xl border border-slate-100">
