                        adjustTextareaHeight(e.target);
                      }}
                      onFocus={(e) => adjustTextareaHeight(e.target)}
                      rows={1}
                    />
                    <div className="print-mirror bg-slate-900 p-10 sm:p-14 rounded-[3rem] text-white text-xl font-light italic">
                      {summary}
                    </div>
                  </div>
                )}
              </div>

              <div className="space-y-32">
                {data.photos.map((photo, idx) => (
                  <div key={photo.id} className="break-inside-avoid">
                    <div className="flex flex-col sm:flex-row sm:items-end justify-between mb-8 border-b-2 border-slate-100 pb-6 gap-4">
                      <div className="flex items-center gap-6">
                        <span className="bg-[#64a1a4] text-white w-12 h-12 rounded-2xl flex items-center justify-center font-black text-xl shadow-lg" style={{ backgroundColor: PRIMARY_COLOR }}>{idx + 1}</span>
                        <div>
                          <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Rilievo Tecnico</p>
                          <h4 className="text-2xl font-black uppercase text-slate-800 italic tracking-tight">{photo.category}</h4>
                        </div>
                      </div>
                      <div className="sm:text-right">
                        <span className="text-[9px] font-black text-slate-400 uppercase">Ditta Incaricata</span>
                        <p className="text-lg font-black text-slate-800 uppercase leading-none mt-1">{photo.supplier || "Da definire"}</p>
                      </div>
                    </div>

                    <div className="grid grid-cols-1 md:grid-cols-2 gap-12 items-start">
                      <div className="rounded-[2.5rem] overflow-hidden shadow-2xl border-8 border-white bg-slate-100 aspect-[4/3]">
                        <img src={photo.url} alt={`Dettaglio ${idx+1}`} className="w-full h-full object-cover" />
                      </div>
                      <div className="flex flex-col h-full">
                        <h5 className="text-[10px] font-black text-[#64a1a4] uppercase tracking-widest flex items-center gap-2 mb-6">
                          <AlertCircle className="w-3 h-3" /> Analisi Diagnostica
                        </h5>
                        <textarea 
                          className="edit-area w-full bg-slate-50 p-10 rounded-[3rem] border-2 border-slate-100 text-slate-800 text-xl font-bold italic leading-relaxed resize-none outline-none focus:bg-white focus:border-[#64a1a4]/50 transition-all overflow-hidden"
                          value={photo.aiPolishedIssue || photo.issue}
                          onChange={(e) => {
                            updatePhoto(photo.id, { aiPolishedIssue: e.target.value, issue: e.target.value });
                            adjustTextareaHeight(e.target);
                          }}
                          onFocus={(e) => adjustTextareaHeight(e.target)}
                          rows={1}
                        />
                        <div className="print-mirror bg-slate-50 p-10 rounded-[3rem] border-2 border-slate-100 text-slate-800 text-xl font-bold italic">
                          {photo.aiPolishedIssue || photo.issue}
                        </div>
                      </div>
                    </div>
                  </div>
                ))}
              </div>

              <div className="mt-48 pt-20 border-t-2 border-slate-900 flex flex-col sm:flex-row justify-between items-end break-inside-avoid gap-12">
                <div className="max-w-md">
                  <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-4">Emesso da:</p>
                  <p className="text-lg font-black text-slate-900 uppercase leading-tight">{STUDIO_NAME}</p>
                  <p className="text-xs font-medium text-slate-400 mt-1 italic">Riferimento File/URL: {customFileName}</p>
                </div>
                <div className="text-center w-full sm:w-80">
                  <div className="h-0.5 bg-slate-200 w-full mb-6"></div>
                  <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest text-center">Timbro e Firma del Professionista</p>
                </div>
              </div>

              <div className="mt-20 text-[9px] text-slate-300 font-bold uppercase tracking-[0.2em] text-center print:block hidden">
                Verbale generato digitalmente tramite CondoInspect Pro. Posizione: {customFileName} - Data: {new Date().toLocaleDateString('it-IT')}.
              </div>
            </div>
          </div>
        )}
      </main>
    </div>
  );
};

export default App;

import React, { useState, useMemo, useEffect, useCallback } from 'react';
import { 
  Camera, 
  Trash2, 
  ChevronRight, 
  ChevronLeft, 
  FileText, 
  Wand2,
  Image as ImageIcon,
  Loader2,
  Sparkles,
  Briefcase,
  Check,
  FileDown,
  Edit3,
  AlertCircle,
  X,
  Link as LinkIcon,
  Download,
  Info
} from 'lucide-react';
import { AppStep, InspectionData, InspectionPhoto } from './types';
import { professionalizeDescription, generateExecutiveSummary } from './services/geminiService';

const DEFAULT_CATEGORIES = ['Strutturale', 'Impianto Idraulico', 'Impianto Elettrico', 'Estetica/Facciata', 'Aree Comuni', 'Sicurezza'];
const STUDIO_NAME = "Studio Amministrazioni Condominiali Ing. Serra";
const STUDIO_TAGLINE = "il condominio trasparente: tutto limpido, tutto evidente";
const PRIMARY_COLOR = "#64a1a4";

const App: React.FC = () => {
  const [step, setStep] = useState<AppStep>(AppStep.SETUP);
  const [isExporting, setIsExporting] = useState(false);
  const [showFilePrompt, setShowFilePrompt] = useState(false);
  const [customFileName, setCustomFileName] = useState('');

  const [data, setData] = useState<InspectionData>({
    condoName: '',
    inspectionDate: new Date().toISOString().split('T')[0],
    logoUrl: undefined,
    technicalNotes: 'Sopralluogo effettuato per verifica stato conservativo generale dell\'immobile e delle pertinenze comuni.',
    photos: [],
    availableCategories: DEFAULT_CATEGORIES
  });

  const [summary, setSummary] = useState('');
  const [isGeneratingSummary, setIsGeneratingSummary] = useState(false);

  const isSetupValid = useMemo(() => {
    return data.condoName.trim().length > 0 && data.inspectionDate.length > 0;
  }, [data.condoName, data.inspectionDate]);

  useEffect(() => {
    if (data.condoName && !customFileName) {
      const sanitized = data.condoName.replace(/[^a-z0-9]/gi, '_').toLowerCase();
      setCustomFileName(`report_${sanitized}_${data.inspectionDate}`);
    }
  }, [data.condoName, data.inspectionDate]);

  const adjustTextareaHeight = (target: HTMLTextAreaElement | null) => {
    if (!target) return;
    target.style.height = 'auto';
    target.style.height = `${target.scrollHeight}px`;
  };

  const fileToBase64 = (file: File): Promise<string> => {
    return new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.readAsDataURL(file);
      reader.onload = () => resolve((reader.result as string).split(',')[1]);
      reader.onerror = error => reject(error);
    });
  };

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files) {
      const newFiles = Array.from(e.target.files) as File[];
      const newPhotosPromises = newFiles.map(async (file) => {
        const base64 = await fileToBase64(file);
        return {
          id: Math.random().toString(36).substr(2, 9),
          url: URL.createObjectURL(file),
          base64Data: base64,
          mimeType: file.type,
          issue: '',
          supplier: '',
          category: data.availableCategories[0],
        };
      });
      const newPhotos = await Promise.all(newPhotosPromises);
      setData(prev => ({ ...prev, photos: [...prev.photos, ...newPhotos] }));
    }
  };

  const handleLogoChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files?.[0]) {
      const url = URL.createObjectURL(e.target.files[0]);
      setData(prev => ({ ...prev, logoUrl: url }));
    }
  };

  const updatePhoto = (id: string, updates: Partial<InspectionPhoto>) => {
    setData(prev => ({
      ...prev,
      photos: prev.photos.map(p => p.id === id ? { ...p, ...updates } : p)
    }));
  };

  const removePhoto = (id: string) => {
    setData(prev => ({
      ...prev,
      photos: prev.photos.filter(p => p.id !== id)
    }));
  };

  const handleAIEnhance = async (photo: InspectionPhoto) => {
    updatePhoto(photo.id, { isLoading: true, aiPolishedIssue: undefined });
    const polished = await professionalizeDescription(photo.issue, photo.base64Data, photo.mimeType);
    updatePhoto(photo.id, { aiPolishedIssue: polished, isLoading: false });
  };

  const handleGenerateReport = async () => {
    setStep(AppStep.REPORT);
    setIsGeneratingSummary(true);
    const issues = data.photos.map(p => p.aiPolishedIssue || p.issue).filter(Boolean);
    const execSummary = await generateExecutiveSummary(data.condoName, issues);
    setSummary(execSummary);
    setIsGeneratingSummary(false);
  };

  const executePrint = useCallback(() => {
    setShowFilePrompt(false);
    setIsExporting(true);

    // Cambiamo il titolo temporaneamente: il browser lo userà come nome del file PDF
    const originalTitle = document.title;
    document.title = customFileName || `Report_${data.condoName}`;

    // Piccolo timeout per chiudere l'interfaccia UI prima di scattare la stampa
    setTimeout(() => {
      window.print();
      document.title = originalTitle;
      setIsExporting(false);
    }, 500);
  }, [customFileName, data.condoName]);

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col">

      {/* MODAL SALVATAGGIO PDF */}
      {showFilePrompt && (
        <div className="fixed inset-0 z-[200] flex items-center justify-center p-4 bg-slate-900/80 backdrop-blur-md animate-in fade-in duration-200">
          <div className="bg-white w-full max-w-lg rounded-[2.5rem] shadow-2xl p-10 space-y-8 animate-in zoom-in-95 duration-200">
            <div className="flex justify-between items-center">
              <div className="bg-slate-50 p-4 rounded-3xl">
                <FileDown className="w-8 h-8 text-[#64a1a4]" />
              </div>
              <button onClick={() => setShowFilePrompt(false)} className="p-2 hover:bg-slate-100 rounded-full transition-colors">
                <X className="w-6 h-6 text-slate-400" />
              </button>
            </div>

            <div className="space-y-2">
              <h2 className="text-3xl font-black text-slate-900 tracking-tight">Salvataggio Verbale</h2>
              <p className="text-slate-500 font-medium">Specifica il nome del file e l'identificativo URL per l'archiviazione digitale.</p>
            </div>

            <div className="space-y-6">
              <div className="space-y-2">
                <label className="text-[10px] font-black uppercase tracking-widest text-[#64a1a4] ml-1">Nome File / Posizione URL</label>
                <div className="relative">
                  <LinkIcon className="absolute left-5 top-1/2 -translate-y-1/2 w-5 h-5 text-slate-300" />
                  <input 
                    autoFocus
                    type="text" 
                    className="w-full bg-slate-50 border-2 border-slate-100 rounded-2xl pl-14 pr-6 py-5 outline-none focus:border-[#64a1a4] focus:ring-4 focus:ring-[#64a1a4]/10 transition-all font-black text-slate-800"
                    value={customFileName}
                    onChange={(e) => setCustomFileName(e.target.value)}
                  />
                </div>
              </div>

              <div className="bg-blue-50 p-6 rounded-3xl flex items-start gap-4 border border-blue-100">
                <Info className="w-6 h-6 text-blue-500 shrink-0 mt-0.5" />
                <p className="text-xs text-blue-700 leading-relaxed font-medium">
                  <strong>Nota Tecnica:</strong> Il browser aprirà la finestra di stampa. Per salvare fisicamente il file, seleziona <strong>"Salva come PDF"</strong> come destinazione. Il file verrà creato nella cartella dei tuoi download.
                </p>
              </div>
            </div>

            <button 
              onClick={executePrint}
              className="w-full bg-slate-900 text-white font-black py-6 rounded-2xl shadow-xl hover:bg-black transition-all active:scale-95 flex items-center justify-center gap-4 text-lg"
            >
              Conferma e Scarica PDF <Download className="w-6 h-6" />
            </button>
          </div>
        </div>
      )}

      {/* HEADER WEB */}
      <header className="bg-white border-b border-slate-200 sticky top-0 z-50 px-4 py-4 print:hidden">
        <div className="max-w-4xl mx-auto flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="p-2.5 rounded-xl shadow-sm" style={{ backgroundColor: PRIMARY_COLOR }}>
              <Briefcase className="text-white w-5 h-5" />
            </div>
            <div>
              <h1 className="text-base font-black text-slate-800 leading-none">Studio Ing. Serra</h1>
              <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest mt-1 italic">CondoInspect Pro</p>
            </div>
          </div>
          <div className="flex items-center gap-4">
             <span className="text-[10px] font-bold uppercase tracking-widest text-slate-400">
               {step === AppStep.SETUP ? '01 Setup' : step === AppStep.PHOTOS ? '02 Rilievi' : '03 Report'}
             </span>
          </div>
        </div>
      </header>

      {/* CONTENUTO PRINCIPALE */}
      <main className="flex-1 max-w-4xl mx-auto w-full p-4 sm:p-6 pb-32 print:p-0 print:max-w-none">

        {/* STEP 1: SETUP */}
        {step === AppStep.SETUP && (
          <div className="bg-white rounded-[2.5rem] shadow-sm border border-slate-200 p-8 sm:p-12 animate-in fade-in duration-500">
            <div className="flex flex-col sm:flex-row items-center justify-between mb-12 pb-8 border-b border-slate-100 gap-8">
              <div className="text-center sm:text-left">
                <h2 className="text-4xl font-black italic tracking-tighter" style={{ color: PRIMARY_COLOR }}>STUDIO SERRA</h2>
                <p className="text-sm font-bold text-slate-500 uppercase tracking-widest mt-1">{STUDIO_NAME}</p>
                <p className="text-xs text-slate-400 italic mt-1">{STUDIO_TAGLINE}</p>
              </div>
              {data.logoUrl && (
                <div className="w-24 h-24 rounded-3xl border-2 border-slate-100 p-2 bg-white shadow-sm">
                  <img src={data.logoUrl} className="w-full h-full object-contain" alt="Logo" />
                </div>
              )}
            </div>

            <div className="space-y-10">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                <div className="space-y-2">
                  <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest ml-1">Condominio *</label>
                  <input type="text" className="w-full px-6 py-5 bg-slate-50 border-2 border-slate-50 rounded-2xl focus:border-[#64a1a4] outline-none font-bold text-slate-800 transition-all shadow-inner" value={data.condoName} onChange={(e) => setData({...data, condoName: e.target.value})} placeholder="es. Condominio Giardini" />
                </div>
                <div className="space-y-2">
                  <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest ml-1">Data Ispezione *</label>
                  <input type="date" className="w-full px-6 py-5 bg-slate-50 border-2 border-slate-50 rounded-2xl focus:border-[#64a1a4] outline-none font-bold text-slate-800 transition-all shadow-inner" value={data.inspectionDate} onChange={(e) => setData({...data, inspectionDate: e.target.value})} />
                </div>
              </div>

              <div className="space-y-2">
                <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest ml-1">Logo Studio</label>
                <label className="border-2 border-dashed border-slate-200 rounded-3xl p-10 flex flex-col items-center justify-center gap-4 cursor-pointer hover:bg-slate-50 transition-all group">
                  <div className="bg-slate-50 p-4 rounded-2xl group-hover:scale-110 transition-transform"><ImageIcon className="w-8 h-8 text-slate-300" /></div>
                  <span className="text-sm font-black text-slate-400 uppercase tracking-widest">{data.logoUrl ? "Cambia Logo" : "Trascina il logo qui"}</span>
                  <input type="file" accept="image/*" className="hidden" onChange={handleLogoChange} />
                </label>
              </div>

              <div className="space-y-2">
                <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest ml-1">Premessa Tecnica</label>
                <textarea className="w-full px-6 py-5 bg-slate-50 border-2 border-slate-50 rounded-2xl focus:border-[#64a1a4] outline-none min-h-[120px] resize-none font-medium text-slate-700 shadow-inner" value={data.technicalNotes} onChange={(e) => setData({...data, technicalNotes: e.target.value})} />
              </div>
            </div>

            <div className="mt-14">
              <button disabled={!isSetupValid} onClick={() => setStep(AppStep.PHOTOS)} className="w-full text-white font-black py-6 rounded-2xl shadow-xl flex items-center justify-center gap-4 uppercase tracking-[0.2em] text-sm transition-all hover:brightness-110 active:scale-95" style={{ backgroundColor: isSetupValid ? PRIMARY_COLOR : "#cbd5e1" }}>
                Prosegui ai Rilievi <ChevronRight className="w-6 h-6" />
              </button>
            </div>
          </div>
        )}

        {/* STEP 2: PHOTOS */}
        {step === AppStep.PHOTOS && (
          <div className="space-y-8 animate-in slide-in-from-bottom-6">
            <div className="flex items-center justify-between bg-white p-5 rounded-3xl border border-slate-200 sticky top-20 z-40 print:hidden shadow-md">
              <button onClick={() => setStep(AppStep.SETUP)} className="text-slate-400 hover:text-slate-900 font-black text-[10px] uppercase tracking-widest flex items-center gap-2 transition-colors">
                <ChevronLeft className="w-5 h-5" /> Indietro
              </button>
              <label className="flex items-center gap-3 text-white px-8 py-3.5 rounded-2xl cursor-pointer shadow-lg font-black text-xs uppercase tracking-widest transition-all hover:scale-105 active:scale-95" style={{ backgroundColor: PRIMARY_COLOR }}>
                <Camera className="w-5 h-5" /> Aggiungi Rilievo
                <input type="file" multiple accept="image/*" className="hidden" onChange={handleFileChange} />
              </label>
            </div>

            <div className="space-y-8">
              {data.photos.length === 0 ? (
                <div className="bg-white border-4 border-dashed border-slate-100 rounded-[3rem] p-24 flex flex-col items-center gap-6 text-center">
                  <div className="bg-slate-50 p-6 rounded-full"><ImageIcon className="w-16 h-16 text-slate-200" /></div>
                  <p className="font-black text-slate-300 uppercase tracking-widest text-sm">Nessuna foto caricata</p>
                </div>
              ) : (
                data.photos.map((photo) => (
                  <div key={photo.id} className="bg-white rounded-[2.5rem] shadow-sm border border-slate-200 overflow-hidden flex flex-col group transition-all hover:shadow-xl">
                    <div className="flex flex-col md:flex-row h-full">
                      <div className="md:w-2/5 relative bg-slate-100 min-h-[300px]">
                        <img src={photo.url} alt="Rilievo" className="w-full h-full object-cover" />
                        <button onClick={() => removePhoto(photo.id)} className="absolute top-5 right-5 p-3 bg-red-500 text-white rounded-2xl shadow-xl opacity-0 group-hover:opacity-100 transition-opacity"><Trash2 className="w-5 h-5" /></button>
                      </div>
                      <div className="flex-1 p-8 space-y-6">
                        <div className="grid grid-cols-2 gap-6">
                          <div className="space-y-1.5">
                            <label className="text-[9px] font-black uppercase text-slate-400 tracking-widest">Macro-Area</label>
                            <select className="w-full p-3 bg-slate-50 border-2 border-slate-50 rounded-xl text-xs font-black uppercase tracking-tight" value={photo.category} onChange={(e) => updatePhoto(photo.id, { category: e.target.value })}>
                              {data.availableCategories.map(cat => <option key={cat} value={cat}>{cat}</option>)}
                            </select>
                          </div>
                          <div className="space-y-1.5">
                            <label className="text-[9px] font-black uppercase text-slate-400 tracking-widest">Ditta di Rif.</label>
                            <input type="text" placeholder="..." className="w-full p-3 bg-slate-50 border-2 border-slate-50 rounded-xl text-xs font-bold" value={photo.supplier} onChange={(e) => updatePhoto(photo.id, { supplier: e.target.value })} />
                          </div>
                        </div>
                        <div className="space-y-1.5">
                          <label className="text-[9px] font-black uppercase text-slate-400 tracking-widest">Evidenze Tecniche</label>
                          <div className="relative">
                            <textarea placeholder="Descrivi l'anomalia riscontrata..." className="w-full p-5 bg-slate-50 border-2 border-slate-50 rounded-2xl text-sm font-medium min-h-[140px] resize-none outline-none focus:border-[#64a1a4] transition-all" value={photo.issue} onChange={(e) => updatePhoto(photo.id, { issue: e.target.value })} />
                            <button onClick={() => handleAIEnhance(photo)} disabled={photo.isLoading} className="absolute bottom-4 right-4 p-3 bg-white border border-slate-200 rounded-2xl shadow-lg hover:bg-slate-50 transition-all disabled:opacity-50" style={{ color: PRIMARY_COLOR }}>
                              {photo.isLoading ? <Loader2 className="animate-spin h-5 w-5" /> : <Wand2 className="w-5 h-5" />}
                            </button>
                          </div>
                        </div>
                      </div>
                    </div>
                    {photo.aiPolishedIssue && (
                      <div className="p-8 bg-slate-900 border-t border-slate-800 animate-in fade-in slide-in-from-top-4">
                        <div className="flex items-center justify-between mb-4">
                          <p className="text-[10px] font-black text-[#64a1a4] uppercase tracking-[0.2em] flex items-center gap-2"><Sparkles className="w-3 h-3" /> Analisi Professionale IA</p>
                          <button onClick={() => updatePhoto(photo.id, { issue: photo.aiPolishedIssue, aiPolishedIssue: undefined })} className="text-[10px] font-black text-white bg-[#64a1a4] px-4 py-2 rounded-lg hover:scale-105 transition-transform uppercase tracking-widest">Applica Analisi</button>
                        </div>
                        <p className="text-sm italic font-medium text-slate-300 leading-relaxed">{photo.aiPolishedIssue}</p>
                      </div>
                    )}
                  </div>
                ))
              )}
            </div>

            <div className="pt-16">
              <button disabled={data.photos.length === 0} onClick={handleGenerateReport} className="w-full bg-slate-900 text-white font-black py-7 rounded-[2rem] shadow-2xl flex items-center justify-center gap-4 uppercase tracking-[0.25em] text-sm transition-all hover:bg-black hover:scale-[1.02]">
                Concludi e Genera Report <FileText className="w-6 h-6" />
              </button>
            </div>
          </div>
        )}

        {/* STEP 3: REPORT FINALE */}
        {step === AppStep.REPORT && (
          <div className="space-y-12 animate-in fade-in duration-700 print:p-0 relative">

            {/* TASTO SALVATAGGIO PDF (Rifatto) */}
            <div className="fixed bottom-10 right-1/2 translate-x-1/2 sm:right-10 sm:translate-x-0 z-[100] print:hidden w-full max-w-xs px-4">
              <button 
                onClick={() => setShowFilePrompt(true)} 
                disabled={isExporting} 
                className="w-full group flex items-center justify-center gap-4 bg-slate-900 text-white p-6 rounded-full shadow-[0_20px_50px_rgba(0,0,0,0.3)] transition-all hover:scale-110 active:scale-95 disabled:bg-slate-400"
              >
                {isExporting ? <Loader2 className="animate-spin w-7 h-7" /> : <Download className="w-7 h-7" />}
                <div className="text-left">
                  <span className="block font-black uppercase tracking-widest text-xs">Salva Report</span>
                  <span className="block text-[10px] font-bold text-[#64a1a4] uppercase">Esporta in PDF Professionale</span>
                </div>
              </button>
            </div>

            <div className="print:hidden">
              <button onClick={() => setStep(AppStep.PHOTOS)} className="flex items-center gap-2 text-slate-500 font-black text-[10px] uppercase tracking-widest hover:text-slate-800 transition-colors">
                <ChevronLeft className="w-5 h-5" /> Modifica Rilievi
              </button>
            </div>

            {/* AREA REPORT PDF */}
            <div id="final-report" className="bg-white p-10 sm:p-20 shadow-2xl rounded-sm print:shadow-none print:p-0 print:border-none">

              <div className="border-b-8 border-[#64a1a4] pb-12 mb-16 flex flex-col md:flex-row justify-between items-start md:items-center gap-12">
                <div className="flex items-center gap-10">
                  {data.logoUrl && <img src={data.logoUrl} alt="Logo" className="h-28 w-auto object-contain" />}
                  <div>
                    <h2 className="text-4xl font-black italic uppercase tracking-tighter" style={{ color: PRIMARY_COLOR }}>STUDIO SERRA</h2>
                    <p className="text-base font-bold text-slate-800 mt-1">{STUDIO_NAME}</p>
                    <p className="text-xs text-slate-400 italic font-medium">{STUDIO_TAGLINE}</p>
                  </div>
                </div>
                <div className="md:text-right">
                  <h1 className="text-5xl font-black text-slate-900 tracking-tighter leading-none">VERBALE</h1>
                  <p className="text-[12px] font-black text-slate-400 uppercase tracking-[0.4em] mt-4">Sopralluogo Tecnico</p>
                </div>
              </div>

              <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-8 mb-20">
                <div className="bg-slate-50 p-10 rounded-[2.5rem] border-2 border-slate-50">
                  <h3 className="text-[11px] font-black text-[#64a1a4] uppercase tracking-widest mb-2">Immobile</h3>
                  <p className="text-2xl font-black text-slate-900 tracking-tight">{data.condoName}</p>
                </div>
                <div className="bg-slate-50 p-10 rounded-[2.5rem] border-2 border-slate-50">
                  <h3 className="text-[11px] font-black text-[#64a1a4] uppercase tracking-widest mb-2">Eseguito il</h3>
                  <p className="text-2xl font-black text-slate-900 tracking-tight">{new Date(data.inspectionDate).toLocaleDateString('it-IT', { day: 'numeric', month: 'long', year: 'numeric' })}</p>
                </div>
                <div className="bg-slate-50 p-10 rounded-[2.5rem] border-2 border-slate-50">
                  <h3 className="text-[11px] font-black text-[#64a1a4] uppercase tracking-widest mb-2">Rif. Pratica</h3>
                  <p className="text-2xl font-black text-slate-900 tracking-tight italic">#{Math.floor(Math.random() * 9000) + 1000}</p>
                </div>
              </div>

              {/* RELAZIONE EDITABILE LIVE */}
              <div className="mb-24">
                <div className="flex items-center gap-4 mb-8">
                  <div className="h-1.5 w-16 bg-[#64a1a4]" />
                  <h3 className="text-sm font-black uppercase tracking-[0.3em] text-[#64a1a4]">Sintesi Professionale Direzionale</h3>
                </div>

                {isGeneratingSummary ? (
                   <div className="flex items-center gap-6 p-16 bg-slate-50 rounded-[4rem] border-4 border-dashed border-slate-100">
                     <Loader2 className="animate-spin w-8 h-8 text-[#64a1a4]" />
                     <p className="text-[#64a1a4] italic text-xl animate-pulse font-black uppercase tracking-widest">IA in elaborazione...</p>
                   </div>
                ) : (
                  <div className="relative">
                    <textarea 
                      className="edit-area w-full bg-slate-900 p-12 sm:p-16 rounded-[4rem] text-white text-2xl font-light italic leading-relaxed whitespace-pre-wrap outline-none border-none resize-none overflow-hidden focus:ring-4 focus:ring-[#64a1a4]/20 transition-all"
                      value={summary}
                      onChange={(e) => {
                        setSummary(e.target.value);
                        adjustTextareaHeight(e.target);
                      }}
                      onFocus={(e) => adjustTextareaHeight(e.target)}
                      rows={1}
                    />
                    <div className="print-mirror bg-slate-900 p-12 sm:p-16 rounded-[4rem] text-white text-2xl font-light italic">
                      {summary}
                    </div>
                  </div>
                )}
              </div>

              {/* DETTAGLIO RILIEVI */}
              <div className="space-y-40">
                {data.photos.map((photo, idx) => (
                  <div key={photo.id} className="break-inside-avoid pt-12 border-t-2 border-slate-50">
                    <div className="flex flex-col sm:flex-row sm:items-end justify-between mb-12 gap-6">
                      <div className="flex items-center gap-10">
                        <span className="bg-[#64a1a4] text-white w-16 h-16 rounded-3xl flex items-center justify-center font-black text-3xl shadow-2xl tracking-tighter">{idx + 1}</span>
                        <div>
                          <p className="text-[11px] font-black text-slate-300 uppercase tracking-[0.3em] mb-2">Area di Intervento</p>
                          <h4 className="text-4xl font-black uppercase text-slate-800 tracking-tighter italic">{photo.category}</h4>
                        </div>
                      </div>
                      <div className="sm:text-right">
                        <span className="text-[10px] font-black text-slate-300 uppercase tracking-widest">Incarico proposto a</span>
                        <p className="text-2xl font-black text-slate-800 uppercase leading-none mt-2">{photo.supplier || "Ditta da designare"}</p>
                      </div>
                    </div>

                    <div className="grid grid-cols-1 md:grid-cols-2 gap-16 items-start">
                      <div className="rounded-[3rem] overflow-hidden shadow-[0_30px_60px_-15px_rgba(0,0,0,0.3)] border-[12px] border-white bg-slate-100 aspect-[4/3]">
                        <img src={photo.url} alt={`Rilievo ${idx+1}`} className="w-full h-full object-cover" />
                      </div>
                      <div className="flex flex-col h-full py-4">
                        <h5 className="text-[11px] font-black text-[#64a1a4] uppercase tracking-[0.3em] flex items-center gap-3 mb-8">
                          <AlertCircle className="w-4 h-4" /> Diagnosi dello Stato di Fatto
                        </h5>
                        <textarea 
                          className="edit-area w-full bg-slate-50 p-12 rounded-[3.5rem] border-2 border-slate-100 text-slate-800 text-2xl font-bold italic leading-relaxed resize-none outline-none focus:bg-white focus:border-[#64a1a4]/50 transition-all overflow-hidden"
                          value={photo.aiPolishedIssue || photo.issue}
                          onChange={(e) => {
                            updatePhoto(photo.id, { aiPolishedIssue: e.target.value, issue: e.target.value });
                            adjustTextareaHeight(e.target);
                          }}
                          onFocus={(e) => adjustTextareaHeight(e.target)}
                          rows={1}
                        />
                        <div className="print-mirror bg-slate-50 p-12 rounded-[3.5rem] border-2 border-slate-100 text-slate-800 text-2xl font-bold italic">
                          {photo.aiPolishedIssue || photo.issue}
                        </div>
                      </div>
                    </div>
                  </div>
                ))}
              </div>

              {/* FIRME */}
              <div className="mt-60 pt-20 border-t-4 border-slate-900 flex flex-col sm:flex-row justify-between items-end break-inside-avoid gap-16">
                <div className="max-w-xl">
                  <p className="text-[12px] font-black text-slate-300 uppercase tracking-[0.4em] mb-6">Validazione Documentale:</p>
                  <p className="text-2xl font-black text-slate-900 uppercase leading-tight tracking-tighter">{STUDIO_NAME}</p>
                  <p className="text-sm font-medium text-slate-400 mt-2 italic">Ref. File: {customFileName}</p>
                </div>
                <div className="text-center w-full sm:w-96">
                  <div className="h-0.5 bg-slate-200 w-full mb-8"></div>
                  <p className="text-[12px] font-black text-slate-300 uppercase tracking-widest">Timbro e Sottoscrizione</p>
                </div>
              </div>

              <div className="mt-24 text-[10px] text-slate-200 font-black uppercase tracking-[0.5em] text-center print:block hidden">
                CondoInspect Pro • Studio Serra • Generato il {new Date().toLocaleDateString('it-IT')}
              </div>
            </div>
          </div>
        )}
      </main>
    </div>
  );
};

export default App;

import React, { useState, useMemo, useEffect, useCallback } from 'react';
import { 
  Camera, 
  Trash2, 
  ChevronRight, 
  ChevronLeft, 
  FileText, 
  Wand2,
  Image as ImageIcon,
  Loader2,
  Sparkles,
  Briefcase,
  Check,
  FileDown,
  AlertCircle,
  X,
  Link as LinkIcon,
  Download,
  Info,
  ShieldCheck
} from 'lucide-react';
import { AppStep, InspectionData, InspectionPhoto } from './types';
import { professionalizeDescription, generateExecutiveSummary } from './services/geminiService';

const DEFAULT_CATEGORIES = ['Strutturale', 'Impianto Idraulico', 'Impianto Elettrico', 'Estetica/Facciata', 'Aree Comuni', 'Sicurezza'];
const STUDIO_NAME = "Studio Amministrazioni Condominiali Ing. Serra";
const STUDIO_TAGLINE = "il condominio trasparente: tutto limpido, tutto evidente";
const PRIMARY_COLOR = "#64a1a4";

declare var html2pdf: any;

const App: React.FC = () => {
  const [step, setStep] = useState<AppStep>(AppStep.SETUP);
  const [isExporting, setIsExporting] = useState(false);
  const [showFilePrompt, setShowFilePrompt] = useState(false);
  const [customFileName, setCustomFileName] = useState('');

  const [data, setData] = useState<InspectionData>({
    condoName: '',
    inspectionDate: new Date().toISOString().split('T')[0],
    logoUrl: undefined,
    technicalNotes: 'Sopralluogo effettuato per verifica stato conservativo generale dell\'immobile e delle pertinenze comuni.',
    photos: [],
    availableCategories: DEFAULT_CATEGORIES
  });

  const [summary, setSummary] = useState('');
  const [isGeneratingSummary, setIsGeneratingSummary] = useState(false);

  const isSetupValid = useMemo(() => {
    return data.condoName.trim().length > 0 && data.inspectionDate.length > 0;
  }, [data.condoName, data.inspectionDate]);

  useEffect(() => {
    if (data.condoName && !customFileName) {
      const sanitized = data.condoName.replace(/[^a-z0-9]/gi, '_').toLowerCase();
      setCustomFileName(`report_${sanitized}_${data.inspectionDate}`);
    }
  }, [data.condoName, data.inspectionDate]);

  const adjustTextareaHeight = (target: HTMLTextAreaElement | null) => {
    if (!target) return;
    target.style.height = 'auto';
    target.style.height = `${target.scrollHeight}px`;
  };

  const fileToBase64 = (file: File): Promise<string> => {
    return new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.readAsDataURL(file);
      reader.onload = () => resolve((reader.result as string).split(',')[1]);
      reader.onerror = error => reject(error);
    });
  };

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files) {
      const newFiles = Array.from(e.target.files) as File[];
      const newPhotosPromises = newFiles.map(async (file) => {
        const base64 = await fileToBase64(file);
        return {
          id: Math.random().toString(36).substr(2, 9),
          url: URL.createObjectURL(file),
          base64Data: base64,
          mimeType: file.type,
          issue: '',
          supplier: '',
          category: data.availableCategories[0],
        };
      });
      const newPhotos = await Promise.all(newPhotosPromises);
      setData(prev => ({ ...prev, photos: [...prev.photos, ...newPhotos] }));
    }
  };

  const handleLogoChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files?.[0]) {
      const url = URL.createObjectURL(e.target.files[0]);
      setData(prev => ({ ...prev, logoUrl: url }));
    }
  };

  const updatePhoto = (id: string, updates: Partial<InspectionPhoto>) => {
    setData(prev => ({
      ...prev,
      photos: prev.photos.map(p => p.id === id ? { ...p, ...updates } : p)
    }));
  };

  const removePhoto = (id: string) => {
    setData(prev => ({
      ...prev,
      photos: prev.photos.filter(p => p.id !== id)
    }));
  };

  const handleAIEnhance = async (photo: InspectionPhoto) => {
    updatePhoto(photo.id, { isLoading: true, aiPolishedIssue: undefined });
    const polished = await professionalizeDescription(photo.issue, photo.base64Data, photo.mimeType);
    updatePhoto(photo.id, { aiPolishedIssue: polished, isLoading: false });
  };

  const handleGenerateReport = async () => {
    setStep(AppStep.REPORT);
    setIsGeneratingSummary(true);
    const issues = data.photos.map(p => p.aiPolishedIssue || p.issue).filter(Boolean);
    const execSummary = await generateExecutiveSummary(data.condoName, issues);
    setSummary(execSummary);
    setIsGeneratingSummary(false);
  };

  // FUNZIONE DI SALVATAGGIO PDF DIRETTO
  const executeSavePdf = useCallback(() => {
    const element = document.getElementById('final-report');
    if (!element) return;

    setShowFilePrompt(false);
    setIsExporting(true);

    const opt = {
      margin: 10,
      filename: `${customFileName || 'report'}.pdf`,
      image: { type: 'jpeg', quality: 0.98 },
      html2canvas: { 
        scale: 2, 
        useCORS: true, 
        letterRendering: true,
        logging: false
      },
      jsPDF: { unit: 'mm', format: 'a4', orientation: 'portrait' },
      pagebreak: { mode: ['avoid-all', 'css', 'legacy'] }
    };

    // Nascondiamo gli elementi web (textarea) e mostriamo i mirror prima di scattare
    const textareas = element.querySelectorAll('.edit-area');
    const mirrors = element.querySelectorAll('.print-mirror');
    textareas.forEach((el: any) => el.style.display = 'none');
    mirrors.forEach((el: any) => el.style.display = 'block');

    html2pdf().set(opt).from(element).save().then(() => {
      setIsExporting(false);
      // Ripristiniamo la visualizzazione web
      textareas.forEach((el: any) => el.style.display = 'block');
      mirrors.forEach((el: any) => el.style.display = 'none');
    }).catch((err: any) => {
      console.error("PDF Export Error:", err);
      alert("Errore durante il salvataggio del PDF. Riprova.");
      setIsExporting(false);
    });
  }, [customFileName]);

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col">

      {/* OVERLAY GENERAZIONE IN CORSO */}
      {isExporting && (
        <div className="fixed inset-0 z-[300] bg-slate-900/90 backdrop-blur-md flex flex-col items-center justify-center p-8 text-center animate-in fade-in duration-300">
          <div className="spinner-ring mb-8"></div>
          <h2 className="text-2xl font-black text-white mb-2 uppercase tracking-widest">Generazione PDF in corso</h2>
          <p className="text-slate-400 font-medium max-w-xs">Stiamo assemblando le foto e le analisi dell'IA. Il download partirà automaticamente tra pochi istanti.</p>
        </div>
      )}

      {/* MODAL SALVATAGGIO PDF */}
      {showFilePrompt && (
        <div className="fixed inset-0 z-[200] flex items-center justify-center p-4 bg-slate-900/80 backdrop-blur-md animate-in fade-in duration-200">
          <div className="bg-white w-full max-w-lg rounded-[2.5rem] shadow-2xl p-10 space-y-8 animate-in zoom-in-95 duration-200">
            <div className="flex justify-between items-center">
              <div className="bg-slate-50 p-4 rounded-3xl">
                <FileDown className="w-8 h-8 text-[#64a1a4]" />
              </div>
              <button onClick={() => setShowFilePrompt(false)} className="p-2 hover:bg-slate-100 rounded-full transition-colors">
                <X className="w-6 h-6 text-slate-400" />
              </button>
            </div>

            <div className="space-y-2">
              <h2 className="text-3xl font-black text-slate-900 tracking-tight">Salva Documento</h2>
              <p className="text-slate-500 font-medium text-sm">Inserisci il nome del file e l'URL/Riferimento per l'archiviazione.</p>
            </div>

            <div className="space-y-6">
              <div className="space-y-2">
                <label className="text-[10px] font-black uppercase tracking-widest text-[#64a1a4] ml-1">Nome File / Posizione URL</label>
                <div className="relative">
                  <LinkIcon className="absolute left-5 top-1/2 -translate-y-1/2 w-5 h-5 text-slate-300" />
                  <input 
                    autoFocus
                    type="text" 
                    className="w-full bg-slate-50 border-2 border-slate-100 rounded-2xl pl-14 pr-6 py-5 outline-none focus:border-[#64a1a4] focus:ring-4 focus:ring-[#64a1a4]/10 transition-all font-black text-slate-800"
                    value={customFileName}
                    onChange={(e) => setCustomFileName(e.target.value)}
                  />
                </div>
              </div>

              <div className="bg-emerald-50 p-6 rounded-3xl flex items-start gap-4 border border-emerald-100">
                <ShieldCheck className="w-6 h-6 text-emerald-500 shrink-0 mt-0.5" />
                <p className="text-xs text-emerald-700 leading-relaxed font-medium">
                  <strong>Risolto:</strong> Cliccando il tasto sotto, il file verrà generato e salvato <strong>direttamente</strong> sul tuo dispositivo. Non è necessario selezionare stampanti.
                </p>
              </div>
            </div>

            <button 
              onClick={executeSavePdf}
              className="w-full bg-slate-900 text-white font-black py-6 rounded-2xl shadow-xl hover:bg-black transition-all active:scale-95 flex items-center justify-center gap-4 text-lg"
            >
              SALVA ORA <Download className="w-6 h-6" />
            </button>
          </div>
        </div>
      )}

      {/* HEADER WEB */}
      <header className="bg-white border-b border-slate-200 sticky top-0 z-50 px-4 py-4 print:hidden">
        <div className="max-w-4xl mx-auto flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="p-2.5 rounded-xl shadow-sm" style={{ backgroundColor: PRIMARY_COLOR }}>
              <Briefcase className="text-white w-5 h-5" />
            </div>
            <div>
              <h1 className="text-base font-black text-slate-800 leading-none">Studio Ing. Serra</h1>
              <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest mt-1 italic">CondoInspect Pro</p>
            </div>
          </div>
          <div className="flex items-center gap-4">
             <span className="text-[10px] font-bold uppercase tracking-widest text-slate-400">
               {step === AppStep.SETUP ? '01 Config' : step === AppStep.PHOTOS ? '02 Rilievi' : '03 Report'}
             </span>
          </div>
        </div>
      </header>

      {/* CONTENUTO PRINCIPALE */}
      <main className="flex-1 max-w-4xl mx-auto w-full p-4 sm:p-6 pb-32 print:p-0 print:max-w-none">

        {/* STEP 1: SETUP */}
        {step === AppStep.SETUP && (
          <div className="bg-white rounded-[2.5rem] shadow-sm border border-slate-200 p-8 sm:p-12 animate-in fade-in duration-500">
            <div className="flex flex-col sm:flex-row items-center justify-between mb-12 pb-8 border-b border-slate-100 gap-8">
              <div className="text-center sm:text-left">
                <h2 className="text-4xl font-black italic tracking-tighter" style={{ color: PRIMARY_COLOR }}>STUDIO SERRA</h2>
                <p className="text-sm font-bold text-slate-500 uppercase tracking-widest mt-1">{STUDIO_NAME}</p>
                <p className="text-xs text-slate-400 italic mt-1">{STUDIO_TAGLINE}</p>
              </div>
              {data.logoUrl && (
                <div className="w-24 h-24 rounded-3xl border-2 border-slate-100 p-2 bg-white shadow-sm">
                  <img src={data.logoUrl} className="w-full h-full object-contain" alt="Logo" />
                </div>
              )}
            </div>

            <div className="space-y-10">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                <div className="space-y-2">
                  <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest ml-1">Condominio *</label>
                  <input type="text" className="w-full px-6 py-5 bg-slate-50 border-2 border-slate-50 rounded-2xl focus:border-[#64a1a4] outline-none font-bold text-slate-800 transition-all shadow-inner" value={data.condoName} onChange={(e) => setData({...data, condoName: e.target.value})} placeholder="es. Condominio Marconi" />
                </div>
                <div className="space-y-2">
                  <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest ml-1">Data Ispezione *</label>
                  <input type="date" className="w-full px-6 py-5 bg-slate-50 border-2 border-slate-50 rounded-2xl focus:border-[#64a1a4] outline-none font-bold text-slate-800 transition-all shadow-inner" value={data.inspectionDate} onChange={(e) => setData({...data, inspectionDate: e.target.value})} />
                </div>
              </div>

              <div className="space-y-2">
                <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest ml-1">Logo Professionale</label>
                <label className="border-2 border-dashed border-slate-200 rounded-3xl p-10 flex flex-col items-center justify-center gap-4 cursor-pointer hover:bg-slate-50 transition-all group">
                  <div className="bg-slate-50 p-4 rounded-2xl group-hover:scale-110 transition-transform"><ImageIcon className="w-8 h-8 text-slate-300" /></div>
                  <span className="text-sm font-black text-slate-400 uppercase tracking-widest">{data.logoUrl ? "Cambia Logo" : "Carica Logo Studio"}</span>
                  <input type="file" accept="image/*" className="hidden" onChange={handleLogoChange} />
                </label>
              </div>

              <div className="space-y-2">
                <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest ml-1">Premessa Sopralluogo</label>
                <textarea className="w-full px-6 py-5 bg-slate-50 border-2 border-slate-50 rounded-2xl focus:border-[#64a1a4] outline-none min-h-[120px] resize-none font-medium text-slate-700 shadow-inner" value={data.technicalNotes} onChange={(e) => setData({...data, technicalNotes: e.target.value})} />
              </div>
            </div>

            <div className="mt-14">
              <button disabled={!isSetupValid} onClick={() => setStep(AppStep.PHOTOS)} className="w-full text-white font-black py-6 rounded-2xl shadow-xl flex items-center justify-center gap-4 uppercase tracking-[0.2em] text-sm transition-all hover:brightness-110 active:scale-95" style={{ backgroundColor: isSetupValid ? PRIMARY_COLOR : "#cbd5e1" }}>
                Procedi ai Rilievi <ChevronRight className="w-6 h-6" />
              </button>
            </div>
          </div>
        )}

        {/* STEP 2: PHOTOS */}
        {step === AppStep.PHOTOS && (
          <div className="space-y-8 animate-in slide-in-from-bottom-6">
            <div className="flex items-center justify-between bg-white p-5 rounded-3xl border border-slate-200 sticky top-20 z-40 print:hidden shadow-md">
              <button onClick={() => setStep(AppStep.SETUP)} className="text-slate-400 hover:text-slate-900 font-black text-[10px] uppercase tracking-widest flex items-center gap-2 transition-colors">
                <ChevronLeft className="w-5 h-5" /> Indietro
              </button>
              <label className="flex items-center gap-3 text-white px-8 py-3.5 rounded-2xl cursor-pointer shadow-lg font-black text-xs uppercase tracking-widest transition-all hover:scale-105 active:scale-95" style={{ backgroundColor: PRIMARY_COLOR }}>
                <Camera className="w-5 h-5" /> Nuovo Rilievo
                <input type="file" multiple accept="image/*" className="hidden" onChange={handleFileChange} />
              </label>
            </div>

            <div className="space-y-8">
              {data.photos.length === 0 ? (
                <div className="bg-white border-4 border-dashed border-slate-100 rounded-[3rem] p-24 flex flex-col items-center gap-6 text-center">
                  <div className="bg-slate-50 p-6 rounded-full"><ImageIcon className="w-16 h-16 text-slate-200" /></div>
                  <p className="font-black text-slate-300 uppercase tracking-widest text-sm">Nessuna immagine presente</p>
                </div>
              ) : (
                data.photos.map((photo) => (
                  <div key={photo.id} className="bg-white rounded-[2.5rem] shadow-sm border border-slate-200 overflow-hidden flex flex-col group transition-all hover:shadow-xl">
                    <div className="flex flex-col md:flex-row h-full">
                      <div className="md:w-2/5 relative bg-slate-100 min-h-[300px]">
                        <img src={photo.url} alt="Rilievo" className="w-full h-full object-cover" />
                        <button onClick={() => removePhoto(photo.id)} className="absolute top-5 right-5 p-3 bg-red-500 text-white rounded-2xl shadow-xl opacity-0 group-hover:opacity-100 transition-opacity"><Trash2 className="w-5 h-5" /></button>
                      </div>
                      <div className="flex-1 p-8 space-y-6">
