                      </div>
                      <div className="sm:text-right">
                        <span className="text-[10px] font-black text-slate-300 uppercase tracking-widest">Ditta Manutentrice</span>
                        <p className="text-2xl font-black text-slate-800 uppercase leading-none mt-2">{photo.supplier || "Da definire"}</p>
                      </div>
                    </div>

                    <div className="grid grid-cols-1 md:grid-cols-2 gap-16 items-start">
                      <div className="rounded-[3rem] overflow-hidden shadow-2xl border-[12px] border-white bg-slate-100 aspect-[4/3]">
