                  <p className="text-[12px] font-black text-slate-300 uppercase tracking-[0.4em] mb-6">Validato da:</p>
                  <p className="text-2xl font-black text-slate-900 uppercase leading-tight tracking-tighter">{STUDIO_NAME}</p>
                  <p className="text-sm font-medium text-slate-400 mt-2 italic">Riferimento File/URL: {customFileName}</p>
