};

export default App;

import React, { useState, useMemo, useEffect, useCallback, useRef } from 'react';
import { 
  Camera, 
  Trash2, 
  ChevronRight, 
  ChevronLeft, 
  FileText, 
  Wand2,
  Image as ImageIcon,
  Loader2,
  Sparkles,
  Briefcase,
  Check,
  FileDown,
  AlertCircle,
  X,
  Download,
  Info,
  ShieldCheck,
  FileCheck
} from 'lucide-react';
import { AppStep, InspectionData, InspectionPhoto } from './types';
import { professionalizeDescription, generateExecutiveSummary } from './services/geminiService';

const DEFAULT_CATEGORIES = ['Strutturale', 'Impianto Idraulico', 'Impianto Elettrico', 'Estetica/Facciata', 'Aree Comuni', 'Sicurezza'];
const STUDIO_NAME = "Studio Amministrazioni Condominiali Ing. Serra";
const STUDIO_TAGLINE = "il condominio trasparente: tutto limpido, tutto evidente";
const PRIMARY_COLOR = "#64a1a4";

declare var html2pdf: any;

const App: React.FC = () => {
  const [step, setStep] = useState<AppStep>(AppStep.SETUP);
  const [isExporting, setIsExporting] = useState(false);
  const [showFilePrompt, setShowFilePrompt] = useState(false);
  const [customFileName, setCustomFileName] = useState('');

  const [data, setData] = useState<InspectionData>({
    condoName: '',
    inspectionDate: new Date().toISOString().split('T')[0],
    logoUrl: undefined,
    technicalNotes: 'Sopralluogo effettuato per verifica stato conservativo generale dell\'immobile e delle pertinenze comuni.',
    photos: [],
    availableCategories: DEFAULT_CATEGORIES
  });

  const [summary, setSummary] = useState('');
  const [isGeneratingSummary, setIsGeneratingSummary] = useState(false);
  const pdfTemplateRef = useRef<HTMLDivElement>(null);

  const isSetupValid = useMemo(() => {
    return data.condoName.trim().length > 0 && data.inspectionDate.length > 0;
  }, [data.condoName, data.inspectionDate]);

  useEffect(() => {
    if (data.condoName && !customFileName) {
      const sanitized = data.condoName.replace(/[^a-z0-9]/gi, '_').toLowerCase();
      setCustomFileName(`report_${sanitized}_${data.inspectionDate}`);
    }
  }, [data.condoName, data.inspectionDate]);

  const fileToBase64 = (file: File): Promise<string> => {
    return new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.readAsDataURL(file);
      reader.onload = () => resolve((reader.result as string).split(',')[1]);
      reader.onerror = error => reject(error);
    });
  };

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files) {
      const newFiles = Array.from(e.target.files) as File[];
      const newPhotosPromises = newFiles.map(async (file) => {
        const base64 = await fileToBase64(file);
        return {
          id: Math.random().toString(36).substr(2, 9),
          url: URL.createObjectURL(file),
          base64Data: base64,
          mimeType: file.type,
          issue: '',
          supplier: '',
          category: data.availableCategories[0],
        };
      });
      const newPhotos = await Promise.all(newPhotosPromises);
      setData(prev => ({ ...prev, photos: [...prev.photos, ...newPhotos] }));
    }
  };

  const handleLogoChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files?.[0]) {
      const url = URL.createObjectURL(e.target.files[0]);
      setData(prev => ({ ...prev, logoUrl: url }));
    }
  };

  const updatePhoto = (id: string, updates: Partial<InspectionPhoto>) => {
    setData(prev => ({
      ...prev,
      photos: prev.photos.map(p => p.id === id ? { ...p, ...updates } : p)
    }));
  };

  const removePhoto = (id: string) => {
    setData(prev => ({
      ...prev,
      photos: prev.photos.filter(p => p.id !== id)
    }));
  };

  const handleAIEnhance = async (photo: InspectionPhoto) => {
    updatePhoto(photo.id, { isLoading: true, aiPolishedIssue: undefined });
    const polished = await professionalizeDescription(photo.issue, photo.base64Data, photo.mimeType);
    updatePhoto(photo.id, { aiPolishedIssue: polished, isLoading: false });
  };

  const handleGenerateReport = async () => {
    setStep(AppStep.REPORT);
    setIsGeneratingSummary(true);
    const issues = data.photos.map(p => p.aiPolishedIssue || p.issue).filter(Boolean);
    const execSummary = await generateExecutiveSummary(data.condoName, issues);
    setSummary(execSummary);
    setIsGeneratingSummary(false);
  };

  const executeSavePdf = useCallback(() => {
    const element = pdfTemplateRef.current;
    if (!element) return;

    setShowFilePrompt(false);
    setIsExporting(true);

    // Aspettiamo un istante per assicurarci che il DOM del template sia pronto
    setTimeout(() => {
      const opt = {
        margin: [10, 10, 10, 10],
        filename: `${customFileName || 'verbale_sopralluogo'}.pdf`,
        image: { type: 'jpeg', quality: 0.95 },
        html2canvas: { 
          scale: 2, 
          useCORS: true, 
          logging: false,
          letterRendering: true
        },
        jsPDF: { unit: 'mm', format: 'a4', orientation: 'portrait' },
        pagebreak: { mode: ['avoid-all', 'css', 'legacy'] }
      };

      html2pdf().set(opt).from(element).save().then(() => {
        setIsExporting(false);
      }).catch((err: any) => {
        console.error("Errore esportazione PDF:", err);
        alert("Si è verificato un errore durante la creazione del file. Riprova.");
        setIsExporting(false);
      });
    }, 500);
  }, [customFileName]);

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col">

      {/* OVERLAY DI CARICAMENTO PDF */}
      {isExporting && (
        <div className="fixed inset-0 z-[500] bg-white flex flex-col items-center justify-center p-10 text-center animate-in fade-in duration-300">
          <div className="spinner-ring mb-6"></div>
          <h2 className="text-xl font-black text-slate-900 uppercase tracking-widest">Compilazione Documento...</h2>
          <p className="text-slate-500 font-medium text-sm mt-2">Attendere la fine del download.</p>
        </div>
      )}

      {/* TEMPLATE PDF NASCOSTO (Solo per html2pdf) */}
      <div style={{ position: 'absolute', left: '-9999px', top: '-9999px' }}>
        <div ref={pdfTemplateRef} className="pdf-content">
          <div className="pdf-header">
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
              <div>
                <h1 style={{ margin: 0, fontSize: '24pt', fontWeight: 900, color: PRIMARY_COLOR }}>STUDIO SERRA</h1>
                <p style={{ margin: 0, fontSize: '10pt', fontWeight: 700 }}>{STUDIO_NAME}</p>
                <p style={{ margin: 0, fontSize: '8pt', color: '#888', fontStyle: 'italic' }}>{STUDIO_TAGLINE}</p>
              </div>
              <div style={{ textAlign: 'right' }}>
                <h2 style={{ margin: 0, fontSize: '18pt', fontWeight: 900 }}>VERBALE DI SOPRALLUOGO</h2>
                <p style={{ margin: 0, fontSize: '9pt', color: '#666' }}>Documento Tecnico d'Archivio</p>
              </div>
            </div>
          </div>

          <div style={{ display: 'flex', gap: '20px', marginBottom: '40px' }}>
            <div style={{ flex: 1, backgroundColor: '#f9f9f9', padding: '15px', borderRadius: '8px' }}>
              <p style={{ fontSize: '8pt', margin: '0 0 5px 0', color: '#64a1a4', fontWeight: 900, textTransform: 'uppercase' }}>Condominio</p>
              <p style={{ margin: 0, fontSize: '14pt', fontWeight: 800 }}>{data.condoName}</p>
            </div>
            <div style={{ flex: 1, backgroundColor: '#f9f9f9', padding: '15px', borderRadius: '8px' }}>
              <p style={{ fontSize: '8pt', margin: '0 0 5px 0', color: '#64a1a4', fontWeight: 900, textTransform: 'uppercase' }}>Data Sopralluogo</p>
              <p style={{ margin: 0, fontSize: '14pt', fontWeight: 800 }}>{new Date(data.inspectionDate).toLocaleDateString('it-IT')}</p>
            </div>
          </div>

          <div className="pdf-section">
            <h3 style={{ borderLeft: `4px solid ${PRIMARY_COLOR}`, paddingLeft: '10px', fontSize: '12pt', fontWeight: 900, marginBottom: '15px' }}>RELAZIONE TECNICA CONCLUSIVA</h3>
            <div className="pdf-text" style={{ backgroundColor: '#111', color: '#eee', padding: '25px', borderRadius: '15px', fontStyle: 'italic' }}>
              {summary}
            </div>
          </div>

          {data.photos.map((photo, idx) => (
            <div key={photo.id} className="pdf-section" style={{ borderTop: '1px solid #eee', paddingTop: '30px' }}>
              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-end', marginBottom: '15px' }}>
                <div style={{ display: 'flex', alignItems: 'center', gap: '15px' }}>
                  <span style={{ backgroundColor: PRIMARY_COLOR, color: 'white', width: '30px', height: '30px', borderRadius: '5px', display: 'flex', alignItems: 'center', justifyCenter: 'center', fontWeight: 900 }}>{idx + 1}</span>
                  <h4 style={{ margin: 0, fontSize: '16pt', fontWeight: 800, textTransform: 'uppercase' }}>{photo.category}</h4>
                </div>
                <div style={{ textAlign: 'right' }}>
                  <p style={{ margin: 0, fontSize: '8pt', color: '#888' }}>Ditta Manutentrice</p>
                  <p style={{ margin: 0, fontSize: '11pt', fontWeight: 700 }}>{photo.supplier || "Da definire"}</p>
                </div>
              </div>
              <img src={photo.url} className="pdf-image" alt="Rilievo" />
              <div style={{ backgroundColor: '#f5f5f5', padding: '20px', borderRadius: '10px' }}>
                <p style={{ fontSize: '8pt', margin: '0 0 8px 0', color: PRIMARY_COLOR, fontWeight: 900 }}>ANALISI DEL DIFETTO:</p>
                <p className="pdf-text" style={{ fontWeight: 600 }}>{photo.aiPolishedIssue || photo.issue}</p>
              </div>
            </div>
          ))}

          <div className="pdf-section" style={{ marginTop: '80px', borderTop: '2px solid #333', paddingTop: '30px', display: 'flex', justifyContent: 'space-between' }}>
            <div>
              <p style={{ fontSize: '9pt', color: '#888', margin: '0 0 5px 0' }}>Sottoscritto da:</p>
              <p style={{ fontSize: '12pt', fontWeight: 900, margin: 0 }}>{STUDIO_NAME}</p>
              <p style={{ fontSize: '8pt', color: '#aaa', margin: '5px 0 0 0' }}>Ref: {customFileName}</p>
            </div>
            <div style={{ width: '200px', borderTop: '1px solid #ccc', marginTop: '40px', textAlign: 'center' }}>
              <p style={{ fontSize: '7pt', color: '#888', marginTop: '5px' }}>Timbro e Firma</p>
            </div>
          </div>
        </div>
      </div>

      {/* MODAL RICHIESTA NOME FILE */}
      {showFilePrompt && (
        <div className="fixed inset-0 z-[400] flex items-center justify-center p-4 bg-slate-900/80 backdrop-blur-md animate-in fade-in duration-200">
          <div className="bg-white w-full max-w-md rounded-[2.5rem] shadow-2xl p-10 space-y-8 animate-in zoom-in-95 duration-200">
            <div className="flex justify-between items-center">
              <div className="bg-slate-50 p-4 rounded-3xl">
                <FileCheck className="w-8 h-8 text-[#64a1a4]" />
              </div>
              <button onClick={() => setShowFilePrompt(false)} className="p-2 hover:bg-slate-100 rounded-full transition-colors">
                <X className="w-6 h-6 text-slate-400" />
              </button>
            </div>
