                <div className="bg-slate-50 p-6 rounded-3xl">
                  <p className="text-[9px] font-black text-[#64a1a4] uppercase mb-1">Data</p>
                  <p className="text-xl font-black">{new Date(data.inspectionDate).toLocaleDateString('it-IT')}</p>
