      </main>

      {/* MODAL SALVATAGGIO */}
      {showFilePrompt && (
        <div className="fixed inset-0 z-[400] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm">
          <div className="bg-white w-full max-w-sm rounded-[2rem] shadow-2xl p-8 space-y-6">
            <h2 className="text-xl font-black text-slate-900">Salva Documento</h2>
            <div className="space-y-1.5">
              <label className="text-[10px] font-black uppercase text-slate-400">Nome File PDF</label>
              <input 
                autoFocus
                type="text" 
                className="w-full bg-slate-50 border-2 border-slate-100 rounded-xl px-5 py-4 outline-none focus:border-[#64a1a4] font-bold"
