import { GoogleGenAI } from "@google/genai";

export const professionalizeDescription = async (
  issue: string, 
  base64Data?: string, 
  mimeType?: string
): Promise<string> => {
  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const parts: any[] = [
      {
        text: `Sei un ingegnere esperto in manutenzione edilizia. 
        Analizza la descrizione dell'utente: "${issue}". 
        Riscrivila in modo tecnico, professionale e dettagliato (circa 50 parole). 
        Usa termini come "degrado", "ammaloramento", "ripristino", "quadro fessurativo".`
      }
    ];

    if (base64Data && mimeType) {
      parts.push({
        inlineData: {
          data: base64Data,
          mimeType: mimeType
        }
      });
    }

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: [{ role: 'user', parts }],
      config: {
        temperature: 0.4,
      },
    });

    return response.text?.trim() || issue;
  } catch (error) {
    console.error("Errore Gemini professionalizeDescription:", error);
    return issue;
  }
};

export const generateExecutiveSummary = async (condoName: string, issues: string[]): Promise<string> => {
  if (issues.length === 0) return "Sopralluogo tecnico effettuato per verificare lo stato dell'immobile.";

  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const prompt = `Agisci come l'Ing. Serra. Scrivi una relazione tecnica conclusiva per il condominio "${condoName}".
    Sintetizza questi problemi rilevati: ${issues.join(". ")}.
    La relazione deve essere formale, professionale e lunga almeno 150 parole. 
    Includi una valutazione generale e consigli per la manutenzione futura.`;

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: [{ role: 'user', parts: [{ text: prompt }] }],
      config: {
        temperature: 0.5,
      }
    });
    return response.text?.trim() || "Relazione tecnica generata in base ai rilievi effettuati.";
  } catch (error) {
    console.error("Errore Gemini generateExecutiveSummary:", error);
    return "Relazione tecnica di sopralluogo per il condominio " + condoName;
  }
};

import React, { useState, useMemo, useEffect, useCallback, useRef } from 'react';
import { 
  Camera, 
  Trash2, 
  ChevronRight, 
  ChevronLeft, 
  FileText, 
  Wand2,
  Image as ImageIcon,
  Loader2,
  Sparkles,
  Briefcase,
  AlertCircle,
  X,
  Download,
  FileCheck
} from 'lucide-react';
import { AppStep, InspectionData, InspectionPhoto } from './types';
import { professionalizeDescription, generateExecutiveSummary } from './services/geminiService';

const STUDIO_NAME = "Studio Amministrazioni Condominiali Ing. Serra";
const STUDIO_TAGLINE = "il condominio trasparente: tutto limpido, tutto evidente";
const PRIMARY_COLOR = "#64a1a4";
const DEFAULT_CATEGORIES = ['Strutturale', 'Impianto Idraulico', 'Impianto Elettrico', 'Estetica/Facciata', 'Aree Comuni', 'Sicurezza'];

declare var html2pdf: any;

const App: React.FC = () => {
  const [step, setStep] = useState<AppStep>(AppStep.SETUP);
  const [isExporting, setIsExporting] = useState(false);
  const [showFilePrompt, setShowFilePrompt] = useState(false);
  const [customFileName, setCustomFileName] = useState('');

  const [data, setData] = useState<InspectionData>({
    condoName: '',
    inspectionDate: new Date().toISOString().split('T')[0],
    logoUrl: undefined,
    technicalNotes: 'Sopralluogo effettuato per verifica stato conservativo generale dell\'immobile.',
    photos: [],
    availableCategories: DEFAULT_CATEGORIES
  });

  const [summary, setSummary] = useState('');
  const [isGeneratingSummary, setIsGeneratingSummary] = useState(false);
  const pdfRef = useRef<HTMLDivElement>(null);

  const isSetupValid = useMemo(() => {
    return data.condoName.trim().length > 0 && data.inspectionDate.length > 0;
  }, [data.condoName, data.inspectionDate]);

  useEffect(() => {
    if (data.condoName && !customFileName) {
      const sanitized = data.condoName.replace(/[^a-z0-9]/gi, '_').toLowerCase();
      setCustomFileName(`report_${sanitized}_${data.inspectionDate}`);
    }
  }, [data.condoName, data.inspectionDate]);

  const fileToBase64 = (file: File): Promise<string> => {
    return new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.readAsDataURL(file);
      reader.onload = () => resolve((reader.result as string).split(',')[1]);
      reader.onerror = error => reject(error);
    });
  };

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files) {
      const newFiles = Array.from(e.target.files) as File[];
      const newPhotosPromises = newFiles.map(async (file) => {
        const base64 = await fileToBase64(file);
        return {
          id: Math.random().toString(36).substr(2, 9),
          url: URL.createObjectURL(file),
          base64Data: base64,
          mimeType: file.type,
          issue: '',
          supplier: '',
          category: data.availableCategories[0],
        };
      });
      const newPhotos = await Promise.all(newPhotosPromises);
      setData(prev => ({ ...prev, photos: [...prev.photos, ...newPhotos] }));
    }
  };

  const handleLogoChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files?.[0]) {
      const url = URL.createObjectURL(e.target.files[0]);
      setData(prev => ({ ...prev, logoUrl: url }));
    }
  };

  const updatePhoto = (id: string, updates: Partial<InspectionPhoto>) => {
    setData(prev => ({
      ...prev,
      photos: prev.photos.map(p => p.id === id ? { ...p, ...updates } : p)
    }));
  };

  const removePhoto = (id: string) => {
    setData(prev => ({
      ...prev,
      photos: prev.photos.filter(p => p.id !== id)
    }));
  };

  const handleAIEnhance = async (photo: InspectionPhoto) => {
    updatePhoto(photo.id, { isLoading: true });
    const polished = await professionalizeDescription(photo.issue, photo.base64Data, photo.mimeType);
    updatePhoto(photo.id, { aiPolishedIssue: polished, isLoading: false });
  };

  const handleGenerateReport = async () => {
    setStep(AppStep.REPORT);
    setIsGeneratingSummary(true);
    const issues = data.photos.map(p => p.aiPolishedIssue || p.issue).filter(Boolean);
    const execSummary = await generateExecutiveSummary(data.condoName, issues);
    setSummary(execSummary);
    setIsGeneratingSummary(false);
  };

  const executeSavePdf = async () => {
    const element = pdfRef.current;
    if (!element) return;

    setShowFilePrompt(false);
    setIsExporting(true);

    // Attesa caricamento di tutte le immagini nel template PDF
    const images = element.getElementsByTagName('img');
    const imagePromises = Array.from(images).map(img => {
      if (img.complete) return Promise.resolve();
      return new Promise(resolve => {
        img.onload = resolve;
        img.onerror = resolve;
      });
    });
    await Promise.all(imagePromises);

    const opt = {
      margin: 10,
      filename: `${customFileName || 'report'}.pdf`,
      image: { type: 'jpeg', quality: 0.98 },
      html2canvas: { 
        scale: 2, 
        useCORS: true, 
        backgroundColor: '#ffffff'
      },
      jsPDF: { unit: 'mm', format: 'a4', orientation: 'portrait' },
      pagebreak: { mode: ['css', 'legacy'] }
    };

    try {
      await html2pdf().set(opt).from(element).save();
    } catch (err) {
      console.error("Errore salvataggio PDF:", err);
      alert("Si è verificato un errore durante la creazione del PDF.");
    } finally {
      setIsExporting(false);
    }
  };

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col">

      {/* OVERLAY DI CARICAMENTO */}
      {isExporting && (
        <div className="fixed inset-0 z-[500] bg-white flex flex-col items-center justify-center p-10 text-center animate-in fade-in">
          <div className="spinner-ring mb-6"></div>
          <h2 className="text-xl font-black text-slate-900 uppercase tracking-widest">Creazione Documento...</h2>
          <p className="text-slate-500 text-sm mt-2">Download in corso.</p>
        </div>
      )}

      {/* TEMPLATE PDF OTTIMIZZATO (OFF-SCREEN) */}
      <div style={{ position: 'absolute', left: '-9999px', top: '-9999px' }}>
        <div ref={pdfRef} className="pdf-export-container">
          <div style={{ display: 'flex', justifyContent: 'space-between', borderBottom: '2px solid #000', paddingBottom: '20px', marginBottom: '30px' }}>
            <div style={{ width: '70%' }}>
              {data.logoUrl && <img src={data.logoUrl} style={{ height: '70px', marginBottom: '15px', display: 'block' }} alt="Logo" />}
              <h1 style={{ margin: 0, fontSize: '22pt', fontWeight: 900, color: PRIMARY_COLOR }}>STUDIO SERRA</h1>
              <p style={{ margin: 0, fontWeight: 700, fontSize: '10pt' }}>{STUDIO_NAME}</p>
              <p style={{ margin: 0, fontSize: '8pt', color: '#666' }}>{STUDIO_TAGLINE}</p>
            </div>
            <div style={{ textAlign: 'right', width: '30%' }}>
              <h2 style={{ margin: 0, fontSize: '14pt', fontWeight: 900 }}>VERBALE TECNICO</h2>
              <p style={{ margin: 0, fontSize: '9pt', color: '#444' }}>Data: {new Date(data.inspectionDate).toLocaleDateString('it-IT')}</p>
