            </div>
            <button 
              onClick={handleOpenApiKeyDialog}
              className="bg-red-600 text-white px-4 py-1.5 rounded-lg text-[10px] font-black uppercase flex items-center gap-2 hover:bg-red-700 transition-colors shadow-sm"
            >
              <Key className="w-3 h-3" /> Usa la tua chiave API (Gratis)
            </button>
          </div>
        </div>
      )}

      {/* OVERLAY EXPORT */}
      {isExporting && (
        <div className="fixed inset-0 z-[600] bg-white/95 backdrop-blur-md flex flex-col items-center justify-center p-10 text-center">
          <div className="spinner-ring mb-6"></div>
          <h2 className="text-xl font-black text-slate-900 uppercase tracking-widest">Generazione Documento PDF...</h2>
          <p className="text-slate-500 text-sm mt-2 font-medium italic">Preparazione rilievi in corso.</p>
        </div>
      )}

      {/* PDF TEMPLATE (STAY HIDDEN BUT ACCESSIBLE) */}
      <div style={{ position: 'fixed', top: 0, left: '500vw', pointerEvents: 'none' }}>
        <div ref={pdfRef} className="pdf-export-container">
          <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', borderBottom: '2px solid #000', paddingBottom: '20px', marginBottom: '30px' }}>
            <div style={{ width: '65%' }}>
              {data.logoUrl && <img src={data.logoUrl} style={{ height: '60px', marginBottom: '15px', objectFit: 'contain' }} alt="Logo" />}
              <h1 style={{ margin: 0, fontSize: '20pt', fontWeight: 900, color: PRIMARY_COLOR }}>STUDIO ING. SERRA</h1>
              <p style={{ margin: 0, fontWeight: 700, fontSize: '9pt' }}>{STUDIO_NAME}</p>
              <p style={{ margin: 0, fontSize: '8pt', color: '#666' }}>{STUDIO_TAGLINE}</p>
            </div>
            <div style={{ textAlign: 'right', width: '35%' }}>
              <h2 style={{ margin: 0, fontSize: '13pt', fontWeight: 900, textTransform: 'uppercase' }}>Verbale di Sopralluogo</h2>
              <p style={{ margin: 0, fontSize: '9pt', color: '#444' }}>Data: {new Date(data.inspectionDate).toLocaleDateString('it-IT')}</p>
              <p style={{ margin: 0, fontSize: '10pt', fontWeight: 900, color: PRIMARY_COLOR }}>{data.condoName.toUpperCase()}</p>
            </div>
          </div>

          <div style={{ marginBottom: '40px' }}>
            <h3 style={{ fontWeight: 900, fontSize: '11pt', color: PRIMARY_COLOR, borderBottom: '1px solid #ddd', paddingBottom: '5px', marginBottom: '15px' }}>RELAZIONE TECNICA CONCLUSIVA</h3>
            <div className="pdf-text-block">
              {summary || "Nessuna relazione generata."}
