              <div style={{ background: '#f9f9f9', padding: '15px', borderRadius: '5px', marginTop: '10px' }}>
                <p style={{ fontSize: '8pt', color: PRIMARY_COLOR, fontWeight: 900, marginBottom: '5px', textTransform: 'uppercase' }}>Analisi Tecnica:</p>
                <p style={{ fontSize: '10pt', margin: 0, fontStyle: 'italic', color: '#222', lineHeight: '1.4' }}>{photo.aiPolishedIssue || photo.issue || "Nota di cantiere non pervenuta."}</p>
              </div>
            </div>
          ))}

          <div style={{ marginTop: '50px', borderTop: '1px solid #000', paddingTop: '20px' }}>
            <table style={{ width: '100%' }}>
              <tbody>
                <tr>
                  <td style={{ verticalAlign: 'top' }}>
                    <p style={{ fontWeight: 900, fontSize: '10pt', margin: 0 }}>{STUDIO_NAME}</p>
                    <p style={{ fontSize: '8pt', color: '#888', margin: 0 }}>Firmato digitalmente per conformità tecnica.</p>
                  </td>
                  <td style={{ textAlign: 'right', verticalAlign: 'top' }}>
                    <div style={{ borderTop: '1px solid #333', width: '180px', display: 'inline-block', marginTop: '30px' }}>
                      <p style={{ fontSize: '7pt', color: '#666', textAlign: 'center', marginTop: '5px' }}>Timbro e Firma</p>
                    </div>
                  </td>
                </tr>
              </tbody>
            </table>
          </div>
        </div>
      </div>

      <header className="bg-white border-b border-slate-200 sticky top-0 sm:top-auto z-50 px-4 py-4">
        <div className="max-w-4xl mx-auto flex items-center justify-between">
