                              <button onClick={() => updatePhoto(photo.id, { issue: photo.aiPolishedIssue, aiPolishedIssue: undefined })} className="text-[9px] font-black text-white bg-white/10 px-3 py-1 rounded-lg hover:bg-white/20 transition-colors uppercase">Accetta</button>
                            </div>
                            <p className="text-[11px] text-slate-300 italic leading-relaxed">{photo.aiPolishedIssue}</p>
                          </div>
                        )}
                      </div>
                    </div>
                  </div>
                ))
              )}
            </div>

            <button disabled={data.photos.length === 0} onClick={handleGenerateReport} className="w-full bg-slate-900 text-white font-black py-7 rounded-[2rem] shadow-2xl flex items-center justify-center gap-4 uppercase tracking-[0.2em] transition-all hover:scale-[1.01] active:scale-95">
