            <div className="bg-white p-8 sm:p-12 shadow-sm rounded-[2.5rem] border border-slate-100">
              <div className="flex items-center gap-2 mb-6">
                <div className="bg-[#64a1a4]/10 p-2 rounded-xl"><Sparkles className="w-4 h-4 text-[#64a1a4]" /></div>
                <h3 className="text-[11px] font-black uppercase text-[#64a1a4] tracking-widest">Sintesi Relazione (Ing. Serra)</h3>
              </div>

              {isGeneratingSummary ? (
                 <div className="p-16 bg-slate-50 rounded-3xl text-center border-2 border-dashed border-slate-100">
                   <Loader2 className="animate-spin w-10 h-10 mx-auto text-[#64a1a4] mb-4" />
