                 </div>
              ) : (
                <div className="space-y-4">
                  <textarea 
                    className="w-full bg-slate-900 p-8 sm:p-12 rounded-[2rem] text-white text-lg font-light italic leading-relaxed border-none resize-none focus:ring-2 focus:ring-[#64a1a4]/20 outline-none transition-all"
                    value={summary}
                    onChange={(e) => {
                      setSummary(e.target.value);
                      e.target.style.height = 'auto';
                      e.target.style.height = e.target.scrollHeight + 'px';
                    }}
                    rows={12}
                    placeholder="La relazione apparirà qui..."
                  />
                  <p className="text-center text-[9px] font-bold text-slate-400 uppercase tracking-widest">Puoi correggere il testo prima dell'esportazione</p>
