        )}
      </main>

      {/* SAVE MODAL */}
      {showFilePrompt && (
        <div className="fixed inset-0 z-[500] flex items-center justify-center p-4 bg-slate-900/80 backdrop-blur-md animate-in fade-in duration-300">
          <div className="bg-white w-full max-w-sm rounded-[2.5rem] shadow-2xl p-10 space-y-8 animate-in zoom-in-95 duration-200">
            <div className="flex justify-between items-center">
              <div className="bg-slate-50 p-4 rounded-2xl"><FileCheck className="w-8 h-8 text-[#64a1a4]" /></div>
              <button onClick={() => setShowFilePrompt(false)} className="text-slate-400 p-2 hover:bg-slate-100 rounded-full transition-colors"><X className="w-6 h-6" /></button>
            </div>
            <div className="space-y-2">
              <h2 className="text-2xl font-black text-slate-900 tracking-tight">Finalizza Report</h2>
              <p className="text-xs text-slate-500 font-medium italic">Il file verrà salvato sul tuo dispositivo in formato PDF alta qualità.</p>
