};

export default App;

import React, { useState, useMemo, useEffect, useRef } from 'react';
import { 
  Camera, 
  Trash2, 
  ChevronRight, 
  ChevronLeft, 
  FileText, 
  Wand2,
  Image as ImageIcon,
  Loader2,
  Sparkles,
  Briefcase,
  AlertCircle,
  X,
  Download,
  FileCheck,
  CheckCircle,
  Key,
  Layout
} from 'lucide-react';
import { AppStep, InspectionData, InspectionPhoto } from './types';
import { professionalizeDescription, generateExecutiveSummary, AIError } from './services/geminiService';

const STUDIO_NAME = "Studio Amministrazioni Condominiali Ing. Serra";
const STUDIO_TAGLINE = "il condominio trasparente: tutto limpido, tutto evidente";
const PRIMARY_COLOR = "#64a1a4";
const DEFAULT_CATEGORIES = ['Strutturale', 'Impianto Idraulico', 'Impianto Elettrico', 'Estetica/Facciata', 'Aree Comuni', 'Sicurezza'];

declare var html2pdf: any;
declare var window: any;

const App: React.FC = () => {
  const [step, setStep] = useState<AppStep>(AppStep.SETUP);
  const [isExporting, setIsExporting] = useState(false);
  const [showFilePrompt, setShowFilePrompt] = useState(false);
  const [customFileName, setCustomFileName] = useState('');
  const [apiQuotaError, setApiQuotaError] = useState(false);

  const [data, setData] = useState<InspectionData>({
    condoName: '',
    inspectionDate: new Date().toISOString().split('T')[0],
    logoUrl: undefined,
    technicalNotes: 'Sopralluogo tecnico effettuato.',
    photos: [],
    availableCategories: DEFAULT_CATEGORIES
  });

  const [summary, setSummary] = useState('');
  const [isGeneratingSummary, setIsGeneratingSummary] = useState(false);
  const pdfRef = useRef<HTMLDivElement>(null);

  const isSetupValid = useMemo(() => {
    return data.condoName.trim().length > 0 && data.inspectionDate.length > 0;
  }, [data.condoName, data.inspectionDate]);

  useEffect(() => {
    if (data.condoName && !customFileName) {
      const sanitized = data.condoName.replace(/[^a-z0-9]/gi, '_').toLowerCase();
      setCustomFileName(`verbale_${sanitized}_${data.inspectionDate}`);
    }
  }, [data.condoName, data.inspectionDate]);

  const handleOpenApiKeyDialog = async () => {
    try {
      await window.aistudio.openSelectKey();
      setApiQuotaError(false);
    } catch (e) {
      console.error("Failed to open key selector", e);
    }
  };

  const fileToBase64 = (file: File): Promise<string> => {
    return new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.readAsDataURL(file);
      reader.onload = () => resolve((reader.result as string).split(',')[1]);
      reader.onerror = error => reject(error);
    });
  };

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files) {
      const newFiles = Array.from(e.target.files) as File[];
      const newPhotosPromises = newFiles.map(async (file) => {
        const base64 = await fileToBase64(file);
        return {
          id: Math.random().toString(36).substr(2, 9),
          url: URL.createObjectURL(file),
          base64Data: base64,
          mimeType: file.type,
          issue: '',
          supplier: '',
          category: data.availableCategories[0],
        };
      });
      const newPhotos = await Promise.all(newPhotosPromises);
      setData(prev => ({ ...prev, photos: [...prev.photos, ...newPhotos] }));
    }
  };

  const handleLogoChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files?.[0]) {
      const url = URL.createObjectURL(e.target.files[0]);
      setData(prev => ({ ...prev, logoUrl: url }));
    }
  };

  const updatePhoto = (id: string, updates: Partial<InspectionPhoto>) => {
    setData(prev => ({
      ...prev,
      photos: prev.photos.map(p => p.id === id ? { ...p, ...updates } : p)
    }));
  };

  const removePhoto = (id: string) => {
    setData(prev => ({
      ...prev,
      photos: prev.photos.filter(p => p.id !== id)
    }));
  };

  const handleAIEnhance = async (photo: InspectionPhoto) => {
    updatePhoto(photo.id, { isLoading: true });
    try {
      const polished = await professionalizeDescription(photo.issue, photo.base64Data, photo.mimeType);
      updatePhoto(photo.id, { aiPolishedIssue: polished, isLoading: false });
    } catch (err: any) {
      updatePhoto(photo.id, { isLoading: false });
      if (err instanceof AIError && err.status === "QUOTA_EXCEEDED") {
        setApiQuotaError(true);
      }
    }
  };

  const handleGenerateReport = async () => {
    setStep(AppStep.REPORT);
    setIsGeneratingSummary(true);
    const issues = data.photos.map(p => p.aiPolishedIssue || p.issue).filter(Boolean);
    try {
      const execSummary = await generateExecutiveSummary(data.condoName, issues);
      setSummary(execSummary);
    } catch (err: any) {
      if (err instanceof AIError && err.status === "QUOTA_EXCEEDED") {
        setApiQuotaError(true);
        setSummary("Limite di traffico IA raggiunto. Per favore, usa la tua chiave API per generare la relazione.");
      }
    } finally {
      setIsGeneratingSummary(false);
    }
  };

  const executeSavePdf = async () => {
    const element = pdfRef.current;
    if (!element) return;

    setShowFilePrompt(false);
    setIsExporting(true);

    // FIX FOTO: Attendiamo che tutte le immagini nel template siano caricate
    const images = Array.from(element.getElementsByTagName('img'));
    const loadPromises = images.map(img => {
      if (img.complete) return Promise.resolve();
      return new Promise(resolve => {
        img.onload = resolve;
        img.onerror = resolve;
      });
    });
    await Promise.all(loadPromises);

    const opt = {
      margin: 10,
      filename: `${customFileName}.pdf`,
      image: { type: 'jpeg', quality: 0.98 },
      html2canvas: { 
        scale: 2, 
        useCORS: true, 
        backgroundColor: '#ffffff',
        logging: false,
        letterRendering: true
      },
      jsPDF: { unit: 'mm', format: 'a4', orientation: 'portrait' },
      pagebreak: { mode: ['css', 'legacy'] }
    };

    try {
      await html2pdf().set(opt).from(element).save();
    } catch (err) {
      console.error("Errore PDF:", err);
      alert("Errore durante l'esportazione.");
    } finally {
      setIsExporting(false);
    }
  };

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col">

      {/* BANNER ERRORE QUOTA */}
      {apiQuotaError && (
        <div className="bg-red-50 border-b border-red-100 px-4 py-3 sticky top-0 z-[100] animate-in slide-in-from-top duration-300">
          <div className="max-w-4xl mx-auto flex flex-col sm:flex-row items-center justify-between gap-3">
            <div className="flex items-center gap-2 text-red-700 text-xs font-bold uppercase tracking-tight">
              <AlertCircle className="w-4 h-4" />
              <span>Limite richieste raggiunto. Usa la tua chiave per sbloccare l'IA.</span>
            </div>
            <button 
              onClick={handleOpenApiKeyDialog}
              className="bg-red-600 text-white px-4 py-1.5 rounded-lg text-[10px] font-black uppercase flex items-center gap-2 hover:bg-red-700 transition-colors shadow-sm"
            >
              <Key className="w-3 h-3" /> Configura Chiave API
            </button>
          </div>
        </div>
      )}

      {/* OVERLAY EXPORT */}
      {isExporting && (
        <div className="fixed inset-0 z-[600] bg-white/95 backdrop-blur-md flex flex-col items-center justify-center p-10 text-center">
          <div className="spinner-ring mb-6"></div>
          <h2 className="text-xl font-black text-slate-900 uppercase tracking-widest">Creazione Documento...</h2>
          <p className="text-slate-500 text-sm mt-2 font-medium">Le foto vengono impaginate nel verbale.</p>
        </div>
      )}

      {/* TEMPLATE PDF (OFF-SCREEN MA RENDERIZZATO) */}
      <div style={{ position: 'fixed', top: 0, left: '1000vw', pointerEvents: 'none' }}>
        <div ref={pdfRef} id="pdf-template">
          <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', borderBottom: '3px solid #000', paddingBottom: '20px', marginBottom: '30px' }}>
            <div style={{ width: '65%' }}>
              {data.logoUrl && <img src={data.logoUrl} style={{ height: '70px', marginBottom: '15px', objectFit: 'contain' }} alt="Logo" />}
              <h1 style={{ margin: 0, fontSize: '22pt', fontWeight: 900, color: PRIMARY_COLOR }}>STUDIO ING. SERRA</h1>
              <p style={{ margin: 0, fontWeight: 700, fontSize: '10pt' }}>{STUDIO_NAME}</p>
              <p style={{ margin: 0, fontSize: '8pt', color: '#666' }}>{STUDIO_TAGLINE}</p>
            </div>
            <div style={{ textAlign: 'right', width: '35%' }}>
              <h2 style={{ margin: 0, fontSize: '14pt', fontWeight: 900, textTransform: 'uppercase' }}>Verbale Sopralluogo</h2>
              <p style={{ margin: 0, fontSize: '9pt', color: '#444' }}>Data: {new Date(data.inspectionDate).toLocaleDateString('it-IT')}</p>
              <p style={{ margin: 0, fontSize: '11pt', fontWeight: 900, color: PRIMARY_COLOR }}>CONDOMINIO: {data.condoName.toUpperCase()}</p>
            </div>
          </div>

          <div className="pdf-section-title">Relazione Tecnica Conclusiva</div>
          <div style={{ fontSize: '11pt', lineHeight: '1.6', textAlign: 'justify', whiteSpace: 'pre-wrap', marginBottom: '40px' }}>
            {summary || "Nessuna relazione generata."}
          </div>

          <div className="pdf-section-title">Elenco Rilievi Fotografici</div>
          {data.photos.map((photo, idx) => (
            <div key={photo.id} className="pdf-item">
              <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '10px' }}>
                <span style={{ fontWeight: 900, fontSize: '12pt' }}>{idx + 1}. {photo.category.toUpperCase()}</span>
                <span style={{ fontWeight: 700, fontSize: '10pt' }}>Rif: {photo.supplier || "N/D"}</span>
              </div>
              <div className="pdf-photo-container">
                <img src={photo.url} className="pdf-photo" alt={`Foto ${idx+1}`} />
              </div>
              <div className="pdf-desc-box">
                <p style={{ fontSize: '8pt', fontWeight: 900, color: PRIMARY_COLOR, margin: '0 0 5px 0' }}>DESCRIZIONE TECNICA:</p>
                <p style={{ fontSize: '10pt', margin: 0, fontStyle: 'italic', lineHeight: '1.4' }}>{photo.aiPolishedIssue || photo.issue || "Nessuna nota aggiunta."}</p>
              </div>
            </div>
          ))}

          <div style={{ marginTop: '50px', borderTop: '1px solid #000', paddingTop: '20px' }}>
            <table style={{ width: '100%' }}>
              <tbody>
                <tr>
                  <td>
                    <p style={{ fontWeight: 900, fontSize: '10pt', margin: 0 }}>{STUDIO_NAME}</p>
                    <p style={{ fontSize: '8pt', color: '#888', margin: 0 }}>Firmato in originale dall'Ing. Serra</p>
                  </td>
                  <td style={{ textAlign: 'right' }}>
                    <div style={{ borderTop: '1px solid #333', width: '200px', display: 'inline-block', marginTop: '30px' }}>
                      <p style={{ fontSize: '7pt', color: '#666', textAlign: 'center', marginTop: '5px' }}>Timbro e Firma Professionale</p>
                    </div>
                  </td>
                </tr>
              </tbody>
            </table>
          </div>
        </div>
      </div>

      {/* HEADER APP */}
      <header className="bg-white border-b border-slate-200 sticky top-0 z-50 px-4 py-4">
        <div className="max-w-4xl mx-auto flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="p-2 rounded-xl bg-slate-900 shadow-md">
              <Briefcase className="text-white w-5 h-5" />
            </div>
            <h1 className="text-sm font-black text-slate-800 uppercase italic tracking-tight">Studio Ing. Serra</h1>
          </div>
          <div className="bg-slate-50 px-3 py-1 rounded-full border border-slate-100 flex items-center gap-2">
            <div className="w-1.5 h-1.5 rounded-full bg-emerald-500 animate-pulse"></div>
            <span className="text-[10px] font-bold text-slate-400 uppercase">Live Report Editor</span>
          </div>
        </div>
      </header>

      <main className="flex-1 max-w-4xl mx-auto w-full p-4 sm:p-6 pb-32">
        {step === AppStep.SETUP && (
          <div className="bg-white rounded-[2.5rem] shadow-sm border border-slate-200 p-8 sm:p-12 animate-in fade-in duration-500">
             <div className="mb-10 border-b border-slate-100 pb-6 flex items-center justify-between">
                <div>
                  <h2 className="text-2xl font-black italic tracking-tighter" style={{ color: PRIMARY_COLOR }}>SOPRALLUOGO</h2>
                  <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mt-1">Configurazione Dati</p>
                </div>
                <div className="bg-slate-50 p-3 rounded-2xl"><FileCheck className="w-6 h-6 text-slate-300" /></div>
             </div>

             <div className="space-y-8">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                  <div className="space-y-2">
                    <label className="text-[10px] font-black uppercase text-slate-400 ml-1">Nome Condominio *</label>
                    <input type="text" className="w-full px-5 py-4 bg-slate-50 border-2 border-slate-50 rounded-2xl focus:border-[#64a1a4] outline-none font-bold transition-all" value={data.condoName} onChange={(e) => setData({...data, condoName: e.target.value})} placeholder="Es. Condominio Giardini" />
                  </div>
                  <div className="space-y-2">
                    <label className="text-[10px] font-black uppercase text-slate-400 ml-1">Data Ispezione *</label>
                    <input type="date" className="w-full px-5 py-4 bg-slate-50 border-2 border-slate-50 rounded-2xl focus:border-[#64a1a4] outline-none font-bold transition-all" value={data.inspectionDate} onChange={(e) => setData({...data, inspectionDate: e.target.value})} />
                  </div>
                </div>

                <div className="space-y-2">
                  <label className="text-[10px] font-black uppercase text-slate-400 ml-1">Logo Studio</label>
                  <div className="flex flex-col sm:flex-row items-center gap-6">
                    {data.logoUrl && (
                      <div className="relative group animate-in zoom-in duration-200">
                        <img src={data.logoUrl} className="w-24 h-24 object-contain border-2 border-slate-100 rounded-2xl p-2 bg-white" alt="Logo" />
                        <button onClick={() => setData({...data, logoUrl: undefined})} className="absolute -top-2 -right-2 bg-red-500 text-white p-1 rounded-full shadow-lg hover:scale-110 transition-transform"><X className="w-3 h-3" /></button>
                      </div>
                    )}
                    <label className="flex-1 w-full border-2 border-dashed border-slate-200 rounded-[1.5rem] p-8 flex flex-col items-center justify-center gap-3 cursor-pointer hover:bg-slate-50 hover:border-[#64a1a4] transition-all group">
                      <ImageIcon className="w-8 h-8 text-slate-300 group-hover:text-[#64a1a4]" />
                      <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest text-center">Seleziona logo professionale</span>
                      <input type="file" accept="image/*" className="hidden" onChange={handleLogoChange} />
                    </label>
                  </div>
                </div>
             </div>

             <button disabled={!isSetupValid} onClick={() => setStep(AppStep.PHOTOS)} className="w-full mt-10 text-white font-black py-6 rounded-2xl shadow-xl flex items-center justify-center gap-3 uppercase tracking-widest transition-all hover:scale-[1.02] disabled:opacity-50" style={{ backgroundColor: isSetupValid ? PRIMARY_COLOR : "#cbd5e1" }}>
                Prosegui ai Rilievi <ChevronRight className="w-5 h-5" />
             </button>
          </div>
        )}

        {step === AppStep.PHOTOS && (
          <div className="space-y-8 animate-in slide-in-from-bottom-4 duration-500">
            <div className="flex items-center justify-between bg-white/80 backdrop-blur-md p-4 rounded-2xl border border-slate-200 sticky top-20 z-40 shadow-sm">
              <button onClick={() => setStep(AppStep.SETUP)} className="text-slate-400 hover:text-slate-900 font-black text-[10px] uppercase tracking-widest flex items-center gap-2">
                <ChevronLeft className="w-4 h-4" /> Indietro
              </button>
              <label className="flex items-center gap-2 text-white px-8 py-3.5 rounded-2xl cursor-pointer shadow-lg font-black text-xs uppercase tracking-widest transition-all hover:brightness-110" style={{ backgroundColor: PRIMARY_COLOR }}>
                <Camera className="w-4 h-4" /> Scatta/Aggiungi Foto
                <input type="file" multiple accept="image/*" className="hidden" onChange={handleFileChange} />
              </label>
            </div>

            <div className="grid grid-cols-1 gap-6">
              {data.photos.length === 0 ? (
                <div className="bg-white border-4 border-dashed border-slate-100 rounded-[3rem] p-24 text-center">
                  <div className="bg-slate-50 w-16 h-16 rounded-full flex items-center justify-center mx-auto mb-6">
                    <Camera className="text-slate-200 w-8 h-8" />
                  </div>
                  <p className="font-black text-slate-300 uppercase tracking-widest text-[10px]">Aggiungi le foto del sopralluogo</p>
                </div>
              ) : (
                data.photos.map((photo) => (
                  <div key={photo.id} className="bg-white rounded-[2rem] shadow-sm border border-slate-200 overflow-hidden group hover:border-[#64a1a4]/30 transition-all">
                    <div className="flex flex-col md:flex-row">
                      <div className="md:w-1/3 relative bg-slate-100 min-h-[220px]">
                        <img src={photo.url} className="w-full h-full object-cover" alt="Rilievo" />
                        <button onClick={() => removePhoto(photo.id)} className="absolute top-4 right-4 p-2.5 bg-red-500 text-white rounded-xl shadow-lg transition-transform hover:scale-110"><Trash2 className="w-4 h-4" /></button>
                      </div>
                      <div className="flex-1 p-6 space-y-4">
                        <div className="grid grid-cols-2 gap-4">
                          <div className="space-y-1">
                            <label className="text-[9px] font-black uppercase text-slate-400 block ml-1">Settore</label>
                            <select className="w-full p-3 bg-slate-50 border-2 border-slate-50 rounded-xl text-[10px] font-black uppercase outline-none focus:border-[#64a1a4]" value={photo.category} onChange={(e) => updatePhoto(photo.id, { category: e.target.value })}>
                              {data.availableCategories.map(cat => <option key={cat} value={cat}>{cat}</option>)}
                            </select>
                          </div>
                          <div className="space-y-1">
                            <label className="text-[9px] font-black uppercase text-slate-400 block ml-1">Fornitore</label>
                            <input type="text" placeholder="Ditta Rif..." className="w-full p-3 bg-slate-50 border-2 border-slate-50 rounded-xl text-[10px] font-bold outline-none focus:border-[#64a1a4]" value={photo.supplier} onChange={(e) => updatePhoto(photo.id, { supplier: e.target.value })} />
                          </div>
                        </div>
                        <div className="relative">
                          <label className="text-[9px] font-black uppercase text-slate-400 block mb-1 ml-1">Problema Evidenziato</label>
                          <textarea placeholder="Descrivi il difetto..." className="w-full p-4 bg-slate-50 border-2 border-slate-50 rounded-2xl text-xs font-medium min-h-[100px] resize-none focus:border-[#64a1a4] outline-none" value={photo.issue} onChange={(e) => updatePhoto(photo.id, { issue: e.target.value })} />
                          <button onClick={() => handleAIEnhance(photo)} disabled={photo.isLoading || !photo.issue} className="absolute bottom-3 right-3 p-2.5 bg-white border border-slate-100 rounded-xl shadow-sm hover:shadow-md text-[#64a1a4] disabled:opacity-40 transition-all">
                            {photo.isLoading ? <Loader2 className="animate-spin h-4 w-4" /> : <Wand2 className="w-4 h-4" />}
                          </button>
                        </div>
                        {photo.aiPolishedIssue && (
                          <div className="p-4 bg-slate-900 rounded-2xl animate-in slide-in-from-top-2">
                            <div className="flex items-center justify-between mb-2">
                              <p className="text-[9px] font-black text-[#64a1a4] uppercase flex items-center gap-2"><Sparkles className="w-3 h-3" /> Report Tecnico IA</p>
                              <button onClick={() => updatePhoto(photo.id, { issue: photo.aiPolishedIssue, aiPolishedIssue: undefined })} className="text-[9px] font-black text-white bg-white/10 px-2 py-1 rounded-lg uppercase">Applica</button>
                            </div>
                            <p className="text-[11px] text-slate-300 italic leading-relaxed">{photo.aiPolishedIssue}</p>
                          </div>
                        )}
                      </div>
                    </div>
                  </div>
                ))
              )}
            </div>

            <button disabled={data.photos.length === 0} onClick={handleGenerateReport} className="w-full bg-slate-900 text-white font-black py-7 rounded-[2rem] shadow-2xl flex items-center justify-center gap-4 uppercase tracking-[0.2em] transition-all hover:scale-[1.01]">
              Genera Relazione <FileText className="w-6 h-6" />
            </button>
          </div>
        )}

        {step === AppStep.REPORT && (
          <div className="space-y-8 animate-in fade-in duration-500">
             <div className="fixed bottom-8 left-1/2 -translate-x-1/2 z-[100] w-full max-w-xs px-4">
              <button onClick={() => setShowFilePrompt(true)} disabled={isExporting} className="w-full bg-emerald-600 text-white p-5 rounded-full shadow-2xl flex items-center justify-center gap-3 hover:scale-105 active:scale-95 transition-all">
                <Download className="w-6 h-6" />
                <span className="font-black text-xs uppercase tracking-widest">Esporta Verbale PDF</span>
              </button>
            </div>

            <button onClick={() => setStep(AppStep.PHOTOS)} className="text-slate-400 hover:text-slate-900 font-black text-[10px] uppercase tracking-widest flex items-center gap-2">
              <ChevronLeft className="w-4 h-4" /> Torna ai Rilievi
            </button>

            <div className="space-y-6">
              {/* RELAZIONE TESTUALE */}
              <div className="bg-white p-8 sm:p-12 shadow-sm rounded-[2.5rem] border border-slate-100">
                <div className="flex items-center gap-2 mb-6">
                  <div className="bg-[#64a1a4]/10 p-2 rounded-xl"><Sparkles className="w-4 h-4 text-[#64a1a4]" /></div>
                  <h3 className="text-[11px] font-black uppercase text-[#64a1a4] tracking-widest">Sintesi Relazione</h3>
                </div>

                {isGeneratingSummary ? (
                   <div className="p-12 bg-slate-50 rounded-3xl text-center border-2 border-dashed border-slate-100">
                     <Loader2 className="animate-spin w-10 h-10 mx-auto text-[#64a1a4] mb-4" />
                     <p className="text-[11px] font-black text-[#64a1a4] uppercase animate-pulse">L'IA sta elaborando la relazione...</p>
                   </div>
                ) : (
                  <textarea 
                    className="w-full bg-slate-900 p-8 sm:p-10 rounded-[2rem] text-white text-lg font-light italic leading-relaxed border-none resize-none focus:ring-0 outline-none transition-all"
                    value={summary}
                    onChange={(e) => {
                      setSummary(e.target.value);
                      e.target.style.height = 'auto';
                      e.target.style.height = e.target.scrollHeight + 'px';
                    }}
                    rows={10}
                  />
                )}
              </div>

              {/* PREVIEW RILIEVI NEL REPORT */}
              <div className="space-y-4">
                <h3 className="text-[11px] font-black uppercase text-slate-400 tracking-[0.2em] flex items-center gap-2 px-6">
                  <Layout className="w-4 h-4" /> Anteprima Elenco Rilievi
                </h3>
                {data.photos.map((photo, idx) => (
                  <div key={photo.id} className="bg-white border border-slate-100 rounded-3xl p-6 flex gap-6 items-center shadow-sm">
                    <div className="w-24 h-24 rounded-2xl overflow-hidden bg-slate-100 flex-shrink-0">
                      <img src={photo.url} className="w-full h-full object-cover" alt="Rilievo" />
                    </div>
                    <div className="flex-1">
                      <div className="flex items-center gap-3 mb-1">
                        <span className="text-[10px] font-black text-[#64a1a4] uppercase">{photo.category}</span>
                        <span className="text-[10px] font-bold text-slate-300">|</span>
                        <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">{photo.supplier || "Nessun Fornitore"}</span>
                      </div>
                      <p className="text-xs text-slate-600 font-medium italic line-clamp-2">
                        {photo.aiPolishedIssue || photo.issue || "Nessuna nota tecnica."}
                      </p>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          </div>
        )}
      </main>

      {/* MODAL SALVATAGGIO */}
      {showFilePrompt && (
        <div className="fixed inset-0 z-[500] flex items-center justify-center p-4 bg-slate-900/80 backdrop-blur-md animate-in fade-in duration-300">
          <div className="bg-white w-full max-w-sm rounded-[2.5rem] shadow-2xl p-10 space-y-8 animate-in zoom-in-95 duration-200">
            <div className="flex justify-between items-center">
              <div className="bg-slate-50 p-4 rounded-2xl"><FileCheck className="w-8 h-8 text-[#64a1a4]" /></div>
              <button onClick={() => setShowFilePrompt(false)} className="text-slate-400 p-2 hover:bg-slate-100 rounded-full transition-colors"><X className="w-6 h-6" /></button>
            </div>
            <div className="space-y-2">
              <h2 className="text-2xl font-black text-slate-900 tracking-tight">Esporta Verbale</h2>
              <p className="text-xs text-slate-500 font-medium italic">Il documento includerà tutte le foto e la relazione tecnica.</p>
            </div>
            <div className="space-y-1.5">
              <label className="text-[10px] font-black uppercase text-[#64a1a4] tracking-widest ml-1">Nome File PDF</label>
              <input 
                autoFocus
                type="text" 
                className="w-full bg-slate-50 border-2 border-slate-100 rounded-2xl px-6 py-5 outline-none focus:border-[#64a1a4] font-black text-slate-800"
                value={customFileName}
                onChange={(e) => setCustomFileName(e.target.value)}
              />
            </div>
            <button onClick={executeSavePdf} className="w-full bg-slate-900 text-white font-black py-6 rounded-2xl shadow-xl flex items-center justify-center gap-4 hover:bg-black transition-all transform active:scale-95">
              SCARICA PDF <Download className="w-6 h-6" />
            </button>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

import React, { useState, useMemo, useEffect, useRef } from 'react';
import { 
  Camera, 
  Trash2, 
  ChevronRight, 
  ChevronLeft, 
  FileText, 
  Wand2,
  Image as ImageIcon,
  Loader2,
  Sparkles,
  Briefcase,
  AlertCircle,
  X,
  Download,
  FileCheck,
  CheckCircle,
  Key,
  Layout
} from 'lucide-react';
import { AppStep, InspectionData, InspectionPhoto } from './types';
import { professionalizeDescription, generateExecutiveSummary, AIError } from './services/geminiService';

const STUDIO_NAME = "Studio Amministrazioni Condominiali Ing. Serra";
const STUDIO_TAGLINE = "il condominio trasparente: tutto limpido, tutto evidente";
const PRIMARY_COLOR = "#64a1a4";
const DEFAULT_CATEGORIES = ['Strutturale', 'Impianto Idraulico', 'Impianto Elettrico', 'Estetica/Facciata', 'Aree Comuni', 'Sicurezza'];

declare var html2pdf: any;
declare var window: any;

const App: React.FC = () => {
  const [step, setStep] = useState<AppStep>(AppStep.SETUP);
  const [isExporting, setIsExporting] = useState(false);
  const [showFilePrompt, setShowFilePrompt] = useState(false);
  const [customFileName, setCustomFileName] = useState('');
  const [apiQuotaError, setApiQuotaError] = useState(false);

  const [data, setData] = useState<InspectionData>({
    condoName: '',
    inspectionDate: new Date().toISOString().split('T')[0],
    logoUrl: undefined,
    technicalNotes: 'Sopralluogo tecnico effettuato.',
    photos: [],
    availableCategories: DEFAULT_CATEGORIES
  });

  const [summary, setSummary] = useState('');
  const [isGeneratingSummary, setIsGeneratingSummary] = useState(false);
  const pdfRef = useRef<HTMLDivElement>(null);

  const isSetupValid = useMemo(() => {
    return data.condoName.trim().length > 0 && data.inspectionDate.length > 0;
  }, [data.condoName, data.inspectionDate]);

  useEffect(() => {
    if (data.condoName && !customFileName) {
      const sanitized = data.condoName.replace(/[^a-z0-9]/gi, '_').toLowerCase();
      setCustomFileName(`verbale_${sanitized}_${data.inspectionDate}`);
    }
  }, [data.condoName, data.inspectionDate]);

  const handleOpenApiKeyDialog = async () => {
    try {
      await window.aistudio.openSelectKey();
      setApiQuotaError(false);
    } catch (e) {
      console.error("Failed to open key selector", e);
    }
  };

  const fileToBase64 = (file: File): Promise<string> => {
    return new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.readAsDataURL(file);
      reader.onload = () => resolve((reader.result as string).split(',')[1]);
      reader.onerror = error => reject(error);
    });
  };

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files) {
      const newFiles = Array.from(e.target.files) as File[];
      const newPhotosPromises = newFiles.map(async (file) => {
        const base64 = await fileToBase64(file);
        return {
          id: Math.random().toString(36).substr(2, 9),
          url: URL.createObjectURL(file),
          base64Data: base64,
          mimeType: file.type,
          issue: '',
          supplier: '',
          category: data.availableCategories[0],
        };
      });
      const newPhotos = await Promise.all(newPhotosPromises);
      setData(prev => ({ ...prev, photos: [...prev.photos, ...newPhotos] }));
    }
  };

  const handleLogoChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files?.[0]) {
      const url = URL.createObjectURL(e.target.files[0]);
      setData(prev => ({ ...prev, logoUrl: url }));
    }
  };

  const updatePhoto = (id: string, updates: Partial<InspectionPhoto>) => {
    setData(prev => ({
      ...prev,
      photos: prev.photos.map(p => p.id === id ? { ...p, ...updates } : p)
    }));
  };

  const removePhoto = (id: string) => {
    setData(prev => ({
      ...prev,
      photos: prev.photos.filter(p => p.id !== id)
    }));
  };

  const handleAIEnhance = async (photo: InspectionPhoto) => {
    updatePhoto(photo.id, { isLoading: true });
    try {
      const polished = await professionalizeDescription(photo.issue, photo.base64Data, photo.mimeType);
      updatePhoto(photo.id, { aiPolishedIssue: polished, isLoading: false });
    } catch (err: any) {
      updatePhoto(photo.id, { isLoading: false });
      if (err instanceof AIError && err.status === "QUOTA_EXCEEDED") {
        setApiQuotaError(true);
      }
    }
  };

  const handleGenerateReport = async () => {
    setStep(AppStep.REPORT);
    setIsGeneratingSummary(true);
    const issues = data.photos.map(p => p.aiPolishedIssue || p.issue).filter(Boolean);
    try {
      const execSummary = await generateExecutiveSummary(data.condoName, issues);
      setSummary(execSummary);
    } catch (err: any) {
      if (err instanceof AIError && err.status === "QUOTA_EXCEEDED") {
        setApiQuotaError(true);
        setSummary("Relazione generata in modalità provvisoria causa limiti traffico.");
      }
    } finally {
      setIsGeneratingSummary(false);
    }
  };

  const executeSavePdf = async () => {
    const element = pdfRef.current;
    if (!element) return;

    setShowFilePrompt(false);
    setIsExporting(true);

    // Garantisce che il template sia pronto prima della cattura
    await new Promise(resolve => setTimeout(resolve, 500));

    const images = Array.from(element.getElementsByTagName('img'));
    const loadPromises = images.map(img => {
      if (img.complete) return Promise.resolve();
      return new Promise(resolve => {
        img.onload = resolve;
        img.onerror = resolve;
      });
    });
    await Promise.all(loadPromises);

    const opt = {
      margin: 0, // I margini sono gestiti nel CSS con padding: 20mm
      filename: `${customFileName}.pdf`,
      image: { type: 'jpeg', quality: 0.98 },
      html2canvas: { 
        scale: 2, 
        useCORS: true, 
        backgroundColor: '#ffffff',
        logging: false,
        width: 793.7, // 210mm a 96 DPI
      },
      jsPDF: { unit: 'mm', format: 'a4', orientation: 'portrait' },
      pagebreak: { mode: ['css', 'legacy'] }
    };

    try {
      await html2pdf().set(opt).from(element).save();
    } catch (err) {
      console.error("Errore PDF:", err);
      alert("Errore durante l'esportazione.");
    } finally {
      setIsExporting(false);
    }
  };

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col">

      {apiQuotaError && (
        <div className="bg-red-50 border-b border-red-100 px-4 py-3 sticky top-0 z-[100] animate-in slide-in-from-top">
          <div className="max-w-4xl mx-auto flex flex-col sm:flex-row items-center justify-between gap-3">
            <div className="flex items-center gap-2 text-red-700 text-xs font-bold uppercase tracking-tight">
              <AlertCircle className="w-4 h-4" />
              <span>Limite richieste raggiunto. Sblocca con la tua chiave.</span>
            </div>
            <button onClick={handleOpenApiKeyDialog} className="bg-red-600 text-white px-4 py-1.5 rounded-lg text-[10px] font-black uppercase flex items-center gap-2 hover:bg-red-700">
              <Key className="w-3 h-3" /> Configura API
            </button>
          </div>
        </div>
      )}

      {isExporting && (
        <div className="fixed inset-0 z-[600] bg-white/95 flex flex-col items-center justify-center p-10 text-center">
          <div className="spinner-ring mb-6"></div>
          <h2 className="text-xl font-black text-slate-900 uppercase tracking-widest">Generazione PDF in corso...</h2>
          <p className="text-slate-500 text-sm mt-2 font-medium">Impaginazione rilievi tecnici...</p>
        </div>
      )}

      {/* TEMPLATE PDF NASCOSTO */}
      <div style={{ position: 'fixed', top: 0, left: '2000vw', pointerEvents: 'none' }}>
        <div ref={pdfRef} id="pdf-template">
          <div className="pdf-header">
            <div style={{ width: '60%' }}>
              {data.logoUrl && <img src={data.logoUrl} style={{ height: '60pt', marginBottom: '10pt', objectFit: 'contain' }} alt="Logo" />}
              <h1 style={{ margin: 0, fontSize: '20pt', fontWeight: 900, color: PRIMARY_COLOR }}>STUDIO ING. SERRA</h1>
              <p style={{ margin: 0, fontWeight: 700, fontSize: '10pt', color: '#333' }}>{STUDIO_NAME}</p>
              <p style={{ margin: 0, fontSize: '8pt', color: '#666' }}>{STUDIO_TAGLINE}</p>
            </div>
            <div style={{ textAlign: 'right', width: '40%' }}>
              <h2 style={{ margin: 0, fontSize: '12pt', fontWeight: 900, textTransform: 'uppercase' }}>Verbale Sopralluogo</h2>
              <p style={{ margin: 0, fontSize: '9pt', color: '#444' }}>Data: {new Date(data.inspectionDate).toLocaleDateString('it-IT')}</p>
              <div style={{ marginTop: '10pt', padding: '5pt', background: '#f8fafc', borderRadius: '4pt' }}>
                <p style={{ margin: 0, fontSize: '10pt', fontWeight: 900, color: PRIMARY_COLOR }}>{data.condoName.toUpperCase()}</p>
              </div>
            </div>
          </div>

          <div className="pdf-section-title">Relazione Tecnica Conclusiva</div>
          <div style={{ fontSize: '11pt', lineHeight: '1.6', textAlign: 'justify', whiteSpace: 'pre-wrap', marginBottom: '30pt', color: '#1a1a1a' }}>
            {summary || "Relazione tecnica non fornita."}
          </div>

          <div className="pdf-section-title">Rilievi Fotografici Dettagliati</div>
          {data.photos.map((photo, idx) => (
            <div key={photo.id} className="pdf-item">
              <div style={{ display: 'flex', justifySelf: 'stretch', justifyContent: 'space-between', marginBottom: '10pt', borderBottom: '0.5pt solid #eee', paddingBottom: '5pt' }}>
                <span style={{ fontWeight: 900, fontSize: '11pt', color: '#333' }}>RILIEVO #{idx + 1} - {photo.category.toUpperCase()}</span>
                <span style={{ fontWeight: 700, fontSize: '9pt', color: '#666' }}>FORNITORE: {photo.supplier || "N/D"}</span>
              </div>
              <div className="pdf-photo-container">
                <img src={photo.url} className="pdf-photo" alt={`Foto ${idx+1}`} />
              </div>
              <div className="pdf-desc-box">
                <p style={{ fontSize: '8pt', fontWeight: 900, color: PRIMARY_COLOR, margin: '0 0 4pt 0', textTransform: 'uppercase' }}>Analisi del Difetto:</p>
                <p style={{ fontSize: '10.5pt', margin: 0, fontStyle: 'italic', lineHeight: '1.5', color: '#2d3748' }}>
                  {photo.aiPolishedIssue || photo.issue || "Nessuna nota tecnica rilevata."}
                </p>
              </div>
            </div>
          ))}

          <div className="pdf-footer">
            <table style={{ width: '100%' }}>
              <tbody>
                <tr>
                  <td style={{ width: '50%' }}>
                    <p style={{ fontWeight: 900, fontSize: '10pt', margin: 0 }}>{STUDIO_NAME}</p>
                    <p style={{ fontSize: '8pt', color: '#718096', margin: 0 }}>Documento generato digitalmente.</p>
                  </td>
                  <td style={{ width: '50%', textAlign: 'right' }}>
                    <div style={{ borderTop: '0.5pt solid #2d3748', width: '150pt', display: 'inline-block', marginTop: '20pt', paddingBottom: '10pt' }}>
                      <p style={{ fontSize: '7pt', color: '#4a5568', textAlign: 'center', marginTop: '5pt', textTransform: 'uppercase', fontWeight: 700 }}>Timbro e Firma</p>
                    </div>
                  </td>
                </tr>
              </tbody>
            </table>
          </div>
        </div>
      </div>

      <header className="bg-white border-b border-slate-200 sticky top-0 z-50 px-4 py-4">
        <div className="max-w-4xl mx-auto flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="p-2 rounded-xl bg-slate-900 shadow-md"><Briefcase className="text-white w-5 h-5" /></div>
            <h1 className="text-sm font-black text-slate-800 uppercase italic tracking-tight">Studio Ing. Serra</h1>
          </div>
          <div className="bg-slate-50 px-3 py-1 rounded-full border border-slate-100 flex items-center gap-2">
            <div className="w-1.5 h-1.5 rounded-full bg-emerald-500"></div>
            <span className="text-[10px] font-bold text-slate-400 uppercase">Editor PDF A4</span>
          </div>
        </div>
      </header>

      <main className="flex-1 max-w-4xl mx-auto w-full p-4 sm:p-6 pb-32">
        {step === AppStep.SETUP && (
          <div className="bg-white rounded-[2.5rem] shadow-sm border border-slate-200 p-8 sm:p-12 animate-in fade-in duration-500">
             <div className="mb-10 border-b border-slate-100 pb-6 flex items-center justify-between">
                <div>
                  <h2 className="text-2xl font-black italic tracking-tighter" style={{ color: PRIMARY_COLOR }}>SOPRALLUOGO</h2>
                  <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mt-1">Configurazione Report</p>
                </div>
                <div className="bg-slate-50 p-3 rounded-2xl"><FileCheck className="w-6 h-6 text-slate-300" /></div>
             </div>

             <div className="space-y-8">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                  <div className="space-y-2">
                    <label className="text-[10px] font-black uppercase text-slate-400 ml-1">Condominio *</label>
                    <input type="text" className="w-full px-5 py-4 bg-slate-50 border-2 border-slate-50 rounded-2xl focus:border-[#64a1a4] outline-none font-bold transition-all" value={data.condoName} onChange={(e) => setData({...data, condoName: e.target.value})} placeholder="Es. Condominio Roma" />
                  </div>
                  <div className="space-y-2">
                    <label className="text-[10px] font-black uppercase text-slate-400 ml-1">Data Ispezione *</label>
                    <input type="date" className="w-full px-5 py-4 bg-slate-50 border-2 border-slate-50 rounded-2xl focus:border-[#64a1a4] outline-none font-bold transition-all" value={data.inspectionDate} onChange={(e) => setData({...data, inspectionDate: e.target.value})} />
                  </div>
                </div>

                <div className="space-y-2">
                  <label className="text-[10px] font-black uppercase text-slate-400 ml-1">Logo Studio Professionale</label>
                  <div className="flex flex-col sm:flex-row items-center gap-6">
                    {data.logoUrl && (
                      <div className="relative group animate-in zoom-in">
                        <img src={data.logoUrl} className="w-24 h-24 object-contain border-2 border-slate-100 rounded-2xl p-2 bg-white" alt="Logo Preview" />
                        <button onClick={() => setData({...data, logoUrl: undefined})} className="absolute -top-2 -right-2 bg-red-500 text-white p-1 rounded-full shadow-lg transition-transform hover:scale-110"><X className="w-3 h-3" /></button>
                      </div>
                    )}
                    <label className="flex-1 w-full border-2 border-dashed border-slate-200 rounded-[1.5rem] p-8 flex flex-col items-center justify-center gap-3 cursor-pointer hover:bg-slate-50 hover:border-[#64a1a4] transition-all group">
                      <ImageIcon className="w-8 h-8 text-slate-300 group-hover:text-[#64a1a4]" />
                      <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest text-center">Trascina qui il tuo logo professionale</span>
                      <input type="file" accept="image/*" className="hidden" onChange={handleLogoChange} />
                    </label>
                  </div>
                </div>
             </div>

             <button disabled={!isSetupValid} onClick={() => setStep(AppStep.PHOTOS)} className="w-full mt-10 text-white font-black py-6 rounded-2xl shadow-xl flex items-center justify-center gap-3 uppercase tracking-widest transition-all hover:scale-[1.01] disabled:opacity-50" style={{ backgroundColor: isSetupValid ? PRIMARY_COLOR : "#cbd5e1" }}>
                Prosegui ai Rilievi <ChevronRight className="w-5 h-5" />
             </button>
          </div>
        )}

        {step === AppStep.PHOTOS && (
          <div className="space-y-8 animate-in slide-in-from-bottom-4">
            <div className="flex items-center justify-between bg-white/80 backdrop-blur-md p-4 rounded-2xl border border-slate-200 sticky top-20 z-40 shadow-sm">
              <button onClick={() => setStep(AppStep.SETUP)} className="text-slate-400 hover:text-slate-900 font-black text-[10px] uppercase tracking-widest flex items-center gap-2 transition-colors">
                <ChevronLeft className="w-4 h-4" /> Indietro
              </button>
              <label className="flex items-center gap-2 text-white px-8 py-3.5 rounded-2xl cursor-pointer shadow-lg font-black text-xs uppercase tracking-widest transition-all hover:brightness-110" style={{ backgroundColor: PRIMARY_COLOR }}>
                <Camera className="w-4 h-4" /> Aggiungi Rilievo
                <input type="file" multiple accept="image/*" className="hidden" onChange={handleFileChange} />
              </label>
            </div>

            <div className="grid grid-cols-1 gap-6">
              {data.photos.length === 0 ? (
                <div className="bg-white border-4 border-dashed border-slate-100 rounded-[3rem] p-24 text-center">
                  <Camera className="text-slate-200 w-12 h-12 mx-auto mb-4" />
                  <p className="font-black text-slate-300 uppercase tracking-widest text-[10px]">Scatta o carica le foto dei rilievi</p>
                </div>
              ) : (
                data.photos.map((photo) => (
                  <div key={photo.id} className="bg-white rounded-[2rem] shadow-sm border border-slate-200 overflow-hidden group hover:border-[#64a1a4]/30 transition-all">
                    <div className="flex flex-col md:flex-row">
                      <div className="md:w-1/3 relative bg-slate-100 min-h-[220px]">
                        <img src={photo.url} className="w-full h-full object-cover" alt="Rilievo" />
                        <button onClick={() => removePhoto(photo.id)} className="absolute top-4 right-4 p-2.5 bg-red-500 text-white rounded-xl shadow-lg hover:scale-110 transition-transform"><Trash2 className="w-4 h-4" /></button>
                      </div>
                      <div className="flex-1 p-6 space-y-4">
                        <div className="grid grid-cols-2 gap-4">
                          <div className="space-y-1">
                            <label className="text-[9px] font-black uppercase text-slate-400 block ml-1">Settore</label>
                            <select className="w-full p-3 bg-slate-50 border-2 border-slate-50 rounded-xl text-[10px] font-black uppercase outline-none focus:border-[#64a1a4]" value={photo.category} onChange={(e) => updatePhoto(photo.id, { category: e.target.value })}>
                              {data.availableCategories.map(cat => <option key={cat} value={cat}>{cat}</option>)}
                            </select>
                          </div>
                          <div className="space-y-1">
                            <label className="text-[9px] font-black uppercase text-slate-400 block ml-1">Fornitore di Riferimento</label>
                            <input type="text" placeholder="Ditta..." className="w-full p-3 bg-slate-50 border-2 border-slate-50 rounded-xl text-[10px] font-bold outline-none focus:border-[#64a1a4]" value={photo.supplier} onChange={(e) => updatePhoto(photo.id, { supplier: e.target.value })} />
                          </div>
                        </div>
                        <div className="relative">
                          <label className="text-[9px] font-black uppercase text-slate-400 block mb-1 ml-1">Caratteristica Difetto</label>
                          <textarea placeholder="Descrivi il problema..." className="w-full p-4 bg-slate-50 border-2 border-slate-50 rounded-2xl text-xs font-medium min-h-[100px] resize-none focus:border-[#64a1a4] outline-none" value={photo.issue} onChange={(e) => updatePhoto(photo.id, { issue: e.target.value })} />
                          <button onClick={() => handleAIEnhance(photo)} disabled={photo.isLoading || !photo.issue} className="absolute bottom-3 right-3 p-2.5 bg-white border border-slate-100 rounded-xl shadow-sm text-[#64a1a4] hover:shadow-md transition-all">
                            {photo.isLoading ? <Loader2 className="animate-spin h-4 w-4" /> : <Wand2 className="w-4 h-4" />}
                          </button>
                        </div>
                        {photo.aiPolishedIssue && (
                          <div className="p-4 bg-slate-900 rounded-2xl animate-in slide-in-from-top-2">
                            <div className="flex items-center justify-between mb-2">
                              <p className="text-[9px] font-black text-[#64a1a4] uppercase flex items-center gap-2"><Sparkles className="w-3 h-3" /> Report IA</p>
                              <button onClick={() => updatePhoto(photo.id, { issue: photo.aiPolishedIssue, aiPolishedIssue: undefined })} className="text-[9px] font-black text-white bg-white/10 px-2 py-1 rounded-lg uppercase">Applica</button>
                            </div>
                            <p className="text-[11px] text-slate-300 italic leading-relaxed">{photo.aiPolishedIssue}</p>
                          </div>
                        )}
                      </div>
                    </div>
                  </div>
                ))
              )}
            </div>

            <button disabled={data.photos.length === 0} onClick={handleGenerateReport} className="w-full bg-slate-900 text-white font-black py-7 rounded-[2rem] shadow-2xl flex items-center justify-center gap-4 uppercase tracking-[0.2em] transition-all hover:scale-[1.01] active:scale-95">
              Genera Relazione Finale <FileText className="w-6 h-6" />
            </button>
          </div>
        )}

        {step === AppStep.REPORT && (
          <div className="space-y-8 animate-in fade-in duration-500">
             <div className="fixed bottom-8 left-1/2 -translate-x-1/2 z-[100] w-full max-w-xs px-4">
              <button onClick={() => setShowFilePrompt(true)} disabled={isExporting} className="w-full bg-emerald-600 text-white p-5 rounded-full shadow-2xl flex items-center justify-center gap-3 hover:scale-105 active:scale-95 transition-all">
                <Download className="w-6 h-6" />
                <span className="font-black text-xs uppercase tracking-widest">Scarica Verbale PDF</span>
              </button>
            </div>

            <button onClick={() => setStep(AppStep.PHOTOS)} className="text-slate-400 hover:text-slate-900 font-black text-[10px] uppercase tracking-widest flex items-center gap-2 transition-colors">
              <ChevronLeft className="w-4 h-4" /> Torna ai Rilievi
            </button>

            <div className="bg-white p-8 sm:p-12 shadow-sm rounded-[2.5rem] border border-slate-100">
              <div className="flex items-center gap-2 mb-6">
                <div className="bg-[#64a1a4]/10 p-2 rounded-xl"><Sparkles className="w-4 h-4 text-[#64a1a4]" /></div>
                <h3 className="text-[11px] font-black uppercase text-[#64a1a4] tracking-widest">Relazione Conclusiva (Ing. Serra)</h3>
              </div>

              {isGeneratingSummary ? (
                 <div className="p-12 bg-slate-50 rounded-3xl text-center border-2 border-dashed border-slate-100">
                   <Loader2 className="animate-spin w-8 h-8 mx-auto text-[#64a1a4] mb-4" />
                   <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Sintesi rilievi in corso...</p>
                 </div>
              ) : (
                <div className="space-y-4">
                  <textarea 
                    className="w-full bg-slate-900 p-8 rounded-[2rem] text-white text-lg font-light italic leading-relaxed border-none resize-none outline-none"
                    value={summary}
                    onChange={(e) => {
                      setSummary(e.target.value);
                      e.target.style.height = 'auto';
                      e.target.style.height = e.target.scrollHeight + 'px';
                    }}
                    rows={12}
                  />
                  <p className="text-center text-[9px] font-bold text-slate-400 uppercase tracking-widest">Il testo è editabile prima dell'esportazione finale</p>
                </div>
              )}
            </div>

            {/* LISTA RILIEVI ANTEPRIMA */}
            <div className="space-y-4">
              <h3 className="text-[11px] font-black uppercase text-slate-400 tracking-[0.2em] px-6">Anteprima Rilievi nel Report</h3>
              {data.photos.map((photo, idx) => (
                <div key={photo.id} className="bg-white border border-slate-100 rounded-3xl p-6 flex gap-6 items-center shadow-sm hover:border-[#64a1a4]/30 transition-all">
                  <div className="w-20 h-20 rounded-2xl overflow-hidden bg-slate-100 flex-shrink-0">
                    <img src={photo.url} className="w-full h-full object-cover" alt="Thumb" />
                  </div>
                  <div className="flex-1">
                    <div className="flex items-center gap-2 mb-1">
                      <span className="text-[10px] font-black text-[#64a1a4] uppercase">{photo.category}</span>
                      <span className="text-[10px] font-bold text-slate-300">/</span>
                      <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">{photo.supplier || "Ditta N/D"}</span>
                    </div>
                    <p className="text-xs text-slate-600 font-medium italic line-clamp-2">
                      {photo.aiPolishedIssue || photo.issue || "Nessuna nota tecnica."}
                    </p>
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}
      </main>

      {showFilePrompt && (
        <div className="fixed inset-0 z-[500] flex items-center justify-center p-4 bg-slate-900/80 backdrop-blur-md animate-in fade-in">
          <div className="bg-white w-full max-w-sm rounded-[2.5rem] shadow-2xl p-10 space-y-8 animate-in zoom-in-95">
            <div className="flex justify-between items-center">
              <div className="bg-slate-50 p-4 rounded-2xl"><FileCheck className="w-8 h-8 text-[#64a1a4]" /></div>
              <button onClick={() => setShowFilePrompt(false)} className="text-slate-400 p-2 hover:bg-slate-100 rounded-full transition-colors"><X className="w-6 h-6" /></button>
            </div>
            <div className="space-y-2">
              <h2 className="text-2xl font-black text-slate-900 tracking-tight">Scarica Report</h2>
              <p className="text-xs text-slate-500 font-medium italic">Il documento sarà ottimizzato per la stampa A4 professionale.</p>
            </div>
            <div className="space-y-1.5">
              <label className="text-[10px] font-black uppercase text-[#64a1a4] tracking-widest ml-1">Nome del Documento</label>
              <input 
                autoFocus
                type="text" 
                className="w-full bg-slate-50 border-2 border-slate-100 rounded-2xl px-6 py-5 outline-none focus:border-[#64a1a4] font-black text-slate-800"
                value={customFileName}
                onChange={(e) => setCustomFileName(e.target.value)}
              />
            </div>
            <button onClick={executeSavePdf} className="w-full bg-slate-900 text-white font-black py-6 rounded-2xl shadow-xl flex items-center justify-center gap-4 hover:bg-black transition-all transform active:scale-95">
              CONFERMA DOWNLOAD <Download className="w-6 h-6" />
            </button>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

import React, { useState, useMemo, useEffect, useRef } from 'react';
import { 
  Camera, 
  Trash2, 
  ChevronRight, 
  ChevronLeft, 
  FileText, 
  Wand2,
  Image as ImageIcon,
  Loader2,
  Sparkles,
  Briefcase,
  AlertCircle,
  X,
  Download,
  FileCheck,
  CheckCircle,
  Key,
  Layout
} from 'lucide-react';
import { AppStep, InspectionData, InspectionPhoto } from './types';
import { professionalizeDescription, generateExecutiveSummary, AIError } from './services/geminiService';

const STUDIO_NAME = "Studio Amministrazioni Condominiali Ing. Serra";
const STUDIO_TAGLINE = "il condominio trasparente: tutto limpido, tutto evidente";
const PRIMARY_COLOR = "#64a1a4";
const DEFAULT_CATEGORIES = ['Strutturale', 'Impianto Idraulico', 'Impianto Elettrico', 'Estetica/Facciata', 'Aree Comuni', 'Sicurezza'];

declare var html2pdf: any;
declare var window: any;

const App: React.FC = () => {
  const [step, setStep] = useState<AppStep>(AppStep.SETUP);
  const [isExporting, setIsExporting] = useState(false);
  const [showFilePrompt, setShowFilePrompt] = useState(false);
  const [customFileName, setCustomFileName] = useState('');
  const [apiQuotaError, setApiQuotaError] = useState(false);

  const [data, setData] = useState<InspectionData>({
    condoName: '',
    inspectionDate: new Date().toISOString().split('T')[0],
    logoUrl: undefined,
    technicalNotes: 'Sopralluogo tecnico effettuato.',
    photos: [],
    availableCategories: DEFAULT_CATEGORIES
  });

  const [summary, setSummary] = useState('');
  const [isGeneratingSummary, setIsGeneratingSummary] = useState(false);
  const pdfRef = useRef<HTMLDivElement>(null);

  const isSetupValid = useMemo(() => {
    return data.condoName.trim().length > 0 && data.inspectionDate.length > 0;
  }, [data.condoName, data.inspectionDate]);

  useEffect(() => {
    if (data.condoName && !customFileName) {
      const sanitized = data.condoName.replace(/[^a-z0-9]/gi, '_').toLowerCase();
      setCustomFileName(`verbale_${sanitized}_${data.inspectionDate}`);
    }
  }, [data.condoName, data.inspectionDate]);

  const handleOpenApiKeyDialog = async () => {
    try {
      await window.aistudio.openSelectKey();
      setApiQuotaError(false);
    } catch (e) {
      console.error("Failed to open key selector", e);
    }
  };

  const fileToBase64 = (file: File): Promise<string> => {
    return new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.readAsDataURL(file);
      reader.onload = () => resolve((reader.result as string).split(',')[1]);
      reader.onerror = error => reject(error);
    });
  };

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files) {
      const newFiles = Array.from(e.target.files) as File[];
      const newPhotosPromises = newFiles.map(async (file) => {
        const base64 = await fileToBase64(file);
        return {
          id: Math.random().toString(36).substr(2, 9),
          url: URL.createObjectURL(file),
          base64Data: base64,
          mimeType: file.type,
          issue: '',
          supplier: '',
          category: data.availableCategories[0],
        };
      });
      const newPhotos = await Promise.all(newPhotosPromises);
      setData(prev => ({ ...prev, photos: [...prev.photos, ...newPhotos] }));
    }
  };

  const handleLogoChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files?.[0]) {
      const url = URL.createObjectURL(e.target.files[0]);
      setData(prev => ({ ...prev, logoUrl: url }));
    }
  };

  const updatePhoto = (id: string, updates: Partial<InspectionPhoto>) => {
    setData(prev => ({
      ...prev,
      photos: prev.photos.map(p => p.id === id ? { ...p, ...updates } : p)
    }));
  };

  const removePhoto = (id: string) => {
    setData(prev => ({
      ...prev,
      photos: prev.photos.filter(p => p.id !== id)
    }));
  };

  const handleAIEnhance = async (photo: InspectionPhoto) => {
    updatePhoto(photo.id, { isLoading: true });
    try {
      const polished = await professionalizeDescription(photo.issue, photo.base64Data, photo.mimeType);
      updatePhoto(photo.id, { aiPolishedIssue: polished, isLoading: false });
    } catch (err: any) {
      updatePhoto(photo.id, { isLoading: false });
      if (err instanceof AIError && err.status === "QUOTA_EXCEEDED") {
        setApiQuotaError(true);
      }
    }
  };

  const handleGenerateReport = async () => {
    setStep(AppStep.REPORT);
    setIsGeneratingSummary(true);
    const issues = data.photos.map(p => p.aiPolishedIssue || p.issue).filter(Boolean);
    try {
      const execSummary = await generateExecutiveSummary(data.condoName, issues);
      setSummary(execSummary);
    } catch (err: any) {
      if (err instanceof AIError && err.status === "QUOTA_EXCEEDED") {
        setApiQuotaError(true);
        setSummary("Sopralluogo tecnico effettuato. Consultare l'elenco dei rilievi per i dettagli.");
      }
    } finally {
      setIsGeneratingSummary(false);
    }
  };

  const executeSavePdf = async () => {
    const element = pdfRef.current;
    if (!element) return;

    setShowFilePrompt(false);
    setIsExporting(true);

    // Aspetta che React abbia finito di iniettare i dati nel DOM del template
    await new Promise(resolve => setTimeout(resolve, 800));

    const images = Array.from(element.getElementsByTagName('img'));
    const loadPromises = images.map(img => {
      if (img.complete) return Promise.resolve();
      return new Promise(resolve => {
        img.onload = resolve;
        img.onerror = resolve;
      });
    });
    await Promise.all(loadPromises);

    const opt = {
      margin: 0,
      filename: `${customFileName}.pdf`,
      image: { type: 'jpeg', quality: 0.98 },
      html2canvas: { 
        scale: 2, 
        useCORS: true, 
        backgroundColor: '#ffffff',
        logging: false,
        scrollY: 0, // Evita che lo scroll attuale influenzi la cattura
        scrollX: 0
      },
      jsPDF: { unit: 'mm', format: 'a4', orientation: 'portrait' },
      pagebreak: { mode: ['css', 'legacy'] }
    };

    try {
      await html2pdf().set(opt).from(element).save();
    } catch (err) {
      console.error("Errore PDF:", err);
      alert("Impossibile generare il PDF. Riprova.");
    } finally {
      setIsExporting(false);
    }
  };

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col">

      {apiQuotaError && (
        <div className="bg-red-50 border-b border-red-100 px-4 py-3 sticky top-0 z-[100] animate-in slide-in-from-top">
          <div className="max-w-4xl mx-auto flex flex-col sm:flex-row items-center justify-between gap-3">
            <div className="flex items-center gap-2 text-red-700 text-xs font-bold uppercase tracking-tight">
              <AlertCircle className="w-4 h-4" />
              <span>Limite IA. Configura la tua chiave API per continuare.</span>
            </div>
            <button onClick={handleOpenApiKeyDialog} className="bg-red-600 text-white px-4 py-1.5 rounded-lg text-[10px] font-black uppercase flex items-center gap-2 hover:bg-red-700">
              <Key className="w-3 h-3" /> Chiave API
            </button>
          </div>
        </div>
      )}

      {isExporting && (
        <div className="fixed inset-0 z-[600] bg-white/95 flex flex-col items-center justify-center p-10 text-center">
          <div className="spinner-ring mb-6"></div>
          <h2 className="text-xl font-black text-slate-900 uppercase tracking-widest">Esportazione PDF...</h2>
          <p className="text-slate-500 text-sm mt-2 font-medium">Stiamo assemblando tutte le foto e le analisi tecniche.</p>
        </div>
      )}

      {/* STRUTTURA PDF MIGLIORATA PER HTML2PDF */}
      <div id="pdf-container-wrapper">
        <div ref={pdfRef} id="pdf-template">
          <div className="pdf-header">
            <div style={{ width: '65%' }}>
              {data.logoUrl && <img src={data.logoUrl} style={{ height: '55pt', marginBottom: '8pt', objectFit: 'contain' }} alt="Logo" />}
              <h1 style={{ margin: 0, fontSize: '18pt', fontWeight: 900, color: PRIMARY_COLOR }}>STUDIO ING. SERRA</h1>
              <p style={{ margin: 0, fontWeight: 700, fontSize: '9pt', color: '#333' }}>{STUDIO_NAME}</p>
              <p style={{ margin: 0, fontSize: '7.5pt', color: '#666' }}>{STUDIO_TAGLINE}</p>
            </div>
            <div style={{ textAlign: 'right', width: '35%' }}>
              <h2 style={{ margin: 0, fontSize: '11pt', fontWeight: 900, textTransform: 'uppercase' }}>Verbale Sopralluogo</h2>
              <p style={{ margin: 0, fontSize: '8.5pt', color: '#444' }}>Data: {new Date(data.inspectionDate).toLocaleDateString('it-IT')}</p>
              <div style={{ marginTop: '8pt', padding: '4pt', background: '#f8fafc', border: '0.5pt solid #eee' }}>
                <p style={{ margin: 0, fontSize: '9pt', fontWeight: 900, color: PRIMARY_COLOR }}>{data.condoName.toUpperCase()}</p>
              </div>
            </div>
          </div>

          <div className="pdf-section-title">Relazione Tecnica Conclusiva</div>
          <div style={{ fontSize: '10.5pt', lineHeight: '1.5', textAlign: 'justify', whiteSpace: 'pre-wrap', marginBottom: '25pt', color: '#1a1a1a' }}>
            {summary || "Nessuna relazione conclusiva specificata."}
          </div>

          <div className="pdf-section-title">Elenco Rilievi Fotografici</div>
          {data.photos.map((photo, idx) => (
            <div key={photo.id} className="pdf-item">
              <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '8pt', borderBottom: '0.5pt solid #f1f5f9', paddingBottom: '4pt' }}>
                <span style={{ fontWeight: 900, fontSize: '10.5pt', color: '#334155' }}>RILIEVO {idx + 1} - {photo.category.toUpperCase()}</span>
                <span style={{ fontWeight: 700, fontSize: '8.5pt', color: '#94a3b8' }}>RIF: {photo.supplier || "DA DEFINIRE"}</span>
              </div>
              <div className="pdf-photo-container">
                <img src={photo.url} className="pdf-photo" alt={`Rilievo ${idx+1}`} />
              </div>
              <div className="pdf-desc-box">
                <p style={{ fontSize: '7.5pt', fontWeight: 900, color: PRIMARY_COLOR, margin: '0 0 3pt 0', textTransform: 'uppercase' }}>Analisi Tecnica:</p>
                <p style={{ fontSize: '10pt', margin: 0, fontStyle: 'italic', lineHeight: '1.4', color: '#334155' }}>
                  {photo.aiPolishedIssue || photo.issue || "Nessuna nota tecnica inserita per questo rilievo."}
                </p>
              </div>
            </div>
          ))}

          <div className="pdf-footer">
            <table style={{ width: '100%' }}>
              <tbody>
                <tr>
                  <td style={{ width: '60%' }}>
                    <p style={{ fontWeight: 900, fontSize: '9.5pt', margin: 0 }}>{STUDIO_NAME}</p>
                    <p style={{ fontSize: '7.5pt', color: '#94a3b8', margin: 0 }}>Documento tecnico originale non modificabile.</p>
                  </td>
                  <td style={{ width: '40%', textAlign: 'right' }}>
                    <div style={{ borderTop: '0.5pt solid #334155', width: '130pt', display: 'inline-block', marginTop: '15pt' }}>
                      <p style={{ fontSize: '7pt', color: '#64748b', textAlign: 'center', marginTop: '3pt', textTransform: 'uppercase', fontWeight: 800 }}>Firma Professionale</p>
                    </div>
                  </td>
                </tr>
              </tbody>
            </table>
          </div>
        </div>
      </div>

      <header className="bg-white border-b border-slate-200 sticky top-0 z-50 px-4 py-4">
        <div className="max-w-4xl mx-auto flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="p-2 rounded-xl bg-slate-900 shadow-md"><Briefcase className="text-white w-5 h-5" /></div>
            <h1 className="text-sm font-black text-slate-800 uppercase italic tracking-tight">Studio Ing. Serra</h1>
          </div>
          <div className="bg-slate-50 px-3 py-1 rounded-full border border-slate-100 flex items-center gap-2">
            <div className="w-1.5 h-1.5 rounded-full bg-emerald-500"></div>
            <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">A4 Report Engine</span>
          </div>
        </div>
      </header>

      <main className="flex-1 max-w-4xl mx-auto w-full p-4 sm:p-6 pb-32">
        {step === AppStep.SETUP && (
          <div className="bg-white rounded-[2.5rem] shadow-sm border border-slate-200 p-8 sm:p-12 animate-in fade-in duration-500">
             <div className="mb-10 border-b border-slate-100 pb-6 flex items-center justify-between">
                <div>
                  <h2 className="text-2xl font-black italic tracking-tighter" style={{ color: PRIMARY_COLOR }}>SOPRALLUOGO</h2>
                  <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mt-1">Dati Condominio</p>
                </div>
                <div className="bg-slate-50 p-3 rounded-2xl"><FileCheck className="w-6 h-6 text-slate-300" /></div>
             </div>

             <div className="space-y-8">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                  <div className="space-y-2">
                    <label className="text-[10px] font-black uppercase text-slate-400 ml-1">Nome Condominio *</label>
                    <input type="text" className="w-full px-5 py-4 bg-slate-50 border-2 border-slate-50 rounded-2xl focus:border-[#64a1a4] outline-none font-bold transition-all" value={data.condoName} onChange={(e) => setData({...data, condoName: e.target.value})} placeholder="Es. Condominio Italia" />
                  </div>
                  <div className="space-y-2">
                    <label className="text-[10px] font-black uppercase text-slate-400 ml-1">Data *</label>
                    <input type="date" className="w-full px-5 py-4 bg-slate-50 border-2 border-slate-50 rounded-2xl focus:border-[#64a1a4] outline-none font-bold transition-all" value={data.inspectionDate} onChange={(e) => setData({...data, inspectionDate: e.target.value})} />
                  </div>
                </div>

                <div className="space-y-2">
                  <label className="text-[10px] font-black uppercase text-slate-400 ml-1">Logo Studio</label>
                  <div className="flex flex-col sm:flex-row items-center gap-6">
                    {data.logoUrl && (
                      <div className="relative group animate-in zoom-in">
                        <img src={data.logoUrl} className="w-24 h-24 object-contain border-2 border-slate-100 rounded-2xl p-2 bg-white" alt="Preview" />
                        <button onClick={() => setData({...data, logoUrl: undefined})} className="absolute -top-2 -right-2 bg-red-500 text-white p-1 rounded-full shadow-lg transition-transform hover:scale-110"><X className="w-3 h-3" /></button>
                      </div>
                    )}
                    <label className="flex-1 w-full border-2 border-dashed border-slate-200 rounded-[1.5rem] p-8 flex flex-col items-center justify-center gap-3 cursor-pointer hover:bg-slate-50 hover:border-[#64a1a4] transition-all group">
                      <ImageIcon className="w-8 h-8 text-slate-300 group-hover:text-[#64a1a4]" />
                      <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest text-center">Carica logo professionale</span>
                      <input type="file" accept="image/*" className="hidden" onChange={handleLogoChange} />
                    </label>
                  </div>
                </div>
             </div>

             <button disabled={!isSetupValid} onClick={() => setStep(AppStep.PHOTOS)} className="w-full mt-10 text-white font-black py-6 rounded-2xl shadow-xl flex items-center justify-center gap-3 uppercase tracking-widest transition-all hover:scale-[1.01] disabled:opacity-50" style={{ backgroundColor: isSetupValid ? PRIMARY_COLOR : "#cbd5e1" }}>
                VAI AI RILIEVI <ChevronRight className="w-5 h-5" />
             </button>
          </div>
        )}

        {step === AppStep.PHOTOS && (
          <div className="space-y-8 animate-in slide-in-from-bottom-4">
            <div className="flex items-center justify-between bg-white/80 backdrop-blur-md p-4 rounded-2xl border border-slate-200 sticky top-20 z-40 shadow-sm">
              <button onClick={() => setStep(AppStep.SETUP)} className="text-slate-400 hover:text-slate-900 font-black text-[10px] uppercase tracking-widest flex items-center gap-2">
                <ChevronLeft className="w-4 h-4" /> Setup
              </button>
              <label className="flex items-center gap-2 text-white px-8 py-3.5 rounded-2xl cursor-pointer shadow-lg font-black text-xs uppercase tracking-widest transition-all hover:brightness-110" style={{ backgroundColor: PRIMARY_COLOR }}>
                <Camera className="w-4 h-4" /> Aggiungi Foto
                <input type="file" multiple accept="image/*" className="hidden" onChange={handleFileChange} />
              </label>
            </div>

            <div className="grid grid-cols-1 gap-6">
              {data.photos.length === 0 ? (
                <div className="bg-white border-4 border-dashed border-slate-100 rounded-[3rem] p-24 text-center">
                  <Camera className="text-slate-200 w-12 h-12 mx-auto mb-4" />
                  <p className="font-black text-slate-300 uppercase tracking-widest text-[10px]">Aggiungi le foto del sopralluogo per iniziare</p>
                </div>
              ) : (
                data.photos.map((photo) => (
                  <div key={photo.id} className="bg-white rounded-[2rem] shadow-sm border border-slate-200 overflow-hidden group hover:border-[#64a1a4]/30 transition-all">
                    <div className="flex flex-col md:flex-row">
                      <div className="md:w-1/3 relative bg-slate-100 min-h-[220px]">
                        <img src={photo.url} className="w-full h-full object-cover" alt="Rilievo" />
                        <button onClick={() => removePhoto(photo.id)} className="absolute top-4 right-4 p-2.5 bg-red-500 text-white rounded-xl shadow-lg hover:scale-110 transition-transform"><Trash2 className="w-4 h-4" /></button>
                      </div>
                      <div className="flex-1 p-6 space-y-4">
                        <div className="grid grid-cols-2 gap-4">
                          <div className="space-y-1">
                            <label className="text-[9px] font-black uppercase text-slate-400 block ml-1">Categoria</label>
                            <select className="w-full p-3 bg-slate-50 border-2 border-slate-50 rounded-xl text-[10px] font-black uppercase outline-none focus:border-[#64a1a4]" value={photo.category} onChange={(e) => updatePhoto(photo.id, { category: e.target.value })}>
                              {data.availableCategories.map(cat => <option key={cat} value={cat}>{cat}</option>)}
                            </select>
                          </div>
                          <div className="space-y-1">
                            <label className="text-[9px] font-black uppercase text-slate-400 block ml-1">Fornitore</label>
                            <input type="text" placeholder="Ditta..." className="w-full p-3 bg-slate-50 border-2 border-slate-50 rounded-xl text-[10px] font-bold outline-none focus:border-[#64a1a4]" value={photo.supplier} onChange={(e) => updatePhoto(photo.id, { supplier: e.target.value })} />
                          </div>
                        </div>
                        <div className="relative">
                          <label className="text-[9px] font-black uppercase text-slate-400 block mb-1 ml-1">Problema Evidenziato</label>
                          <textarea placeholder="Descrivi il difetto..." className="w-full p-4 bg-slate-50 border-2 border-slate-50 rounded-2xl text-xs font-medium min-h-[100px] resize-none focus:border-[#64a1a4] outline-none" value={photo.issue} onChange={(e) => updatePhoto(photo.id, { issue: e.target.value })} />
                          <button onClick={() => handleAIEnhance(photo)} disabled={photo.isLoading || !photo.issue} className="absolute bottom-3 right-3 p-2.5 bg-white border border-slate-100 rounded-xl shadow-sm text-[#64a1a4] hover:shadow-md transition-all">
                            {photo.isLoading ? <Loader2 className="animate-spin h-4 w-4" /> : <Wand2 className="w-4 h-4" />}
                          </button>
                        </div>
                        {photo.aiPolishedIssue && (
                          <div className="p-4 bg-slate-900 rounded-2xl animate-in slide-in-from-top-2">
                            <div className="flex items-center justify-between mb-2">
                              <p className="text-[9px] font-black text-[#64a1a4] uppercase flex items-center gap-2"><Sparkles className="w-3 h-3" /> Analisi IA</p>
                              <button onClick={() => updatePhoto(photo.id, { issue: photo.aiPolishedIssue, aiPolishedIssue: undefined })} className="text-[9px] font-black text-white bg-white/10 px-2 py-1 rounded-lg uppercase">Applica</button>
                            </div>
                            <p className="text-[11px] text-slate-300 italic leading-relaxed">{photo.aiPolishedIssue}</p>
                          </div>
                        )}
                      </div>
                    </div>
                  </div>
                ))
              )}
            </div>

            <button disabled={data.photos.length === 0} onClick={handleGenerateReport} className="w-full bg-slate-900 text-white font-black py-7 rounded-[2rem] shadow-2xl flex items-center justify-center gap-4 uppercase tracking-[0.2em] transition-all hover:scale-[1.01]">
              Genera Report Finale <FileText className="w-6 h-6" />
            </button>
          </div>
        )}

        {step === AppStep.REPORT && (
          <div className="space-y-8 animate-in fade-in duration-500">
             <div className="fixed bottom-8 left-1/2 -translate-x-1/2 z-[100] w-full max-w-xs px-4">
              <button onClick={() => setShowFilePrompt(true)} disabled={isExporting} className="w-full bg-emerald-600 text-white p-5 rounded-full shadow-2xl flex items-center justify-center gap-3 hover:scale-105 transition-all">
                <Download className="w-6 h-6" />
                <span className="font-black text-xs uppercase tracking-widest">Esporta Verbale PDF</span>
              </button>
            </div>

            <button onClick={() => setStep(AppStep.PHOTOS)} className="text-slate-400 hover:text-slate-900 font-black text-[10px] uppercase tracking-widest flex items-center gap-2">
              <ChevronLeft className="w-4 h-4" /> Rilievi
            </button>

            <div className="bg-white p-8 sm:p-12 shadow-sm rounded-[2.5rem] border border-slate-100">
              <div className="flex items-center gap-2 mb-6">
                <div className="bg-[#64a1a4]/10 p-2 rounded-xl"><Sparkles className="w-4 h-4 text-[#64a1a4]" /></div>
                <h3 className="text-[11px] font-black uppercase text-[#64a1a4] tracking-widest">Sintesi Relazione</h3>
              </div>

              {isGeneratingSummary ? (
                 <div className="p-12 bg-slate-50 rounded-3xl text-center border-2 border-dashed border-slate-100">
                   <Loader2 className="animate-spin w-8 h-8 mx-auto text-[#64a1a4] mb-4" />
                   <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">IA al lavoro sulla sintesi...</p>
                 </div>
              ) : (
                <textarea 
                  className="w-full bg-slate-900 p-8 rounded-[2rem] text-white text-lg font-light italic leading-relaxed border-none resize-none outline-none"
                  value={summary}
                  onChange={(e) => {
                    setSummary(e.target.value);
                    e.target.style.height = 'auto';
                    e.target.style.height = e.target.scrollHeight + 'px';
                  }}
                  rows={10}
                />
              )}
            </div>

            <div className="space-y-4">
              <h3 className="text-[11px] font-black uppercase text-slate-400 tracking-[0.2em] px-6">Elenco Rilievi (Anteprima PDF)</h3>
              {data.photos.map((photo, idx) => (
                <div key={photo.id} className="bg-white border border-slate-100 rounded-3xl p-6 flex gap-6 items-center shadow-sm">
                  <div className="w-20 h-20 rounded-2xl overflow-hidden bg-slate-100 flex-shrink-0">
                    <img src={photo.url} className="w-full h-full object-cover" alt="Rilievo" />
                  </div>
                  <div className="flex-1">
                    <div className="flex items-center gap-2 mb-1">
                      <span className="text-[10px] font-black text-[#64a1a4] uppercase">{photo.category}</span>
                      <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">| {photo.supplier || "Nessun fornitore"}</span>
                    </div>
                    <p className="text-xs text-slate-600 font-medium italic line-clamp-2">
                      {photo.aiPolishedIssue || photo.issue || "Nessun commento."}
                    </p>
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}
      </main>

      {showFilePrompt && (
        <div className="fixed inset-0 z-[500] flex items-center justify-center p-4 bg-slate-900/80 backdrop-blur-md animate-in fade-in">
          <div className="bg-white w-full max-w-sm rounded-[2.5rem] shadow-2xl p-10 space-y-8 animate-in zoom-in-95">
            <div className="flex justify-between items-center">
              <div className="bg-slate-50 p-4 rounded-2xl"><FileCheck className="w-8 h-8 text-[#64a1a4]" /></div>
              <button onClick={() => setShowFilePrompt(false)} className="text-slate-400 p-2 hover:bg-slate-100 rounded-full transition-colors"><X className="w-6 h-6" /></button>
            </div>
            <div className="space-y-2">
              <h2 className="text-2xl font-black text-slate-900 tracking-tight">Scarica PDF</h2>
              <p className="text-xs text-slate-500 font-medium italic">Il file verrà generato in formato A4 professionale.</p>
            </div>
            <div className="space-y-1.5">
              <label className="text-[10px] font-black uppercase text-[#64a1a4] tracking-widest ml-1">Nome Documento</label>
              <input 
                autoFocus
                type="text" 
                className="w-full bg-slate-50 border-2 border-slate-100 rounded-2xl px-6 py-5 outline-none focus:border-[#64a1a4] font-black text-slate-800"
                value={customFileName}
                onChange={(e) => setCustomFileName(e.target.value)}
              />
            </div>
            <button onClick={executeSavePdf} className="w-full bg-slate-900 text-white font-black py-6 rounded-2xl shadow-xl flex items-center justify-center gap-4 hover:bg-black transition-all transform active:scale-95">
              CONFERMA DOWNLOAD <Download className="w-6 h-6" />
            </button>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

import React, { useState, useMemo, useEffect, useRef } from 'react';
import { 
  Camera, 
  Trash2, 
  ChevronRight, 
  ChevronLeft, 
  FileText, 
  Wand2,
  Image as ImageIcon,
  Loader2,
  Sparkles,
  Briefcase,
  AlertCircle,
  X,
  Download,
  FileCheck,
  CheckCircle,
  Key,
  Layout
} from 'lucide-react';
import { AppStep, InspectionData, InspectionPhoto } from './types';
import { professionalizeDescription, generateExecutiveSummary, AIError } from './services/geminiService';

const STUDIO_NAME = "Studio Amministrazioni Condominiali Ing. Serra";
const STUDIO_TAGLINE = "il condominio trasparente: tutto limpido, tutto evidente";
const PRIMARY_COLOR = "#64a1a4";
const DEFAULT_CATEGORIES = ['Strutturale', 'Impianto Idraulico', 'Impianto Elettrico', 'Estetica/Facciata', 'Aree Comuni', 'Sicurezza'];

declare var html2pdf: any;
declare var window: any;

const App: React.FC = () => {
  const [step, setStep] = useState<AppStep>(AppStep.SETUP);
  const [isExporting, setIsExporting] = useState(false);
  const [showFilePrompt, setShowFilePrompt] = useState(false);
  const [customFileName, setCustomFileName] = useState('');
  const [apiQuotaError, setApiQuotaError] = useState(false);

  const [data, setData] = useState<InspectionData>({
    condoName: '',
    inspectionDate: new Date().toISOString().split('T')[0],
    logoUrl: undefined,
    technicalNotes: 'Sopralluogo tecnico effettuato.',
    photos: [],
    availableCategories: DEFAULT_CATEGORIES
  });

  const [summary, setSummary] = useState('');
  const [isGeneratingSummary, setIsGeneratingSummary] = useState(false);
  const pdfRef = useRef<HTMLDivElement>(null);

  const isSetupValid = useMemo(() => {
    return data.condoName.trim().length > 0 && data.inspectionDate.length > 0;
  }, [data.condoName, data.inspectionDate]);

  useEffect(() => {
    if (data.condoName && !customFileName) {
      const sanitized = data.condoName.replace(/[^a-z0-9]/gi, '_').toLowerCase();
      setCustomFileName(`verbale_${sanitized}_${data.inspectionDate}`);
    }
  }, [data.condoName, data.inspectionDate]);

  const handleOpenApiKeyDialog = async () => {
    try {
      await window.aistudio.openSelectKey();
      setApiQuotaError(false);
    } catch (e) {
      console.error("Failed to open key selector", e);
    }
  };

  const fileToBase64 = (file: File): Promise<string> => {
    return new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.readAsDataURL(file);
      reader.onload = () => resolve((reader.result as string).split(',')[1]);
      reader.onerror = error => reject(error);
    });
  };

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files) {
      const newFiles = Array.from(e.target.files) as File[];
      const newPhotosPromises = newFiles.map(async (file) => {
        const base64 = await fileToBase64(file);
        return {
          id: Math.random().toString(36).substr(2, 9),
          url: URL.createObjectURL(file),
          base64Data: base64,
          mimeType: file.type,
          issue: '',
          supplier: '',
          category: data.availableCategories[0],
        };
      });
      const newPhotos = await Promise.all(newPhotosPromises);
      setData(prev => ({ ...prev, photos: [...prev.photos, ...newPhotos] }));
    }
  };

  const handleLogoChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files?.[0]) {
      const url = URL.createObjectURL(e.target.files[0]);
      setData(prev => ({ ...prev, logoUrl: url }));
    }
  };

  const updatePhoto = (id: string, updates: Partial<InspectionPhoto>) => {
    setData(prev => ({
      ...prev,
      photos: prev.photos.map(p => p.id === id ? { ...p, ...updates } : p)
    }));
  };

  const removePhoto = (id: string) => {
    setData(prev => ({
      ...prev,
      photos: prev.photos.filter(p => p.id !== id)
    }));
  };

  const handleAIEnhance = async (photo: InspectionPhoto) => {
    updatePhoto(photo.id, { isLoading: true });
    try {
      const polished = await professionalizeDescription(photo.issue, photo.base64Data, photo.mimeType);
      updatePhoto(photo.id, { aiPolishedIssue: polished, isLoading: false });
    } catch (err: any) {
      updatePhoto(photo.id, { isLoading: false });
      if (err instanceof AIError && err.status === "QUOTA_EXCEEDED") {
        setApiQuotaError(true);
      }
    }
  };

  const handleGenerateReport = async () => {
    setStep(AppStep.REPORT);
    setIsGeneratingSummary(true);
    const issues = data.photos.map(p => p.aiPolishedIssue || p.issue).filter(Boolean);
    try {
      const execSummary = await generateExecutiveSummary(data.condoName, issues);
      setSummary(execSummary);
    } catch (err: any) {
      if (err instanceof AIError && err.status === "QUOTA_EXCEEDED") {
        setApiQuotaError(true);
        setSummary("Sopralluogo tecnico effettuato. Consultare l'elenco dei rilievi per i dettagli.");
      }
    } finally {
      setIsGeneratingSummary(false);
    }
  };

  const executeSavePdf = async () => {
    const element = pdfRef.current;
    if (!element) return;

    setShowFilePrompt(false);
    setIsExporting(true);

    // Aspetta che React abbia finito di iniettare i dati nel DOM del template
    await new Promise(resolve => setTimeout(resolve, 800));

    const images = Array.from(element.getElementsByTagName('img'));
    const loadPromises = images.map(img => {
      if (img.complete) return Promise.resolve();
      return new Promise(resolve => {
        img.onload = resolve;
        img.onerror = resolve;
      });
    });
    await Promise.all(loadPromises);

    const opt = {
      margin: 0,
      filename: `${customFileName}.pdf`,
      image: { type: 'jpeg', quality: 0.98 },
      html2canvas: { 
        scale: 2, 
        useCORS: true, 
        backgroundColor: '#ffffff',
        logging: false,
        scrollY: 0, // Evita che lo scroll attuale influenzi la cattura
        scrollX: 0
      },
      jsPDF: { unit: 'mm', format: 'a4', orientation: 'portrait' },
      pagebreak: { mode: ['css', 'legacy'] }
    };

    try {
      await html2pdf().set(opt).from(element).save();
    } catch (err) {
      console.error("Errore PDF:", err);
      alert("Impossibile generare il PDF. Riprova.");
    } finally {
      setIsExporting(false);
    }
  };

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col">

      {apiQuotaError && (
        <div className="bg-red-50 border-b border-red-100 px-4 py-3 sticky top-0 z-[100] animate-in slide-in-from-top">
          <div className="max-w-4xl mx-auto flex flex-col sm:flex-row items-center justify-between gap-3">
            <div className="flex items-center gap-2 text-red-700 text-xs font-bold uppercase tracking-tight">
              <AlertCircle className="w-4 h-4" />
              <span>Limite IA. Configura la tua chiave API per continuare.</span>
            </div>
            <button onClick={handleOpenApiKeyDialog} className="bg-red-600 text-white px-4 py-1.5 rounded-lg text-[10px] font-black uppercase flex items-center gap-2 hover:bg-red-700">
              <Key className="w-3 h-3" /> Chiave API
            </button>
          </div>
        </div>
      )}

      {isExporting && (
        <div className="fixed inset-0 z-[600] bg-white/95 flex flex-col items-center justify-center p-10 text-center">
          <div className="spinner-ring mb-6"></div>
          <h2 className="text-xl font-black text-slate-900 uppercase tracking-widest">Esportazione PDF...</h2>
          <p className="text-slate-500 text-sm mt-2 font-medium">Stiamo assemblando tutte le foto e le analisi tecniche.</p>
        </div>
      )}

      {/* STRUTTURA PDF MIGLIORATA PER HTML2PDF */}
      <div id="pdf-container-wrapper">
        <div ref={pdfRef} id="pdf-template">
          <div className="pdf-header">
            <div style={{ width: '65%' }}>
              {data.logoUrl && <img src={data.logoUrl} style={{ height: '55pt', marginBottom: '8pt', objectFit: 'contain' }} alt="Logo" />}
              <h1 style={{ margin: 0, fontSize: '18pt', fontWeight: 900, color: PRIMARY_COLOR }}>STUDIO ING. SERRA</h1>
              <p style={{ margin: 0, fontWeight: 700, fontSize: '9pt', color: '#333' }}>{STUDIO_NAME}</p>
              <p style={{ margin: 0, fontSize: '7.5pt', color: '#666' }}>{STUDIO_TAGLINE}</p>
            </div>
            <div style={{ textAlign: 'right', width: '35%' }}>
              <h2 style={{ margin: 0, fontSize: '11pt', fontWeight: 900, textTransform: 'uppercase' }}>Verbale Sopralluogo</h2>
              <p style={{ margin: 0, fontSize: '8.5pt', color: '#444' }}>Data: {new Date(data.inspectionDate).toLocaleDateString('it-IT')}</p>
              <div style={{ marginTop: '8pt', padding: '4pt', background: '#f8fafc', border: '0.5pt solid #eee' }}>
                <p style={{ margin: 0, fontSize: '9pt', fontWeight: 900, color: PRIMARY_COLOR }}>{data.condoName.toUpperCase()}</p>
              </div>
            </div>
          </div>

          <div className="pdf-section-title">Relazione Tecnica Conclusiva</div>
          <div style={{ fontSize: '10.5pt', lineHeight: '1.5', textAlign: 'justify', whiteSpace: 'pre-wrap', marginBottom: '25pt', color: '#1a1a1a' }}>
            {summary || "Nessuna relazione conclusiva specificata."}
          </div>

          <div className="pdf-section-title">Elenco Rilievi Fotografici</div>
          {data.photos.map((photo, idx) => (
            <div key={photo.id} className="pdf-item">
              <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '8pt', borderBottom: '0.5pt solid #f1f5f9', paddingBottom: '4pt' }}>
                <span style={{ fontWeight: 900, fontSize: '10.5pt', color: '#334155' }}>RILIEVO {idx + 1} - {photo.category.toUpperCase()}</span>
                <span style={{ fontWeight: 700, fontSize: '8.5pt', color: '#94a3b8' }}>RIF: {photo.supplier || "DA DEFINIRE"}</span>
              </div>
              <div className="pdf-photo-container">
                <img src={photo.url} className="pdf-photo" alt={`Rilievo ${idx+1}`} />
              </div>
              <div className="pdf-desc-box">
                <p style={{ fontSize: '7.5pt', fontWeight: 900, color: PRIMARY_COLOR, margin: '0 0 3pt 0', textTransform: 'uppercase' }}>Analisi Tecnica:</p>
                <p style={{ fontSize: '10pt', margin: 0, fontStyle: 'italic', lineHeight: '1.4', color: '#334155' }}>
                  {photo.aiPolishedIssue || photo.issue || "Nessuna nota tecnica inserita per questo rilievo."}
                </p>
              </div>
            </div>
          ))}

          <div className="pdf-footer">
            <table style={{ width: '100%' }}>
              <tbody>
                <tr>
                  <td style={{ width: '60%' }}>
                    <p style={{ fontWeight: 900, fontSize: '9.5pt', margin: 0 }}>{STUDIO_NAME}</p>
                    <p style={{ fontSize: '7.5pt', color: '#94a3b8', margin: 0 }}>Documento tecnico originale non modificabile.</p>
                  </td>
                  <td style={{ width: '40%', textAlign: 'right' }}>
                    <div style={{ borderTop: '0.5pt solid #334155', width: '130pt', display: 'inline-block', marginTop: '15pt' }}>
                      <p style={{ fontSize: '7pt', color: '#64748b', textAlign: 'center', marginTop: '3pt', textTransform: 'uppercase', fontWeight: 800 }}>Firma Professionale</p>
                    </div>
                  </td>
                </tr>
              </tbody>
            </table>
          </div>
        </div>
      </div>

      <header className="bg-white border-b border-slate-200 sticky top-0 z-50 px-4 py-4">
        <div className="max-w-4xl mx-auto flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="p-2 rounded-xl bg-slate-900 shadow-md"><Briefcase className="text-white w-5 h-5" /></div>
            <h1 className="text-sm font-black text-slate-800 uppercase italic tracking-tight">Studio Ing. Serra</h1>
          </div>
          <div className="bg-slate-50 px-3 py-1 rounded-full border border-slate-100 flex items-center gap-2">
            <div className="w-1.5 h-1.5 rounded-full bg-emerald-500"></div>
            <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">A4 Report Engine</span>
          </div>
        </div>
      </header>

      <main className="flex-1 max-w-4xl mx-auto w-full p-4 sm:p-6 pb-32">
        {step === AppStep.SETUP && (
          <div className="bg-white rounded-[2.5rem] shadow-sm border border-slate-200 p-8 sm:p-12 animate-in fade-in duration-500">
             <div className="mb-10 border-b border-slate-100 pb-6 flex items-center justify-between">
                <div>
                  <h2 className="text-2xl font-black italic tracking-tighter" style={{ color: PRIMARY_COLOR }}>SOPRALLUOGO</h2>
                  <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mt-1">Dati Condominio</p>
                </div>
                <div className="bg-slate-50 p-3 rounded-2xl"><FileCheck className="w-6 h-6 text-slate-300" /></div>
             </div>

             <div className="space-y-8">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                  <div className="space-y-2">
                    <label className="text-[10px] font-black uppercase text-slate-400 ml-1">Nome Condominio *</label>
                    <input type="text" className="w-full px-5 py-4 bg-slate-50 border-2 border-slate-50 rounded-2xl focus:border-[#64a1a4] outline-none font-bold transition-all" value={data.condoName} onChange={(e) => setData({...data, condoName: e.target.value})} placeholder="Es. Condominio Italia" />
                  </div>
                  <div className="space-y-2">
                    <label className="text-[10px] font-black uppercase text-slate-400 ml-1">Data *</label>
                    <input type="date" className="w-full px-5 py-4 bg-slate-50 border-2 border-slate-50 rounded-2xl focus:border-[#64a1a4] outline-none font-bold transition-all" value={data.inspectionDate} onChange={(e) => setData({...data, inspectionDate: e.target.value})} />
                  </div>
                </div>

                <div className="space-y-2">
                  <label className="text-[10px] font-black uppercase text-slate-400 ml-1">Logo Studio</label>
                  <div className="flex flex-col sm:flex-row items-center gap-6">
                    {data.logoUrl && (
                      <div className="relative group animate-in zoom-in">
                        <img src={data.logoUrl} className="w-24 h-24 object-contain border-2 border-slate-100 rounded-2xl p-2 bg-white" alt="Preview" />
                        <button onClick={() => setData({...data, logoUrl: undefined})} className="absolute -top-2 -right-2 bg-red-500 text-white p-1 rounded-full shadow-lg transition-transform hover:scale-110"><X className="w-3 h-3" /></button>
                      </div>
                    )}
                    <label className="flex-1 w-full border-2 border-dashed border-slate-200 rounded-[1.5rem] p-8 flex flex-col items-center justify-center gap-3 cursor-pointer hover:bg-slate-50 hover:border-[#64a1a4] transition-all group">
                      <ImageIcon className="w-8 h-8 text-slate-300 group-hover:text-[#64a1a4]" />
                      <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest text-center">Carica logo professionale</span>
                      <input type="file" accept="image/*" className="hidden" onChange={handleLogoChange} />
                    </label>
                  </div>
                </div>
             </div>

             <button disabled={!isSetupValid} onClick={() => setStep(AppStep.PHOTOS)} className="w-full mt-10 text-white font-black py-6 rounded-2xl shadow-xl flex items-center justify-center gap-3 uppercase tracking-widest transition-all hover:scale-[1.01] disabled:opacity-50" style={{ backgroundColor: isSetupValid ? PRIMARY_COLOR : "#cbd5e1" }}>
                VAI AI RILIEVI <ChevronRight className="w-5 h-5" />
             </button>
          </div>
        )}

        {step === AppStep.PHOTOS && (
          <div className="space-y-8 animate-in slide-in-from-bottom-4">
            <div className="flex items-center justify-between bg-white/80 backdrop-blur-md p-4 rounded-2xl border border-slate-200 sticky top-20 z-40 shadow-sm">
              <button onClick={() => setStep(AppStep.SETUP)} className="text-slate-400 hover:text-slate-900 font-black text-[10px] uppercase tracking-widest flex items-center gap-2">
                <ChevronLeft className="w-4 h-4" /> Setup
              </button>
              <label className="flex items-center gap-2 text-white px-8 py-3.5 rounded-2xl cursor-pointer shadow-lg font-black text-xs uppercase tracking-widest transition-all hover:brightness-110" style={{ backgroundColor: PRIMARY_COLOR }}>
                <Camera className="w-4 h-4" /> Aggiungi Foto
                <input type="file" multiple accept="image/*" className="hidden" onChange={handleFileChange} />
              </label>
            </div>

            <div className="grid grid-cols-1 gap-6">
              {data.photos.length === 0 ? (
                <div className="bg-white border-4 border-dashed border-slate-100 rounded-[3rem] p-24 text-center">
                  <Camera className="text-slate-200 w-12 h-12 mx-auto mb-4" />
                  <p className="font-black text-slate-300 uppercase tracking-widest text-[10px]">Aggiungi le foto del sopralluogo per iniziare</p>
                </div>
              ) : (
                data.photos.map((photo) => (
                  <div key={photo.id} className="bg-white rounded-[2rem] shadow-sm border border-slate-200 overflow-hidden group hover:border-[#64a1a4]/30 transition-all">
                    <div className="flex flex-col md:flex-row">
                      <div className="md:w-1/3 relative bg-slate-100 min-h-[220px]">
                        <img src={photo.url} className="w-full h-full object-cover" alt="Rilievo" />
                        <button onClick={() => removePhoto(photo.id)} className="absolute top-4 right-4 p-2.5 bg-red-500 text-white rounded-xl shadow-lg hover:scale-110 transition-transform"><Trash2 className="w-4 h-4" /></button>
                      </div>
                      <div className="flex-1 p-6 space-y-4">
                        <div className="grid grid-cols-2 gap-4">
                          <div className="space-y-1">
                            <label className="text-[9px] font-black uppercase text-slate-400 block ml-1">Categoria</label>
                            <select className="w-full p-3 bg-slate-50 border-2 border-slate-50 rounded-xl text-[10px] font-black uppercase outline-none focus:border-[#64a1a4]" value={photo.category} onChange={(e) => updatePhoto(photo.id, { category: e.target.value })}>
                              {data.availableCategories.map(cat => <option key={cat} value={cat}>{cat}</option>)}
                            </select>
                          </div>
